window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["1067049"]={"book":{"id":1067049,"title":"孩子，把你的手给我","author":"[美] 海姆·G.吉诺特","translator":"张雪兰","publisher":"京华出版社","pubdate":"2004-9","isbn":"9787806009475","tags":["育儿","教育","儿童教育","沟通","子女教育","心理学","孩子把你的手给我","心理"],"memCount":6},"np":1,"pb":[23],"idx":[{"i":17142,"t":"当孩子出现问题时:要回应，而不是反应 对生气的孩子回应:方法最重要","l":"TF3-3","c":"季草集美业","g":1,"p":1},{"i":17006,"t":"不助长孩子撒谎三步法","l":"TF3-2","c":"季草集美业","g":1,"p":1},{"i":16437,"t":"用两种方法提升亲子之间的沟通","l":"TF2-4","c":"回头看见光","g":1,"p":1},{"i":16328,"t":"发怒的三个步骤","l":"TF2-3","c":"季草集美业","g":1,"p":1},{"i":16314,"t":"情绪管理","l":"TF2-1","c":"心欢喜","g":1,"p":1},{"i":15907,"t":"发怒的三个步骤","l":"TF2-3","c":"季草集美业","g":1,"p":1},{"i":15807,"t":"孩子，把你的手给我","l":"TF1-2","c":"艾玛舟","g":1,"p":1},{"i":13731,"t":"发怒的三个步骤","l":"TF1-1","c":"流沙103","g":1,"p":1},{"i":13571,"t":"《LED情绪缓解法》","l":"TF2-2","c":"王文婷Jessica","g":1,"p":1},{"i":12832,"t":"对生气孩子的回应：方法最重要","l":"TF3-2","c":"杨飞","g":1,"p":1},{"i":11814,"t":"如何表达我们的愤怒20210411","l":"TF2-2","c":"贺楚瑜","g":1,"p":1},{"i":11316,"t":"发怒的三个步骤","l":"TF1-1","c":"余铄灵","g":1,"p":1},{"i":10880,"t":"学会应对发怒","l":"TF1-1","c":"上官兰幽","g":1,"p":1},{"i":10724,"t":"青铜树沟通法","l":"TF2-2","c":"王文婷Jessica","g":1,"p":1},{"i":8267,"t":"生气的三个步骤","l":"TF2-1","c":"张璐琳","g":1,"p":1},{"i":8077,"t":"教育孩子光有爱和洞察力是不够的，教育全都体现在日常的沟通技巧","l":"TF2-2","c":"李秋红","g":1,"p":1},{"i":8005,"t":"本书的主旨是讲父母如何正确有效地与孩子沟通","l":"TF2-1","c":"李秋红","g":1,"p":1},{"i":6902,"t":"表达愤怒三步法","l":"TF2-1","c":"郭露","g":1,"p":1},{"i":6608,"t":"“限制的技巧”","l":"TF2-3","c":"王焱","g":1,"p":1},{"i":6606,"t":"“表达限制的方法”","l":"TF2-1","c":"王焱","g":1,"p":1},{"i":3991,"t":"打造小小的理财师","l":"TF2-2","c":"贺楚瑜","g":1,"p":1},{"i":3070,"t":"孩子，我们陪你快乐成长","l":"TF2-4","c":"贺楚瑜","g":1,"p":1},{"i":888,"t":"如何正确与孩子沟通","l":"TF2-2","c":"安静","g":1,"p":1}],"ms":[{"id":17142,"topic":"当孩子出现问题时:要回应，而不是反应 对生气的孩子回应:方法最重要","learn_goal":"","remark":"反应是一种当外界发生刺激时\n你的情绪的反应冲动，是不受控制的\n根本不考虑后果的一种被动行为\n而回应则是一种有意识的对应方式\n你很清楚你会怎么去做，得到什么样的结果\n是一种赋予能量的有效的良好的反应。\n所以当问题出现时\n我们要学会去回应，而不是凭本能的反应。","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍和分组、学习目标\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位伙伴大家晚上好！非常感谢大家今夜的相聚陪伴赋能，我是今天的拆书家陈芳。\u003c/p>\u003cp>三个标签简单的介绍\u003c/p>\u003cp>1. 首先我是一名美业顾问（目前有一间自己小小的工作室）\u003c/p>\u003cp>2. 我是孩子的学习提升导师（未来会专注亲子育儿类的书籍）\u003c/p>\u003cp>3. 正在努力向三级精进的二级拆书家。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>那由于后面有讨论演练环节，我先来做个简单的分组，从我的左手边两个人两个人一组可以吧，最后张瑛老师那边三个人一组，OK。\u003c/p>\u003cp>\u003cstrong>【总学习目标】\u003c/strong>\u003c/p>\u003cp>我今天的讲解有两个拆页，第一个是当孩子出现问题时：要回应，而不是反应。第二个拆页是：如何回应生气的孩子的方法。\u003c/p>\u003cp>我们都知道只有父母学会正确的回应孩子的问题，不带无礼、侮辱的反应，孩子才会愿意听取，才不会反应、反击，才能与孩子建立良好的沟通桥梁。那我们做父母也不是万能的神，总归也有与孩子发生意见不一致的时候，那今天的第二个片段将教会我们如何回应孩子生气的方法。\u003c/p>\u003cp>这两个片段是一个\u003cstrong>并列\u003c/strong>关系。\u003c/p>\u003cp>学习目标1：首先我们一起来学习第一个片段，在大家跟随我完成本次的学习后，学习者能够运用正确回应的三步法，学会正确地回应问题，而不是当问题出现时，就本能地产生反应。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003c/p>\u003cp>【拆书技能】：选择图书是实用类或理论类图书。学习者场景介绍法中，能够清晰辨别出事件、提问、影响和解决4个步骤。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>开讲前，先来段故事。我家大宝呢，从小吃饭的习惯就没有培养好，每次吃饭，饭桌前都是糊的一塌糊涂，有时候衣服上，地上也弄得很脏，这令我经常的特别烦躁和无语。前几天在家的一次晚饭，她盛汤的时候，我提醒了她几次，注意袖子别蹭到菜碗里了，话音刚落，就蹭一袖子油了。我当时也是一通怒火：“我就知道你会蹭到袖子上，每次都是。你都12岁了，这事需要我再一次次提醒吗？”这时大宝也怒怼回来，“我要你提醒了吗？”那接下来的场景基本上不是她鸡飞狗跳，就是我鸡飞蛋打了。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>大家有过类似的经历吗？你们又是怎样解决的呢？是直接用反应过激的态度说教？还是用打骂的行为？最后的解决效果如何呢？那还有没有更好的方法呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>类似这样的事情，相信很多父母与孩子都会多多少少的发生。如果没有一个合适的解决方法。父母一遇到问题，首先就是运用父母的权威去无礼羞辱的反应去否定孩子，孩子再发怒反击回来，这样只会与孩子之间的亲子关系越来越严重，而问题也没有得到实质性的解决。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>那我今天带来的这个片段就是选自于这本书《孩子，把你的手给我》。作者将教会我们，当孩子出现问题时，如何正确有效地回应，而不是过激的反应。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>现在请大家花2分钟时间，阅读手中的原文片段一。阅读完成的伙伴可以举手向我示意一下，现在开始。\u003c/p>","ratings_count":2,"texts":[{"id":21318,"quote":"\u003cp>\u003cstrong>三、阅读拆页（一个拆页的RIA总共15-25分钟）\u003c/strong>\u003c/p>\u003cp>【拆书技能】：拆页内容未超过2页图书内页，至少有一个拆页不包括how的内容，\u003cstrong>\u003cu>两个拆页是有\u003c/u>\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">逻辑关系\u003cu>的\u003c/u>\u003c/strong>\u003c/p>\u003cp>出问题时要\u003cstrong>\u003cu>回应\u003c/u>\u003c/strong>，而不是\u003cstrong>\u003cu>反应\u003c/u>\u003c/strong>\u003c/p>\u003cp>在许多家庭中，父母和孩子之间的激烈争吵有一个规律的、可预见的顺序。孩子做错了什么事，或者说错了什么话，父母对此作出无礼侮辱的反应。孩子则以更糟糕的言行来回答。父母再反击，高声恐吓，或者横暴地处罚。\u003c/p>\u003cp>一天早晨，早餐时间，七岁的纳撒尼尔在玩一个空杯子，他的父亲在看报纸。\u003c/p>\u003cp>父亲：你会打碎它的。你总是打碎东西。\u003c/p>\u003cp>纳撒尼尔：不会的，我不会打碎它的。\u003c/p>\u003cp>就在这时，杯子掉到地上摔碎了。\u003c/p>\u003cp>父亲：你就大声哭吧。你真是个笨蛋，屋里所有的东西都被你打碎了。\u003c/p>\u003cp>纳撒尼尔：你也是笨蛋，你打碎了妈妈最好的盘子。\u003c/p>\u003cp>父亲：你居然叫你父亲笨蛋？你太没礼貌了！\u003c/p>\u003cp>纳撒尼尔：你也没有礼貌，是你先叫我笨蛋的。\u003c/p>\u003cp>父亲：你不许再说话！马上站起来回你自己的房间去！\u003c/p>\u003cp>纳撒尼尔：来啊！逼我啊！\u003c/p>\u003cp>这种对其权威的直接挑战激怒了父亲，他一把抓住儿子，狠狠地打了一通。在试图挣脱时，纳撒尼尔把父亲推到了一扇玻璃门上，玻璃碎了，割伤了父亲的手。看到血，纳撒尼尔慌了，他跑了出去，直到深夜才回来。全家人都心烦意乱，那天晚上没有人能睡好觉。\u003c/p>\u003cp>纳撒尼尔是否得到教训以后不再玩空杯子，跟他得到的关于自己和父亲的消极教训比，后者对他更重要一些。问题是，这场战争是必然发生的吗？可以避免吗？或者可以用一种更聪明的方法来处理这样的事件吗？\u003c/p>\u003cp>看到儿子玩杯子，父亲可以拿走杯子，然后给他一个更适合玩的东西，例如一个球。或者当杯子打碎时，他可以帮助儿子处理玻璃碎片，顺带说一些像“杯子很容易打碎，有没有想过这么小一个杯子居然能弄得这么乱？”之类的话。\u003c/p>\u003cp>这种和气的话会让纳撒尼尔很惊讶，可能会为他闯的祸产生歉意和赎罪心理。在没有呵斥，没有巴掌的情况下，他甚至可能会在心里思考，并自己得出结论：杯子不是用来玩的。\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【I】讲解引导时，拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤等。或者【I】讲解引导时，拆书家主动给出貌似相近或相反的概念，并辨析了易混淆概念之间细微差异，从而让学习者更清晰知识点的适用边界。（达到其一即可打勾）\u003c/p>\u003cp>好的，我看到大部分伙伴都已阅读完成，没有阅读完成的也没有关系，接下来我会详细讲解。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>现在我们一起来看拆页。拆页中第一个案例，里面有一位父亲，用了一种过激反应的语言和行为去羞辱打骂了孩子是不是？最后问题也没有解决，反而弄得两败俱伤。这种做法，如果用一个词来概括，你会用什么词？\u003cstrong>（反应）\u003c/strong>\u003c/p>\u003cp>第二个案例，是作者用了举例更好的回应方式，避免了一场可能发生的战争。这种做法，如果用一个词来概括，你会用什么词？\u003cstrong>（回应）\u003c/strong>\u003c/p>\u003cp>【Why】在生活中我们经常会碰到孩子做错事情的时候，如果父母总是做出无礼，羞辱过级的反应行为，只会让孩子越来越叛逆，越来越不尊重父母。只有父母学会找到问题的根源，学会处理问题的方法，才能真正的赢得孩子的尊重。才能与孩子建立良好的亲子关系。\u003c/p>\u003cp>\u003cstrong>【概念辨析】\u003c/strong>\u003c/p>\u003cp>那到底什么是“反应”，什么是“回应”呢？这两者看上去好像没有太大的区别是不是？接下来我们来细细的区分这两个概念。\u003c/p>\u003cp>“反应”是一种当外界发生刺激时，你的情绪的反应冲动，是不受控制的，根本不考虑后果的一种被动行为。\u003cstrong>这种情绪反应，有可能是正面积极的，比如知道孩子考试成绩非常好的时候，能让我们感觉到快乐。但负面的情绪反应，会给我们造成很大的困扰。接下来的讲解和练习，我们也重点处理负面的情绪反应。\u003c/strong>\u003c/p>\u003cp>而“回应”则是一种有意识的对应方式，你很清楚你会怎么去做，得到什么样的结果，\u003cstrong>即使面临的是负面情形，我们也能做出是一种赋予能量的反应。\u003c/strong>\u003c/p>\u003cp>所以当你反应的时候，就会被事情控制着你，会有什么结果，不得而知，当你回应的时候，整个局面是在你的掌控之中的，你很清楚知道自己需要什么结果。所以我们要学会去有效的回应，而不是凭本能的反应。\u003c/p>\u003cp>那接下来为了让大家更好地理解“反应”与“回应”，我来列举几个案例，大家分辨一下什么是反应，什么是回应。\u003c/p>\u003cp>1. 孩子放学回来，你看到孩子衣服上都处是墨汁，瞬间大怒：你看看你天天回来都是脏兮兮的，你再把衣服弄这么脏，就不要回来了，我不想看到你这么脏的孩子。\u003c/p>\u003cp>请问这是“反应”还是“回应”\u003c/p>\u003cp>学习者：反应\u003c/p>\u003cp>拆书家：对的，这是\u003cstrong>我们在面临外界负面的刺激时，产生的负面的情绪冲动，所以，这属于\u003c/strong>反应。\u003c/p>\u003cp>2. 晚上孩子写作业的时候，发现文具盒里买的新钢笔不见了，你和她一起寻找时，发现书包里乱得跟鸡窝似的，你没有怒诉他书包总是这么乱，而是有序的指引他先整理好书包，或许书包整理清楚了，钢笔就能找到了呢？\u003c/p>\u003cp>请问这是“反应”还是“回应”\u003c/p>\u003cp>学习者“回应”\u003c/p>\u003cp>拆书家：对的。\u003cstrong>虽然我们受到了负面的刺激，但我们是有意识地应对了这种情形，清楚怎么说、怎么做，所以，这是\u003c/strong>回应。\u003c/p>\u003cp>3. 答应孩子这个周末带她去恐龙园玩，可是临时有工作安排，跟孩子解释，爸爸妈妈临时有事，只能约到下次了去了，孩子一听去不了，又是哭又是闹，你见孩子这么不讲道理，生气的对他怒吼道，都跟你说了，工作忙，没有时间，你再闹下次也取消。\u003c/p>\u003cp>请问这是“反应”还是“回应”\u003c/p>\u003cp>学习者：“反应”\u003c/p>\u003cp>拆书家：对，这\u003cstrong>也是我们在面临外界负面的刺激时，产生的负面的情绪冲动，所以属于\u003c/strong>反应。\u003c/p>\u003cp>4. 在接孩子放学的路上，孩子跟你说今天她的同桌一直打扰她上课，导致今天的数学课都没有听懂。\u003c/p>\u003cp>你耐心的听她诉说事情的经过，并为她今天的遭遇表示同情，耐心地跟她沟通协商解决问题。\u003c/p>\u003cp>请问这是“反应”还是“回应”\u003c/p>\u003cp>学习者：回应\u003c/p>\u003cp>拆书家：对，这是\u003cstrong>有意识地应对孩子，所以属于\u003c/strong>回应。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那我们该怎么做，才能避免在孩子出了问题的时候是正回应，而不是反应的态度呢？以下我总结了三步。\u003c/p>\u003cp>【拆书技能】：【I】讲解引导时，拆书家给出了具体行动建议或具体步骤。\u003c/p>\u003cp>\u003cstrong>【How】(反例变正例）\u003c/strong>\u003c/p>\u003cp>1. 改观点\u003c/p>\u003cp>（正如我前面的案例，一看到孩子去盛汤，我就知道袖子一定会在菜碗里糊上油。还没有发生的事，我首先就否认了孩子，这就是给后面不一定发生的事，埋下了情绪的种子，所以首先我们要有信相信孩子）\u003c/p>\u003cp>2. 说事实\u003c/p>\u003cp>（我们只需要说出我们看到的就行了，例如：妈妈看到你的袖子上粘到油了）\u003c/p>\u003cp>3. 正引导\u003c/p>\u003cp>（你看衣服上粘了油，不仅不好看了，而且还特别不好洗，我想你也不喜欢自己漂亮的衣服总是脏兮兮的是不是？那下次我们注意一下，好不好，我家姐姐已经是大姑娘了，这点小事一定能做到，妈妈相信你！）\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>那有些伙伴可能会说，不管说多少次都一样，当耳边风，不说吧又看不下去，说多了吧，她还跟你顶嘴，把你气得个半死。那为什么怎么说孩子都一样故犯呢？那到底是我们在用反应的态度在说教，还是在用正确引导的方式在回应孩子呢？想必，这才是问题的所在。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>回应三步法，不仅适用于跟孩子之间的沟通，也适用于成年人之间的沟通，但对于比较小的幼儿就不适合，太小还没有形成习惯的模式，但是可以慢慢培养。对于正处在好习惯养成阶段的5到12岁小学生就非常的适用了。\u003c/p>\u003cp>【拆书技能】：有体现出【I】环节的互动、且拆书家能精准掌控。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A2】催化应用\u003c/strong>\u003c/p>\u003cp>【拆书技能】：使用【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：1}学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事，2）学习者可以根据指令，写出自己未来的一个具体的要做的应用。（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/p>\u003cp>\u003cstrong>【A2 编剧本】\u003c/strong>\u003c/p>\u003cp>那通过我前面的讲解，相信大家已经对正确的回应有了一定的认识，以及学会去如何运用这三个方法（1.改观点2. 说事实3. 正引导）现在请大家自己编写一个未来一周可能会发生的一个小故事，故事需要有：时间，地点，人物，起因，经过，结果。\u003c/p>\u003cp>（这里特别提醒一下小伙伴，要一个人扮演两个角色，以对话的方式分享出来）。\u003c/p>\u003cp>5分钟时间，现在开始。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分伙伴都已完成，那有请哪位伙伴来分享一下他设计的故事呢？\u003c/p>\u003cp>\u003cstrong>【邀请分享】\u003c/strong>\u003c/p>\u003cp>下面请樊老师分享一下。\u003c/p>\u003cp>樊老师：\u003c/p>\u003cp>时间：未来一周的周日晚上， 吃完晚饭7点。\u003c/p>\u003cp>地点：家里，\u003c/p>\u003cp>人物：我和女儿（果果）\u003c/p>\u003cp>起因：周一她要上学，周日晚上我检查她的作业。\u003c/p>\u003cp>樊老师：我说果果把你的作业拿出来我看看，写完了没？\u003c/p>\u003cp>果果：写完了。\u003c/p>\u003cp>樊老师：你把作业拿出来我看看，你确定你写完了。\u003c/p>\u003cp>果果：我确定。\u003c/p>\u003cp>樊老师：那我们来一项一项核对，最后发现英语网上打卡作业没有做，当时我的心啊，我那个火蹭一下就起来了，我的天哪，当时我就想拍桌子。但是呢？回想起学习了陈老师正确回应三步骤，我试着去运用：\u003c/p>\u003cp>第一步：改观点，我应该先平复自己的情绪去信任孩子。\u003c/p>\u003cp>第二步：说事实，我会说，果果咱们今天这个作业，大部分都已经完成了，就剩这一项英语网上打卡没有完成，爸爸呢是希望你九点半之前能够完成，我相信你一定有能力完成这个作业。\u003c/p>\u003cp>最后结果，她在九点出头一点完成了这项作业。\u003c/p>\u003cp>\u003cstrong>【拆书家回应】\u003c/strong>好的，非常感谢樊老师的分享，让我们掌声给到樊老师。樊老师跟我们分享了她女儿写作业这样一个事情的起因经过和结果。运用了今天所学的三步骤，避免了与孩子发生一场亲子大战，而是游刃有余解决了这个问题。\u003c/p>\u003cp>【拆书技能】：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/p>\u003cp>\u003cstrong>六、总结过渡+学习目标2（1分钟）（另一个拆页的总时间是35-55分钟）\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong>\u003c/p>\u003cp>好的，听完第一个拆页的讲解，有伙伴可能会想，那如果我们已经正确的回应引导孩子，可孩子有时候还会再犯同样的错误，并且还会嫌弃我们啰嗦，偶尔也会发生一些情绪怎么办？那接下来，我们一起学习今天的第二个片段“对生气孩子的回应：方法最重要”四个步骤。\u003c/p>\u003cp>在大家跟随我完成第二个拆页学习后，学习者能够运用（行为）回应生气孩子的四步骤（澄清），去接纳孩子生气的情绪，最后引导孩子解决问题（界定）\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>现在大家手中都有一页标有自测表的纸，在进入下一个环节之前呢，我们先来做个小小的测试。请大家现在仔细阅读表格内容，回忆一下自己在遇到孩子生气的时候，你是怎么做的呢？思考后，大家可以圈出对应的分数，然后统计一下分数，看看自己的得分情况，时间是1分钟，现在开始。\u003c/p>\u003cp>\u003cstrong>七、【A1】量表自测1分钟\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【A1】技能环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的而表现。\u003c/p>\u003cp>\u003cstrong>八、【I】解释自测题1分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【解释自测题】\u003c/strong>\u003c/p>\u003cp>这个自测题的目的是帮助大家了解关于孩子在生气时，大人的一个处理问题的方式方法。得分越高，说明你平时在处理孩子情绪的时候做的很全面。\u003c/p>\u003cp>一共5道题，总分是30分，请问有没有25分以上的伙伴？\u003c/p>\u003cp>哇！29分有三位老师，说明这三位老师平时在处理孩子情绪的时候，做得非常的全面。\u003c/p>\u003cp>请问有16-25分之间的伙伴吗？\u003c/p>\u003cp>说明我们平时还是有一些解决问题的办法，但是呢，还不够全面，还有需要提升的地方。\u003c/p>\u003cp>那15分以下的伙伴，咱们也没有关系哈，相信今天的拆页讲解一定能给你带来一些新的启发和收获。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>现在请大家花2分钟的时间阅读手中的原文片段二，阅读完成的伙伴可以举手向我示意一下，现在开始。\u003c/p>\u003cp>好的，我看到大部分伙伴都已经阅读完成了，没有读完的也没有关系，接下来我会详细讲解。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":21319,"quote":"\u003cp>\u003cstrong>九、阅读拆页\u003c/strong>\u003c/p>\u003cp>【拆书技能】：拆页内容未超过2页图书内页，至少有一个拆页不包括how的内容\u003c/p>\u003cp>一对兄妹在地下室玩，突然传来什么东西被毁坏的声音，随后就是喊叫声和指责声。六岁的比利从楼梯上来，气得满脸通红，他一上来就脱口叫道：“贝特西把我的堡垒撞翻了。”他的妈妈同情地说：“哦——，那你一定非常生气了。”“我是很生气。”他转过身继续回去玩了。\u003cbr>\u003c/p>\u003cp>这是比利的妈妈第一次试着没有卷入孩子们的日常争吵中。她没有问那个最具破坏性的问题：“谁先引起的？”这样就避免了儿子讲述冤情和要求报仇。通过真实地反应儿子内心的情绪，她避免了成为孩子们的法官、检察官、执法人这些不讨好的角色。\u003cbr>\u003c/p>\u003cp>\u003cbr>在下面的事例中，一位母亲同情的评论使得和平与战争成为一线之隔。九岁的大卫不想去看牙医，他很生气，激怒了他的姐姐蒂娜，她对他说：“噢，大卫，长大点！”大卫更生气了，行为变得更加令人讨厌。\u003cbr>\u003cbr>她的妈妈对蒂娜说：“大卫今天很烦，他担心去看牙医。现在他需要我们所有人的体谅。”就好像变魔法一样，大卫马上安静下来，他去看了牙医，没有再抱怨。妈妈的回应是针对大卫烦躁的心情，而不是他让人讨厌的行为，这使得大卫感到放松多了，因此也就不再那么讨厌了。\u003cbr>\u003cbr>在这个小事件里，帮助孩子平息怒气和遭受挫折的两种方法正好形成对照，一种是使怒火更盛，一种是消除怒气。\u003cbr>\u003c/p>\u003cp>\u003cstrong>汤姆和他的朋友吉姆，两个人都才三岁，他们在玩玩具木琴。吉姆的音捶卡住了，生气地哭了起来。他的妈妈警告他说:“你没有理由大哭大闹的，我不会给你修音锤，除非你停止尖叫。”吉姆继续哭闹，于是他的妈妈拿走了玩具。这一下，吉姆大发脾气，场面颇为壮观。\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>与吉姆的例子形成对照的是，汤姆的音锤也卡住了，他也哭了起来，他的妈妈对他说：“你哭是因为音锤卡住了，我们需要修好它。”哭声停止了。现在，无论什么时候音锤被卡住，汤姆都不会再哭，而是拿过去让妈妈修理。\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>吉姆的妈妈用的方法是谩骂、威胁、责备和惩罚，而汤姆的妈妈则是指出问题所在，然后给出解决问题的建议。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>十、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】：在未包含how拆页的【I】环节，拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤等。或者【I】讲解引导时，拆书家主动给出貌似相近或相反的概念，并辨析了易混淆概念之间细微差异，从而让学习者更清晰知识点的适用边界。（达到其一即可打勾）\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段里，\u003cstrong>作者通过几个案例\u003c/strong>，向我们进行了一个明显的对比是不是？同时也向我们展示了两种不同处理问题的方法，会得到两种不一样的结果是不是？所以我们在面对情绪的时候，首先要学会去接纳情绪，表达感受，然后弄清楚问题的根源。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>生活中我们经常会遇到孩子，家人朋友等有情绪的时候，那我们通常是怎么处理的呢？那有些人自己本身就是个暴脾气，性格也比较直的人，遇到不好好说话的，肯定会跟随他的情绪一起爆发，你不好好说话，我也懒得跟你好好说，那这种以暴制暴无疑就是火上浇油是不是？所以我们还是要找到合适的学习方法，只有这样才能真正的解决问题的本质。大家认同吗？OK!\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>那面对生气的孩子，我们该怎样去回应呢？我总结了以下四个步骤。\u003c/p>\u003cp>第一步：接纳情绪\u003c/p>\u003cp>（真诚地去接纳他的感受，“你很生气，这确实让人很生气”）\u003c/p>\u003cp>第二步：\u003cstrong>移情表达\u003c/strong>\u003c/p>\u003cp>（我非常理解你现在的感受，难怪你会这么生气。或者列举一二自己曾经和他一样的经历与孩子产生共情，\u003cstrong>让孩子知道，你能理解他的感受\u003c/strong>）\u003c/p>\u003cp>第三步：发现问题\u003c/p>\u003cp>（耐心地询问一下孩子发生了什么事啊？引导他把事情的经过讲述一下）\u003c/p>\u003cp>第四步：\u003cstrong>给出建议\u003c/strong>\u003c/p>\u003cp>（\u003cstrong>作为成年人，我们在自己的成长中积累了经验。所以，如果孩子愿意，我们\u003c/strong>可以和孩子一起想办法，给他提供\u003cstrong>建议\u003c/strong>，征求他是否愿意接纳）\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>为了让大家更好的理解并应用，下面我结合我生活中与孩子的案例运用这四个步骤来进行分享。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>上周末，在家晚饭后的闲暇时光，大家各干各的。平时我家小宝特别喜欢收集纸盒子，搞一些自己的小创意，每次家里只要有各种快递盒子，她都想宝贝一样收集着。那天晚饭后，她也像往常一样，一个人在那据啊剪啊贴啊粘啊，当时可能是有个东西不好粘，老是倒，她就急了“怎么回事啊，怎么就粘不住呢？我要撕了你，不要了”一边自己把自己搞了半天的作品推到，一边瘫坐在一堆她的纸堆里哭。\u003c/p>\u003cp>那当时呢，我是这样做的。\u003c/p>\u003cp>我：妹妹，妈妈刚刚看到你把做的很长时间的创作推毁了，我看出来了，你很生气。\u003c/p>\u003cp>女儿：它太讨厌了，总是倒（接纳情绪）\u003c/p>\u003cp>我：也是哦，你辛辛苦苦做了这么久，它粘不上，老是倒下来，是我我也会很生气。（\u003cstrong>移情表达\u003c/strong>）\u003c/p>\u003cp>我：那你需要妈妈来跟你一起看看到底是哪里出了问题好不好？\u003c/p>\u003cp>女儿：你看这个那个……它老是粘不上去，我一松手它就倒了。\u003c/p>\u003cp>我：原来是这样的，那我问你上面那个盒子大不大？\u003c/p>\u003cp>女儿：嗯，很大\u003c/p>\u003cp>我：那下面这个盒子小不小？\u003c/p>\u003cp>女儿：太小了\u003c/p>\u003cp>我：所以啊，你看下面那个纸盒子就像一只小小的蜗牛，上面那个呢，就像一个大大的房子，那小蜗牛肯定没有那么大力气背起这座房子是不是？\u003cstrong>（发现问题）\u003c/strong>\u003c/p>\u003cp>女儿：好像是的\u003c/p>\u003cp>我：那妈妈建议把上面那个大的换成一个小一点的纸盒，妈妈帮你扶着，你来粘好不好？\u003c/p>\u003cp>这时女儿突然：妈妈我有个好主意……然后就开始自告奋勇……\u003c/p>\u003cp>我：这个主意太棒了！（\u003cstrong>给出建议\u003c/strong>）\u003c/p>\u003cp>那就这样问题解决了，而且还激发了她新的灵感。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>那有些伙伴可能会说，听到孩子发火生气，哭哭啼啼的就来气，有什么话不能好好说呢，本来很好解决的问题，非得把大人激怒。确实是啊，有什么不能好好说呢？当我们自问这句话的时候，是什么感觉呢？那我们有在好好说话吗？所以啊，想要与孩子建立一个良好的沟通桥梁，大人不仅要先学会平稳自己的情绪，还要学会合适的方法，才能平息孩子的情绪，才能帮助孩子培养解决问题的能力。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>对生气孩子回应的四步骤，不仅适用于跟孩子，也适用于跟关系比较熟悉的家人、朋友、同事。前提是我们自己要先学会平稳自己的情绪，才能帮助到他人，否则就是推波助澜，点火加油。\u003c/p>\u003cp>【拆书技能】：在未包含how拆页的【I】环节，拆书家给出了与学习目标相关的具体行动建议或具体步骤。\u003c/p>\u003cp>【拆书技能】：有体现出【I】环节的互动、且拆书家能精准掌控。\u003c/p>","interaction":"\u003cp>\u003cstrong>十一、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>【拆书技能】：在未包含 how 拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。其中，微行动学习环节包含了 5 个步骤：1）拆书家引导学习者提出，并明确一个需要解决的问题；2）拆书家引导学习者分组讨论问题本质；3）拆书家引导学习者明确出问题本质；4）拆书家引导学习者分组讨论问题解决方案；5）请每组学习者代表讲解自己组的讨论成果。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，那第二个片段的讲解解决孩子生气四步骤就到这里，为了让大家更深刻的理解及学会应用这四个步骤，那接下来我们要进行一个微行动学习。\u003c/p>\u003cp>\u003cstrong>【重新分组】\u003c/strong>\u003c/p>\u003cp>我们要用大组讨论的方式，分为两组。前面五个人一组，后面四个人一组，为了保证每组的学习效果，我现在需要选出每组的组长和记录员以及发言官。\u003c/p>\u003cp>这样吧，大家伸出自己的左手的食指，听我的指令，我说1.2.3大家就指向你觉得合适的人选，\u003c/p>\u003cp>拆书家：好，1.2.3，哈哈哈，现在大家能确定下来了吗？\u003c/p>\u003cp>第一组：丁舵组长，丹丹老师记录员，驰驰老师发言官。\u003c/p>\u003cp>第二组：樊老师组织，冯老师记录员，李老师发言官。\u003c/p>\u003cp>微行动学习步骤1：拆书家引导学习者提出，并明确一个需要解决的问题；\u003c/p>\u003cp>\u003cstrong>【拆书家提问】\u003c/strong>\u003c/p>\u003cp>好的，在一片欢乐祥和的笑声中，我看到大家都非常开心的选出各组的组长和记录员、发言官，那现在，请大家先回到我这里。\u003c/p>\u003cp>那通过我刚才的讲解，大家学习了“回应生气孩子的四个步骤”（1.接纳情绪 2.\u003cstrong>移情表达\u003c/strong> 3.发现问题 4.\u003cstrong>给出建议\u003c/strong>）接下来结合我们以往生活中遇到的问题，大家觉得这四个步骤中，哪一个步骤最难实施？\u003c/p>\u003cp>现在给到大家5分钟时间在小组内讨论，一会儿请每组的记录员进行一个汇报分享。大家现在可以开始。\u003c/p>\u003cp>\u003cstrong>【小组分享】\u003c/strong>\u003c/p>\u003cp>好的，时间到，我看到大家都讨论的差不多了哈。\u003c/p>\u003cp>有请第一组的记录员分享一下，你们觉得哪一步最难？\u003c/p>\u003cp>第一组：驰驰老师：我们觉得第一步“接纳情绪”最难。\u003c/p>\u003cp>拆书家：那第二组你们觉得哪一步最难呢？\u003c/p>\u003cp>第二组；李老师：我们这组也觉得“接纳情绪“最难。\u003c/p>\u003cp>\u003cstrong>【明确问题】\u003c/strong>\u003c/p>\u003cp>那现在两组的伙伴得出的结论是一样的，都觉得第一步接纳情绪最难。\u003c/p>\u003cp>那么，我们要解决的问题就是，如何接纳孩子的情绪？\u003c/p>\u003cp>微行动学习步骤2：拆书家引导学习者分组讨论问题本质；\u003c/p>\u003cp>\u003cstrong>【讨论问题的本质】\u003c/strong>\u003c/p>\u003cp>让大家觉得难的本质原因是什么？我们只有找到问题的根源，才那找到解决的方法，现在请大家在小组继续讨论，现在给到大家8分钟左右时间，请每组的组长负责一下尽量给到每位伙伴2分钟左右的分享，辛苦记录员记录到白纸上。\u003c/p>\u003cp>好的，时间到，哪一组愿意来分享一下你们讨论的结果？那我们有请第一组先来分享一下吧，有请驰驰老师：\u003c/p>\u003cp>1. 不考虑后果。\u003c/p>\u003cp>2. 理性脑的速度比感性脑的速度慢。\u003c/p>\u003cp>3. 经验族（觉得自己吃的盐比孩子吃的饭都多）。\u003c/p>\u003cp>第二组，你们觉得接纳情绪最难的原因有哪些？有请发言官李老师给大家分享：\u003c/p>\u003cp>1. 权力族（我是你爹，你必须得听我的）。\u003c/p>\u003cp>2. 自我情绪认知（对自己的情绪掌控不好）。\u003c/p>\u003cp>3. 自我修养（学习如何做一个好爸爸、好妈妈）。\u003c/p>\u003cp>微行动学习步骤3：拆书家引导学习者明确出问题本质；\u003c/p>\u003cp>\u003cstrong>【拆书家回应】\u003c/strong>\u003c/p>\u003cp>通过两组的讨论，得出的结果，接纳情绪的几个难点，我概括一下，也写在白板上了。\u003c/p>\u003cp>大家觉得这几点，哪一个是引起这个问题的最本质的原因？只有找到问题最本质的原因，才能找到问题的解决方法。下面请大家回到小组里继续讨论一下，引起这个问题最本质的原因是什么？讨论时间 8 分钟，现在开始。\u003c/p>\u003cp>\u003cstrong>【一组分享】\u003c/strong>\u003c/p>\u003cp>驰驰老师：我们组认为最本质的原因是理性脑的速度比感性脑的速度慢。\u003c/p>\u003cp>\u003cstrong>【二组分享】\u003c/strong>\u003c/p>\u003cp>李金莲老师：我们认为最本质的原因是爸爸妈妈的自我修养不足。\u003c/p>\u003cp>\u003cstrong>【明确问题本质】\u003c/strong>\u003c/p>\u003cp>我们两组意见不一，在这两个原因中，哪一个是问题真正的本质？最后只能得出一个本质原因。\u003c/p>\u003cp>\u003cstrong>张瑛\u003c/strong>：我来补充一下。理性比感性反应慢，这个是先天的，是客观存在的情况，如果我们接下来讨论这个问题的话，是没有答案的，或者会非常难。对我们学习者来说，家长的自我修养和认知是可以提升的。所以，我们认为最本质的原因是家长的自我修养不足。\u003c/p>\u003cp>【拆书家】请问第一组的伙伴，你们认同张瑛老师最后的陈述吗？（一组表示认同）好的，那我们就本质原因达成了一致，也就是家长的自我修养不足。\u003c/p>\u003cp>微行动学习步骤4：拆书家引导学习者分组讨论问题解决方案；\u003c/p>\u003cp>\u003cstrong>【讨论解决方案】\u003c/strong>\u003c/p>\u003cp>现在我们已经很清楚要解决的问题是如何接纳孩子的情绪，其中最本质的原因是家长的自我修养不足。那接下来我们还是在小组继续讨论怎么解决这个问题。现在给到大家6分钟时间，辛苦记录员把解决的方案记录下来。\u003c/p>\u003cp>微行动学习步骤5：请每组学习者代表讲解自己组的讨论成果。\u003c/p>\u003cp>\u003cstrong>【分享讨论方案】\u003c/strong>\u003c/p>\u003cp>好的，时间有限，我们请第二组的记录员李老师来分享一下讨论出来的解决方案吧：\u003c/p>\u003cp>李金莲老师：\u003c/p>\u003cp>1. 学习更多的育儿知识。\u003c/p>\u003cp>2. 修身养性，提升自己的兴趣爱好。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>我们最终讨论出来了接纳情绪的方法，通过大家的分析，讨论出问题的六个原因，并且总结出一个最根本的原因，找到了解决问题的方法。大家对今天讨论出来的结果是大家想要的吗？\u003c/p>\u003cp>学习者：是的，是的。\u003c/p>\u003cp>\u003cstrong>十二、【A2】催化应用\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：1}学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事，2）学习者可以根据指令，写出自己未来的一个具体的要做的应用。（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/p>\u003cp>那我们拆书学习的目的是为了拆为己用，现在给大家步骤个作业，未来一周，你的孩子可能会发生一些闹心的事情，发生情绪问题，需要运用到今天所学的，回应生气孩子的四个步骤（1. 接纳情绪、2. \u003cstrong>表移情表达\u003c/strong>、3. 发现问题、4. \u003cstrong>给出建议\u003c/strong>）把你是怎么跟孩子进行沟通交流的过程记录下来，然后微信发给我，再次谢谢大家！\u003c/p>\u003cp>【拆书技能】：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/p>\u003cp>\u003cstrong>十三、总结语\u003c/strong>\u003c/p>\u003cp>我们一起来回顾一下今天所学的内容，首先学习的是当孩子出现问题时：要回应而不是反应三步法：1.改观点2.说事实3.正引导。教会我们当孩子出现问题时，需要我们正确有效的良好回应，而不是过激的反应。第二个当孩子生气时回应四步骤：1.接纳情绪2.\u003cstrong>移情表达\u003c/strong>3.发现问题4.\u003cstrong>给出建议\u003c/strong>。\u003c/p>\u003cp>希望大家回去以后能多多运用，正确的引导孩子，帮助孩子在成长的人生道路上体验到被尊重理解的价值感。\u003c/p>\u003cp>每次拆解育儿类书籍，结束的时候，我都会特别的感慨这样一句话“都说父母是孩子的一面镜子，你想要孩子成为怎样的人，首先我们就要做怎样的父母”。\u003c/p>\u003cp>好的，我今天的讲解就到这里，感谢大家的积极配合与聆听！\u003c/p>\u003cp>【拆书技能】：总时长没有少于50分钟，没有超过80分钟。一个拆页\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">15-25分钟，另一个拆页35-\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">55分钟。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1704807714000,"updated_at":1706160675000,"ria":true},{"id":17006,"topic":"不助长孩子撒谎三步法","learn_goal":"","remark":"当孩子说谎时\n特别是谎言很明显时\n可孩子依然坚持说:我没有，我不知道……\n你会像侦探一样设圈逼迫孩子坦白承认?\n还是会做一位智慧的父母\n学会怎样不助长孩子说谎的坏习惯\n提升与孩子之间的信任度\n建立孩子的安全感","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍和分组\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位伙伴大家晚上好！非常感谢大家今夜的相聚陪伴赋能，我是今天的拆书家陈芳。\u003c/p>\u003cp>三个标签简单的介绍一下我自己：\u003c/p>\u003cp>1. 首先我是一名美业顾问（目前有一间自己小小的工作室）\u003c/p>\u003cp>2. 我是孩子的学习提升导师（未来会专注亲子育儿类的书籍）\u003c/p>\u003cp>3. 正在努力向三级精进的二级拆书家。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>那由于后面有讨论演练环节，我先来做个简单的分组。我看大家从我的左手边起两两一组，最后三位老师为一组。\u003c/p>\u003cp>\u003cstrong>二、图书介绍、学习目标\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习者场景介绍法中，能够清晰辨别出事件、提问、影响和解决4个步骤。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>那开讲前呢，我给大家讲个小故事。前几天我家小宝生病发烧了，还有些轻微的肺炎。生病期间的那几天呢，我特别注意她的饮食，一些生冷甜的食物都在控制不让吃。但是大人嘛也不能时时刻刻盯着她，我们总归有自己忙的时候。生病第四天，我去忙店里了，中午我回家给她爷俩做饭时，发现小宝嘴角糊着巧克力残渣，我去冰箱一看，确实少了好几颗。\u003c/p>\u003cp>我就问了小女儿欣语：你是不是吃巧克力啦？\u003c/p>\u003cp>女儿回答：没有啊，我不喜欢吃巧克力。\u003c/p>\u003cp>我：那冰箱里的巧克力怎么少了好几颗啊？\u003c/p>\u003cp>女儿回答：那也不一定是我吃的啊，爸爸也在家，你怎么不问他呢？\u003c/p>\u003cp>我：现在只想知道巧克力怎么少了一些。\u003c/p>\u003cp>女儿回答：我也不知道。\u003c/p>\u003cp>我：可是我明明看到某个小孩嘴巴旁边还有巧克力渣渣。我跟你说过了，这几天不能吃巧克力，会加重咳嗽，如果再严重了，你就要住院治疗了。你明明偷吃了还说慌。这时女儿终于崩不住，哇哇大哭了。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>大家是否也有过这样的经历呢？你明明已经通过一系列的观察，已经发现孩子在撒谎了，可依然还要扮演侦探和检查官的角色去刨根问到底呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>其实无论是我们大人还是孩子，都很讨厌被别人审问，特别是孩子已经感觉到了父母已经知道答案了，而大人还要一步步去设套设圈逼迫她们在笨拙和尴尬中去坦白，那这样做的结果只会让孩子今后遇到问题越来越不会说真话。因为她们不知道会换来什么结果。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>我们作为父母又该如何去学会不助长孩子说慌的毛病呢？今天我要跟大家分享的这本书的片段就是选自《孩子，把你的手给我》一书中，将教会我们如何正确有效地不助长孩子说慌。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在大家跟随我完成本次拆页学习后，学习者能够运用如何不助长孩子说谎四个步骤去有效对待孩子说谎的策略，从而避免孩子以后说谎。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>现在大家手中都有一页标有自测表的纸。在进入下一个环节之前呢，我们先来做个小小的测试，请大家现在仔细阅读表格内容，回忆一下自己在遇到孩子说谎时，你是怎么去思考和行动的呢？思考后，大家可以圈出对应的分数，然后统计一下分数，看看自己的得分情况，时间是1分钟，现在开始。\u003c/p>\u003cp>\u003cstrong>三、【A1】量表自测\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【A1】环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现。\u003c/p>\u003cp>\u003cstrong>四、解释自测题\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分伙伴都已经打好分了。\u003c/p>\u003cp>请问有25分以上的伙伴吗？\u003c/p>\u003cp>哇！宋老师好厉害啊，说明宋老师平时是非常关注孩子说谎行为，并能很好的去处理，让我们掌声给到某老师！\u003c/p>\u003cp>请问有18-25之间分数的吗？\u003c/p>\u003cp>好的，我看到陈老师也比较重视这个问题。说明大家平时还是比较重视这个问题，也能找出一些办法应对。\u003c/p>\u003cp>18分以下的伙伴今天来对了。\u003c/p>\u003cp>好的，也没有关系，那过去我们遇到这样的问题，找不到更好的方法去引导孩子，那希望今天我的分享能给大家带来一些启发和帮助。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>现在请大家花2分钟的时间阅读手中的原文拆页。阅读完成的伙伴可以举手向往示意一下，现在开始。\u003c/p>","ratings_count":1,"texts":[{"id":21146,"quote":"\u003cp>\u003cstrong>五、阅读拆页\u003c/strong>\u003c/p>\u003cp>【拆书技能】：选择图书是实用类或理论类图书，为\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">why或者\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">what的内容，或\u003ca href=\"https://links.jianshu.com/go?to=https://%E6%97%A0\">原书一个完整的案例。\u003c/p>\u003cp>七岁的昆廷打碎了父亲送给他的一辆新的玩具小卡车，他吓坏了，把碎片都藏在地下室里。当父亲发现卡车残片时，他很生气，问了几个问题，最后导致了一场激烈的争吵。\u003c/p>\u003cp>父亲：你的新卡车呢？\u003c/p>\u003cp>昆廷：在什么地方吧。\u003c/p>\u003cp>父亲：我没看见你玩它。\u003c/p>\u003cp>昆廷：我不知道它在哪儿。\u003c/p>\u003cp>父亲：去找，我想看看。\u003c/p>\u003cp>昆廷：可能卡车被什么人偷走了。\u003c/p>\u003cp>父亲：你这个该死的说谎的孩子！你打碎了卡车！别以为你能混过去，如果有什么让我厌恶的事情，那就是说谎的人！\u003c/p>\u003cp>这是一场不必要的战争。昆廷的父亲不应该偷偷扮演侦探和检察官的角色，不应该称自己的儿子是个说谎的孩子，如果昆廷的父亲这样说会对他的儿子有帮助得多：“我看到你的新卡车坏了，它不经玩，真遗憾，你真的很喜欢它。”\u003c/p>\u003cp>孩子可能因此获得有价值的教训：爸爸能够理解。我可以告诉他我闯的祸。我必须更好地保管他的礼物，我应该更小心点。\u003c/p>","explains":"\u003cp>\u003cstrong>六、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【I】环节拆书家有进行简短互动，并能精确控场。\u003c/p>\u003cp>好的，我看到大部分伙伴已经阅读完成。没有读完的也没有关系，接下来我会详细讲解。\u003c/p>\u003cp>\u003cstrong>【What】（简短互动）\u003c/strong>\u003c/p>\u003cp>1. 大家遇到过片段里这样的问题吗？\u003c/p>\u003cp>答：有的。\u003c/p>\u003cp>2. 大家从这个片段看到了什么让我们讨厌的事情？\u003c/p>\u003cp>答：小孩说谎。\u003c/p>\u003cp>答：昆廷的爸爸已经知道答案了，还要一步步去责问这确实是很令人厌恶的事。\u003c/p>\u003cp>3. 那你认同昆廷的爸爸这样扮演侦探检察官的角色去处理问题吗？\u003c/p>\u003cp>答：不赞同。\u003c/p>\u003cp>好的，通过大家的回答，我已经很明确大家很讨厌这种明知答案，还要去设套把孩子陷入尴尬境地之中。确实让人很讨厌。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>那我们为什么要学习这个片段呢？因为小孩往往不是主动想说谎的。有时候，是出于害怕、担心等心理，才想用说谎来掩饰的。如果父母不是缓解孩子面临的压力，而是真的像小孩害怕、担心的那样去做，就印证了小孩的担心，实质上是在助长小孩说谎。\u003c/p>\u003cp>\u003cstrong>【不这样做的坏处】\u003c/strong>\u003c/p>\u003cp>如果不运用今天的方法呢？当孩子在说慌时，父母很可能会很生气，尤其是谎言很明显，脸上、衣服上都是证据时，孩子依然说我没有啊，不知道啊，这些确实会让人很生气。\u003c/p>\u003cp>那如果我们用设圈套或者打骂的方式方法去处理，只会把孩子逼到更尴尬的处境，只会进一步激化矛盾升级，从而引发更多激烈的战争。伴随孩子的成长，他会越来越叛逆，越来越不敢说真话，越来越不信任父母。因为他没有安全感。\u003c/p>\u003cp>\u003cstrong>【How】（反例变正例）\u003c/strong>\u003c/p>\u003cp>那我们该怎样做才能不助长孩子说谎的坏毛病，不仅不让矛盾激化，并且还能与孩子营造良好的亲子关系，提升孩子的信任度和安全感，让孩子获得更有价值帮助呢？以下我总结了四个步骤。\u003c/p>\u003cp>\u003cstrong>1. 控制情绪\u003c/strong>\u003c/p>\u003cp>首先我们需要稳定自己的情绪，不要一副兴师问罪、鱼死网破的态度去质问。\u003c/p>\u003cp>\u003cstrong>2. 说出事实\u003c/strong>\u003c/p>\u003cp>不要设圈、设套的一步步去逼迫孩子说出真相，直接说出看到的就行了。\u003c/p>\u003cp>例如：妈妈看到冰箱里的巧克力少了，同时看到你嘴巴旁边有巧克力的印子。\u003c/p>\u003cp>\u003cstrong>3. 说出感受\u003c/strong>\u003c/p>\u003cp>比如，妈妈很担心，吃了巧克力会加重咳嗽。妈妈看到你生病咳嗽、发烧痛苦的样子，也很难受。\u003c/p>\u003cp>\u003cstrong>4. 给予相信\u003c/strong>\u003c/p>\u003cp>比如，我会说，妈妈还是相信你在知道什么时候适合吃什么样的食物。然后，我会给孩子一个有力量的拥抱。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>那有些伙伴可能会说，我可以允许孩子犯错，但绝不允许孩子说谎，因为诚实是基本的品质。听到孩子说谎就气不打一处来，还有心情控制情绪一步步来；那甚至还有更过分的家长说，要打就一顿打好，打得他再也不说谎。\u003c/p>\u003cp>但是，大家想过没有，孩子为什么会说谎？其他一个原因就是害怕在做错事时被父母批评、打骂。如果我们打骂，那正好印证了孩子的担心。孩子下次只会想怎么把谎撒得更圆一些，因为他仍然感到害怕。\u003c/p>\u003cp>如果我们接受已经发生的事实，让孩子知道我们关心的是他的成长，愿意和孩子一起面对已经发生的错误，寻求改善，这样才能打消孩子的害怕心理，做错事时不是害怕父母，而是愿意向父母求助。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>这个方法适用于有一定理解能力的学龄儿童及未成年子女。\u003c/p>","interaction":"\u003cp>\u003cstrong>七、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【A3】环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那接下来为了让这个方法能更好的学以致用，我们来进行一个演练环节。现在请大家来演练这样一个场景。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>刚刚期中考试结束，想必很多家长比较关注孩子的考试成绩。今天放学你的孩子乐乐拿了一张数学成绩单回来给你看，你一看哟……不错嘛96分，你很是满意。但你越看这个9，越像是有点问题，你带着疑惑私聊了数学老师，才知道孩子私自把7改成了9。你得知后怒火冲天，但你并没有当面羞辱拆穿他，而是用了今天所学的四个步骤去跟孩子进行了交流和沟通。\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp>现在请大家在各自小组内讨论，然后分配好角色，一位扮演家长，一位扮演孩子乐乐。运用这四个步骤来进行演练，时间是4分钟，一会儿请一组的小伙伴来演练一下，现在开始。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，时间到，我看到大家讨论的很热烈哈，有没有哪一组的小伙伴愿意自告奋勇的演练一下。\u003c/p>\u003cp>好的有请宋老师、陈老师这一组。\u003c/p>\u003cp>陈晓庆老师：妈妈\u003c/p>\u003cp>宋亚伟老师：乐乐\u003c/p>\u003cp>妈妈：咦，96 分啊。乐乐你挺厉害的嘛，进步很大啊。\u003c/p>\u003cp>乐乐：嗯。\u003c/p>\u003cp>妈妈：乐乐，不对啊。我看这分数，怎么错题还是不少呢？是老师算错了吗？我来看一看群里的聊天记录，好像我今天在群里看到分数了。哦，乐乐，我看到群里统计的分数是 76 分。（\u003cstrong>控制情绪，陈述事实\u003c/strong>）\u003c/p>\u003cp>乐乐：（沉默）\u003c/p>\u003cp>妈妈：我们来看一下试卷里，到底是错了哪些题目。这一题，还有这一题，你来看看，是因为粗心大意才错的吧？你拿到试卷后，有没有分析一下？这道题你会做吗？\u003c/p>\u003cp>乐乐：会的。\u003c/p>\u003cp>妈妈：那你觉得是什么原因错的。\u003c/p>\u003cp>乐乐：我也不知道啊。我算出来就是这样的。我本来会算这个的。\u003c/p>\u003cp>妈妈：妈妈很相信你的。你看这个 20+50，你怎么会做不出来呢？你看前两天做的 100 以内加减法，你都做得很好。\u003c/p>\u003cp>乐乐：我算错了。\u003c/p>\u003cp>妈妈：哦，那就是粗心大意才错了。妈妈看到你因为粗心丢了这样的分数，妈妈也很难受啊。（\u003cstrong>说出感受\u003c/strong>）你自己是不是也觉得很可惜啊？分数就这样丢了。\u003c/p>\u003cp>乐乐：是的。\u003c/p>\u003cp>妈妈：没事啊，下次咱们睁大眼睛看好题目。考试的时候一定要逐字逐句看每一项要求。因为试卷上每一个字，都有它的要求。不要做得太快，时间是够的。\u003c/p>\u003cp>乐乐：知道了。\u003c/p>\u003cp>妈妈：妈妈相信你会吸取教训，下次考得更好。加油。（\u003cstrong>给予相信\u003c/strong>）\u003c/p>\u003cp>乐乐：嗯。\u003c/p>\u003cp>\u003cstrong>【拆书家回应】\u003c/strong>\u003c/p>\u003cp>太棒了，四个步骤都运用了。没有因为不信任孩子跟孩子发生冲突，没有层层剥问，导致孩子情绪激动、大家也激动。方法运用得很到位。\u003c/p>\u003cp>感谢宋老师和陈老师的精彩演绎，请大家再次献上掌声。\u003c/p>\u003cp>【拆书技能】：使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点进行小组讨论并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/p>\u003cp>\u003cstrong>八、【A2】催化应用\u003c/strong>\u003c/p>\u003cp>【拆书技能】：【A2】环节指令清晰，学习者可以根据指令，写出自己未来的一个具体的要做的应用。（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/p>\u003cp>那刚刚也给大家讲解了这么多，现场的伙伴也进行了演练，那接下来我们可以把今天所学的如何不助长孩子说谎的四个步骤带回家。可以跟身边的朋友分享；如果下一周孩子有说谎的行为，不妨学以致用一下，那下周请各位老师把作业微信发给我一下哦，谢谢！\u003c/p>\u003cp>李老师反馈：\u003c/p>\u003cp>\u003cstrong>九、总结\u003c/strong>\u003c/p>\u003cp>最后总结一下今天我们一起学习了如何不助长孩子说谎的四个步骤，我们一起来回顾一下：1.控制情绪、2. 说出事实、3. 说出感受、4. 给与相信。\u003c/p>\u003cp>当孩子出现这一不良行为时，作为家长的我们更多的是需要反醒自己的行为，为什么孩子会一而再再而三说谎呢？只有我们与孩子建立了安全的，相互信任的桥梁了，孩子才不会惧怕说真话。好的，我的分享就到这里，谢谢大家！\u003c/p>\u003cp>\u003cstrong>【拆书技能】：\u003c/strong>总时长没有少于20分钟，没有超过25分钟。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1701914395000,"updated_at":1702257292000,"ria":true},{"id":16437,"topic":"用两种方法提升亲子之间的沟通","learn_goal":"","remark":"畅销美国500多万册的教子经典，以31种语言畅销全世界，彻底改变父母与孩子沟通方式的巨著。\n\n","level":"TF2-4","duration":53,"status":30,"type":0,"chaishujia":{"username":"回头看见光","city":"襄樊"},"club":{"name":"襄阳朗瑟分舵","city":"襄樊"},"prologue":"\u003cp>\u003cstrong>环节1：开场\u003c/strong>\u003c/p>\u003cp>大家好，我是杨蓉，是一名新手拆书家，我的三个标签是：\u003c/p>\u003cp>1、中医养生践行者。用中医养生的方法让自己瘦身30斤\u003c/p>\u003cp>2、拆书家，正在努力冲破2-4 的一级拆书家。\u003c/p>\u003cp>3、三年级宝妈，暑假结束，我的女儿该上三年级了。\u003c/p>\u003cp>\u003cstrong>【主题介绍】\u003c/strong>\u003c/p>\u003cp>欢迎大家参加我的TF2-4拆书晋级活动，我今天拆书的主题是亲子沟通。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>在正式开始之前呢，为了便于接下来的学习和讨论，我们根据现场实际情况来进行分组：李老师和左老师一组，杨老师和陈老师一组\u003c/p>\u003cp>\u003cstrong>环节2：FAB图书介绍\u003c/strong> \u003c/p>\u003cp>\u003cstrong>【F特征】\u003c/strong> \u003c/p>\u003cp>今天我选择的拆页来自于《孩子，请把你的手给我》，是畅销美国500多万册的教子经典，以31种语言畅销全世界，彻底改变父母与孩子沟通方式的巨著。\u003c/p>\u003cp>这本书的作者是美国作家海姆.吉诺特，是著名的儿童心理学家，儿科医生，一生致力于儿童心理学的研究以及对父母和教师的教育。\u003c/p>\u003cp>我们众所周知的著名畅销书《正面管教》《如何说孩子才会听，如何听孩子才会说》的作者都听过他的课。\u003c/p>\u003cp>\u003cstrong>【A优势】\u003c/strong>\u003c/p>\u003cp>市面上有很多介绍亲子沟通的书籍，大多侧重技巧，和其他同类书籍不同之处是，这本书更关注于父母和孩子心理，书里不仅有很多亲子沟通类的技巧让亲子交流不费力，更有很多方法引导父母学会从心理学的角度化解父母子女间的隔阂，让亲子相处不费心。\u003c/p>\u003cp>\u003cstrong>【B1利益】\u003c/strong>\u003c/p>\u003cp>你是否经历过，明明很爱孩子，孩子却不愿意听你说话，恨不得把你当仇人；你是否经历过，明明是一件小事孩子却不照做，偏偏跟你对着干最后闹的鸡飞狗跳，这本书可以告诉你原因和解决的办法。\u003c/p>\u003cp>\u003cstrong>【B2利益】\u003c/strong>\u003c/p>\u003cp>孩子总是在一件事上屡教不改，让你忍无可忍，却担心发脾气不仅解决不了问题，还会伤害到孩子。但是不发却让自己很难受，不知如何是好。\u003c/p>\u003cp>遇到不愉快的意外，忍不住对孩子发了脾气，孩子从此以后跟你变得疏远，不愿意跟你过多交流，不知道如何改变。\u003c/p>\u003cp>今天的两个拆页可以告诉你解决办法。\u003c/p>\u003cp>\u003cstrong>环节3：设立目标\u003c/strong> \u003c/p>\u003cp>今天给大家带来了两个拆页，这两个拆页都来自《孩子，请把你的手给我》。我们的总学习目标是，学习者在跟随我完成这两次RIA现场学习以后，学会两个提升亲子沟通力的方法。\u003c/p>\u003cp>两个拆页都有4个部分，“学习目标”、“拆页阅读”、“拆书讲解引导”、“学习者拆为己用”\u003c/p>\u003cp>\u003cstrong>【片段1目标】\u003c/strong>\u003c/p>\u003cp>希望学习者在通过本次RIA现场学习以后，能够运用“生气4步法”，解决在遇到孩子屡教不改，想对孩子发脾气时，担心发脾气会伤害孩子而不敢发脾气的问题。\u003c/p>\u003cp>运用这个方法可以让自己“无需再忍”，既能表达自己的愤怒，又不会伤害孩子，还能让孩子能够理解自己想表达的意思。\u003c/p>\u003cp>\u003cstrong>（过渡）\u003c/strong>这是今天的第一个拆页，现在分发给大家。篇幅比较短，给大家1分钟阅读时间。只用阅读红色部分就可以了，阅读完毕的老师可以举手示意我。谢谢。\u003c/p>","ratings_count":2,"texts":[{"id":20563,"quote":"\u003cp>\u003cstrong>【R】片段一 \u003c/strong>\u003c/p>\u003cp>处理激动的情绪第一步是给他们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”：“我觉得很讨厌”“我觉得被激怒了”。\u003c/p>\u003cp>如果简短的陈述和拉长着脸并没有产生效果，那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>“我生气了”\u003c/p>\u003cp>“我很生气”\u003c/p>\u003cp>“我非常非常生气”\u003c/p>\u003cp>“我气极了”\u003c/p>\u003cp>有时，仅仅表达出我们的感受（不用表达原因）就能让孩子停止不端行为。但是，有时候可能采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们的希望行为。\u003c/p>","explains":"\u003cp>\u003cstrong>环节4：讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp> 这个片段教给我们了一种表达愤怒的方法，这种表达方法能使愤怒的父母得到一定程度的解脱和轻松，同时不会伤害到孩子，且能让到孩子理解你生气的原因，对任何一方都没有副作用。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>愤怒是一种情绪，我们不喜欢他，但是无法忽略他，对待自己的孩子时，我们可以极力忍耐自己的愤怒，但是忍耐是有限度的，久了，必然会爆发出来。\u003c/p>\u003cp>\u003cstrong>我们常规的做法：\u003c/strong>\u003c/p>\u003cp>当我们发怒时，我们的行为经常会失去理智，有的时候对外人可能犹豫控制一下，但是对自己的孩子，会控制不住的大喊大叫、辱骂抨击、讽刺挖苦，甚至是动手打人。\u003c/p>\u003cp>\u003cstrong>这样做的坏处：\u003c/strong>\u003c/p>\u003cp>当一切结束时，我们又会觉得内疚，我们也下定过决心，以后绝不再犯。这不但没有作用，反而有可能更糟糕。如此反复恶性循环，跟孩子的关系也会越来越不受控制，孩子可是我们愿意为了他们的幸福付出生命和财富代价的人啊。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>说一个自己的例子\u003c/p>\u003cp>我的女儿特别喜欢做手工，尤其是剪纸类的，做完以后就会留下很多碎纸片，她基本不会收拾。我说了很多次都没有用，终于我爆发了，我当着她的面把她所有的手工作品，不论是她做好的，还是正在做的，一股脑的都扔出了门外，看着她一边哭一边捡那些手工的时候，我心里也很难受。但是我也真的很生气。\u003c/p>\u003cp>其实在亲自关系中，父母的愤怒也可以起到一定的作用，真正关心孩子的父母很难做到一直不生气，对孩子做的错事毫无反应，孩子反而会觉得你不在意他。\u003c/p>\u003cp>这并不代表孩子有能力面对你的愤怒和暴力，这里需要表达的是让孩子能够理解的愤怒：比如说让他们能够感到我们的忍耐已经到了极限。\u003c/p>\u003cp>\u003cstrong>【HOW细化步骤】\u003c/strong>\u003c/p>\u003cp>那么具体要怎么做呢？\u003c/p>\u003cp>\u003cstrong>1、察觉自己的直接反应\u003c/strong>\u003c/p>\u003cp>双手握拳，气血上头，脸部涨红，眯眼，深呼吸等，都是我们在生气时可能出现的反应，跟孩子打交道的时候我们有时会发脾气，这很正常，但是在发脾气之前我们可以通过自己的直接反应来察觉自己的情绪，为了方便大家理解，我这里也列举了一个词汇表，都是些关于情绪的形容词，大家可以参照一下。\u003c/p>\u003cp>\u003cstrong>2、表达出自己的情绪\u003c/strong>\u003c/p>\u003cp>我们察觉出自己的情绪以后，就直接用简短的语言表达出来\u003c/p>\u003cp>在这里尽量多用“我”字开头。而不是“你”字开头，因为你字开头会让孩子觉得你在指责他。\u003c/p>\u003cp>比如：我不喜欢你这样说话的口气；我很烦躁；而不是你让我很烦躁，你说话的口气让我很生气。\u003c/p>\u003cp>孩子的理解能力有限，有的时候我们只讲出自己的感受时，孩子们可能不会把这些与自己不端的行为联想到一起，这个时候可以加一些强调性的词语，\u003c/p>\u003cp>比如：我很生气，我愤怒极了\u003c/p>\u003cp>\u003cstrong>3、讲出生气的原因\u003c/strong>\u003c/p>\u003cp>我们生气的根本原因还是在于：孩子的行为与我们最初期盼的相违背。所以想让孩子的行为朝着我们希望的方向发展，就用孩子能理解的的语言直接告诉孩子你生气的原因。\u003c/p>\u003cp>比如：书桌被弄的很乱，衣服被弄脏了。\u003c/p>\u003cp>\u003cstrong>4、讲出期望的行为\u003c/strong>\u003c/p>\u003cp>生气是为了发泄一下自己的负面情绪，最重要的还是要让孩子知道自己该怎么做，而不是让孩子也沉浸在你的情绪之中，所以一定要告诉孩子你希望他怎么做。\u003c/p>\u003cp>这里，是要告诉孩子你希望的行为，而不是必须的行为，这个很重要，\u003c/p>\u003cp>比如我希望你能把书桌整理一下。而不是你必须把书桌整理洗一下。\u003c/p>\u003cp>这4步中，第2.3.4步没有固定的顺序，可以根据自己的习惯和实际情况来调整顺序。\u003c/p>\u003cp>\u003cstrong>【反例加工】\u003c/strong>\u003c/p>\u003cp>学了上面这个方法，我对自己的行为也做了调整，没过多久，女儿又开始剪纸，依旧把碎纸弄的到处都是，同样不会去收拾。\u003c/p>\u003cp>我先察觉了一下自己的反应，我感觉自己浑身发毛，很暴躁，很想发火，我在不断的深呼吸压制自己的怒火（察觉自己的反应）\u003c/p>\u003cp>然后我跟她说：你做完手工留下的一堆碎纸，密密麻麻的，让我浑身发毛，我有密集恐惧症，我讨厌这种感觉，我非常生气（表达情绪）\u003c/p>\u003cp>为了保持家里的整洁，我不得不去忍受发毛的感觉去面对这些碎纸，还要把他们收拾干净，我已经收拾了很多次了。（说出原因）\u003c/p>\u003cp>我希望你下次做手工的时候把一个垃圾桶放在旁边，不要的碎纸直接丢进垃圾桶（说出期望）\u003c/p>\u003cp>女儿听了我的话，思考了一会儿，点点头说了句好，然后自己去收拾碎纸去了，这个方法很管用，她后面做手工的时候真的会在身边放一个垃圾桶，然后把碎纸扔进去。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个拆页可以适用于亲子间父母对孩子，职场里上级对下级，生活里长辈对晚辈。不适用于下属对上级，晚辈对长辈，同事平级和生活中平辈之间。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>1. 可能有小伙伴会问，使用了这个方法，我就不气了吗？\u003c/p>\u003cp>答：当然不可能这么绝对啊，我们不是为了生气而生气，也不是为了不生气而强迫自己忍耐，我们的目的是在我们表达负面情绪的时候不伤害孩子，同时孩子能够接受，并愿意改正。\u003c/p>\u003cp>2. 有小伙伴会说为什么要用这个方法，用别的不行吗？\u003c/p>\u003cp>答：当然这不是唯一的方法，我们只需要找到最适合自己的即可，如果还没有找到，不妨试试这个生气4步法。\u003c/p>","interaction":"\u003cp>\u003cstrong>环节5：\u003c/strong>A1激活经验 \u003c/p>\u003cp>\u003cstrong>【A1之显像提问】\u003c/strong>\u003c/p>\u003cp>好了，以上是片段的讲解部分就到这里，下面咱们用今天学到的生气4步法实操一下。\u003c/p>\u003cp>各位小伙伴，让我们一起来回忆一下，在过去的一个月内，有没有哪件事情让你忍不住发了脾气呢，可以是跟孩子之间，可以是跟下属，也可以是跟晚辈，咱们可以在小组内讨论一下。\u003c/p>\u003cp>这里只用回忆事件本身就行，不用说事后的反思和感受。好了大家可以分组讨论了，这里有3分钟的时间。稍后，我们会请一个小伙伴来分享一下。\u003c/p>\u003cp>好了时间到，让我们请一位小伙伴来分享一下。\u003c/p>\u003cp>保洁大叔：昨天下午，有一个下属在执行活动之前没有跟我以及财务报备流程，我询问进度的时候说，都弄好了，已经开始了，这属于违规操作没有按工作流程走，让我觉得很生气，对下属发了脾气。\u003c/p>\u003cp>\u003cstrong>回应和反馈：感谢李老师主动分享了自己在工作中经历，掌声送给他，下属违规操作有可能会带来没有必要的麻烦，让他很生气。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+反思加工】 \u003c/strong>\u003c/p>\u003cp>下面让咱们来设想一下，如果时间可以倒流，让我们能够运用今天学到的生气4步法，来表达自己的愤怒，我们可以怎么做，咱们先回顾一下，生气4步法有哪些，\u003c/p>\u003cp>1.察觉自己的直接反应 2.表达自己的情绪 3.说出原因 4说出自己的期望\u003c/p>\u003cp>好的，再给大家5分钟的时间分组讨论，刚才给到大家的表达情绪的词汇表，大家可以根据上面的词语来找出能够表达你当时情绪的对应词语。\u003c/p>\u003cp>好的，时间到了，让我们来请一位小伙伴分享\u003c/p>\u003cp>保洁大叔：应用今天学习的4步，\u003c/p>\u003cp>第1步觉察自己的直觉反应，一听他说的这些话我感觉到头晕，激动焦躁。\u003c/p>\u003cp>第2步表达自己的情绪，跟他说我不太高兴。\u003c/p>\u003cp>第3步说出原因，告诉他我生气的原因是因为他没有报备财务走流程。\u003c/p>\u003cp>第4步说出期望，希望下一次活动先走流程报备财务再推进工作。\u003c/p>\u003cp>\u003cstrong>A1+ 回应和反馈\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好的，非常感谢李老师，给李老师掌声。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小结\u003c/strong>\u003c/p>\u003cp>好了以上是第一个片段的学习，通过第一个片段的学习，我们知道了，在亲子沟通中，在不伤害孩子的情况下，有些脾气是非常有必要发的，只要方法得当，反而能提高亲子间的沟通力，增进亲子关系。\u003c/p>\u003cp>但是有些场合下，发脾气反而会让亲子间的关系变得恶劣，这时需要把自己的负面情绪转移到问题的解决上。让我们来看看今天的第二个拆页，遇到突发事件让我们很不愉快，下意识想口出恶言时，我们该如何把注意力从情绪上转移到解决问题上。\u003c/p>\u003cp>我们今天的两个片段是并列的关系，针对不同具体的场合下，具体运用。\u003c/p>\u003cp>\u003cstrong>环节1：学习目标\u003c/strong>\u003c/p>\u003cp>本拆页的学习目标是：让学习者通过本次RIA的学习，学会使用“转移3步法”解决在遇到突发的，令人不愉快的意外时，下意识使用恶意的言语伤害孩子，恶化双方关系的问题。\u003c/p>\u003cp>同样有1分钟的时间，大家只需要读黄色的部分，阅读完毕的小伙伴可以举手示意一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":20564,"quote":"\u003cp>\u003cstrong>环节2：阅读拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】片段二\u003c/strong>\u003c/p>\u003cp>当八岁的玛丽不小心打翻了她的果汁时，她的妈妈平静地说道：“我看到果汁打翻了，我们再拿一杯果汁吧，还要拿一块海绵。”她站起来，把果汁和海绵递给女儿。玛丽抬起头来看妈妈，既松了一口气，又有点怀疑。玛丽低声说：“哎呀，谢谢你妈妈”。她把桌子抹干净，妈妈还在一边帮她。妈妈并没有说什么严厉的、批评的话，也没有说一些无用的忠告，她说：“我当时想说‘下次小心点’，但是当我看到她善意的沉默，看到她多么感激时，我就什么都没说了。”\u003c/p>","explains":"\u003cp>\u003cstrong>环节3：I讲解引导 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>当令人不愉快的意外发生时，当时可能并不是教训孩子（肇事者）人品的合适时机，这个时候，应该先处理事情，而不是人。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>原文中的案例是亲子间的案例，现场也有小伙伴没有孩子，或者孩子已经成年，为了方便大家理解，我们来举一个在职场上经常会发生的例子。\u003c/p>\u003cp> 当二十岁的小张在高速上开车时不小心错过了下高速的路口，正坐在副驾驶上他的老板赵总平静地说道：“我看到错过了一个路口，我们再找一下，下一个路口的位置吧，打开导航看一看。”\u003c/p>\u003cp> 赵总拿出手机查起了地图，然后把打开导航的手机放在了小张面前的手机支架上。小张转过头来看了一眼老板，既松了一口气，又有点怀疑。他低声说：“哎呀，谢谢你，赵总”。\u003c/p>\u003cp> 赵总一边查看着手机，一边帮小张核对着途经的路标。并没有说什么难听的、指责的话，也没有说一些无用的忠告，赵总说：“我当时真的想说下次注意点’，但是当我看到他善意的沉默，看到他多么感激时，我就什么都没说了。”\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>如果案例中的赵总在小张错过第一个路口时说：你在想什么，那么大个路标都看不见。我想小张肯定不会觉得自己应该提高的是视力和开车技术，而是会觉无地自容很难看。赵总并没有指责小张，而是协助小张一起寻找下一个路口，解决了问题，这个小插曲很快就过去了。\u003c/p>\u003cp>再回到亲子关系上，小意外的发生，是父母向孩子传授价值观的好时机，我们可以言行身教，让孩子从父母的处事方式上学会分辨什么事情仅仅是使人不愉快、让人讨厌，什么样的事情才是悲剧和灾难。\u003cstrong>（这样做的好处）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>常规做法：\u003c/strong>\u003c/p>\u003cp>而现实中许多父母对打碎了一个鸡蛋的反应就像是被打断了一条腿，对玻璃被打碎的反应就像是心被打碎了一样。\u003c/p>\u003cp>\u003cstrong>常规做法的结果:\u003c/strong>\u003c/p>\u003cp>这样会混淆孩子的价值观，让孩子分不清事情的轻重缓急，长此以往有可能会影响到孩子在面对人生重要时刻做出错误的选择，我们都知道，失之毫厘，谬以千里。\u003cstrong>（不这样做的坏处）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp> 那么我们具体要怎么做呢？\u003c/p>\u003cp>\u003cstrong>第一步：不进行任何评判\u003c/strong>，当遇到不好的事情突发时，难免会产生一些负面的情绪，\u003c/p>\u003cp>也会下意识的说出一些评判性的词语，比如，你怎么这么笨，没长眼睛吗。\u003c/p>\u003cp>其实我们也不是为了指责谁，真的就只是一种发泄，但是对方有可能因此受到伤害。\u003c/p>\u003cp>这个时候我们需要做的是冷静下来，不进行评判，可以根据自己实际情况在心里默数10个数，做几个深呼吸等。\u003c/p>\u003cp>\u003cstrong>第二步：说出事实。\u003c/strong>\u003c/p>\u003cp>这里可以用简短的语言描述事实，目的是为了让双方对发生的事情进行一个共同的确认，没有出现理解性的偏差。这样做可以让双方都聚焦在客观事实上。\u003c/p>\u003cp>这里同样建议在描述事实的时候多用“我”字开头，少用带有指责意思的“你”\u003c/p>\u003cp>比如：我看见果汁打翻了，我看见错过了一个路口。而不是我看见你把果汁打翻了，我看见你错过了一个路口。\u003c/p>\u003cp>\u003cstrong>第三步：主动采取行动。\u003c/strong>\u003c/p>\u003cp>大多数孩子（肇事者）突然意识到自己犯错时会处在一个束手无策的状态中，一方面不知道该怎么样应对眼前的情况，也就是不知道该怎么解决问题，另一方面害怕面对家长的反应，更多的是生气，愤怒。\u003c/p>\u003cp>所以主动采取行动，会把孩子的注意力从情绪拉回到问题上。\u003c/p>\u003cp>同时也是在给孩子打一个样板，让孩子从你的行为中学会今后遇到类似事情时不是沉浸在不知所措的状态中而是赶紧解决问题。\u003c/p>\u003cp>\u003cstrong>【使用边界】\u003c/strong>\u003c/p>\u003cp>同样，这个拆页可以适用于亲子间父母对孩子，职场里上级对下级，生活里长辈对晚辈。不适用于下属对上级，晚辈对长辈，同事平级和生活中平辈之间。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp> 1、有的小伙伴可能会觉得，这真的是太麻烦了，我就是想发这个火，不然我心里会憋的很。\u003c/p>\u003cp>答：这当然没有问题了，但是我们今天的学习目的不是为了省事，也不是为了不发火，而是为了解决问题，我们很清楚，不管当时发了多大的脾气最后都是要解决问题，而发脾气有可能会让事情更糟糕。\u003c/p>\u003cp>2、也有小伙伴会说，难道就一定要用你这种方法吗？\u003c/p>\u003cp>答：当然不是，我们不管学习什么都是为了找到最适合自己的，如果找到了就恭喜你，如果没有找到，不妨试试今天的转移3步法。\u003c/p>","interaction":"\u003cp>\u003cstrong>环节4：A3促动参与  \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】场景\u003c/strong>\u003c/p>\u003cp>好了以上是对拆页的讲解部分，我们刚刚学习了转移3步法，下面让我们来练习一下这个方法，大家仔细听一下\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>有这样一个场景\u003c/p>\u003cp>\u003cstrong>背景：\u003c/strong>菲菲和爸爸要去看电影，走到小区楼下，爸爸发现没有带手机，就把钥匙给了菲菲，让菲菲回家帮忙拿手机，并叮嘱菲菲下来的时候一定要记得把钥匙拿上。\u003c/p>\u003cp>\u003cstrong>问题：\u003c/strong>当菲菲再次下楼的时候，发现把钥匙落在了家里，菲菲非常害怕，她不敢跟爸爸说话，她可以想象爸爸会是怎么样的暴怒，爸爸可能会说：你到底有没有长脑子，还专门提醒你了要带钥匙，养你有什么用......\u003c/p>\u003cp>\u003cstrong>方法\u003c/strong>：转移三步法：1.不进行评判 2.说出事实 3.主动采取行动\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>把负面情绪转移到解决问题上\u003c/p>\u003cp>\u003cstrong>【A3】清晰指令\u003c/strong>\u003c/p>\u003cp>下面我们在小组内进行演练，一个人扮演菲菲爸爸，面对菲菲突发的小状况，如何运用今天学到的知识点来处理问题，而不是责备菲菲。另一个人来扮演担惊受怕的菲菲。\u003c/p>\u003cp> 我们有10分钟的时间大家可以先在小组内谈论，运用今天的知识点来设计两人之间的对话，稍后咱们请一个爸爸和一个菲菲来给大家展示一下。好的，开始。\u003c/p>\u003cp>\u003cstrong>【A3】角色扮演  \u003c/strong>\u003c/p>\u003cp>好的时间到，大家讨论得十分激烈，下面我们有请一个菲菲和一个爸爸\u003c/p>\u003cp>\u003cstrong>左老师：菲菲，手机给我\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李老师：好的爸爸，给你\u003c/strong>\u003c/p>\u003cp>\u003cstrong>左老师：钥匙呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李老师：什么钥匙\u003c/strong>\u003c/p>\u003cp>\u003cstrong>左老师：家里钥匙啊？找一找\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李老师：哎呀，刚才拿手机的时候顺手放在窗台上面了，完了完了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>左老师：哎，钥匙被我们忘记家里窗台上了，我给妈妈打个电话，看她什么时候回来吧，如果回来的早我们就不用担心了，要是回来的晚，等我们看完电影，想办法去取吧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>行动：打开手机，拨号\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回应和反馈\u003c/strong> \u003c/p>\u003cp>感谢两位老师的角色扮演，我们从中也能学习到不少东西，爸爸既没有批评菲菲，还教会了菲菲处理类似事情的方法。\u003c/p>\u003cp>\u003cstrong>环节5：A2催化应用\u003c/strong> \u003c/p>\u003cp>\u003cstrong>【A2】分步催化1  \u003c/strong>\u003c/p>\u003cp>我们刚才在特定的场景中进行了演练，下面请小伙伴们设想一下，在未来的一周或者一个月内，在你与孩子之间，或者是与下属，晚辈之间有可能出现的一些不愉快的场景，会让你忍不住恶语相向，给大家5分钟左右的时间把这个场景设想一下，并写下来，稍后请小伙伴分享。注意，这里只用描述出场景即可。包括时间，地点，事件起因、经过或结果。\u003c/p>\u003cp>\u003cstrong>李老师：明天有一场电影包场活动，因为人比较多，环节也比较多，下属有可能会出现，疏忽嘉宾的情况，比如没有更换嘉宾麦克风的电池。我看到这样的事情一定会很不高兴，会责备员工。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回应和反馈\u003c/strong> \u003c/p>\u003cp>\u003cstrong>感谢李老师的分享，分享了具体场景如下：明天的活动，员工因为忙碌会忽略客户让你很不高兴，会责备员工。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】分步催化2    \u003c/strong>\u003c/p>\u003cp>根据咱们刚才设想的场景，再联系拆页2学到的内容，可以做出哪样的调整呢，给大家5分钟的时间，写到便签纸上，然后会请小伙伴分享一下。这里也给了大家一个模板。\u003c/p>\u003cp>李老师的分享\u003c/p>\u003cp>在未来的 \u003cu>明天\u003c/u> （时间周/月）\u003c/p>\u003cp>我可能会遇到与 \u003cu>下属\u003c/u> （孩子/爱人/同事）\u003c/p>\u003cp> 在\u003cu>公司\u003c/u>（地点）\u003c/p>\u003cp>发生 \u003cu>活动包场时下属因为忙碌忽略嘉宾\u003c/u> （什么样的事情）\u003c/p>\u003cp>会让我说出不好的言语，伤害到彼此的关系。\u003c/p>\u003cp>我计划用到今天学到的知识点进行改善\u003c/p>\u003cp>第一步 \u003cu>不做任何评判，调整一下自己的情绪\u003c/u> \u003c/p>\u003cp> 第二步 \u003cu>我看见嘉宾的麦克风没有电了\u003c/u> \u003c/p>\u003cp>第三步 \u003cu>拿上一些饮品去跟嘉宾道歉并更换电池\u003c/u> \u003c/p>\u003cp>\u003cstrong>回应和反馈\u003c/strong>\u003c/p>\u003cp>\u003cstrong>谢谢李老师的分享。真正做到了不做评判，描述事实，主动采取行动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>环节6：总结\u003c/strong>\u003c/p>\u003cp>今天我们学习了两个片段，教会了我们 两个在亲子关系中化解自己负面情绪的方法，一个是“生气4步法”一个是“转移3步法”    \u003c/p>\u003cp>希望在这些在今后的生活中能对大家有所帮助，今天的拆书就到这里，感谢大家的参与。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1692382923000,"updated_at":1693548535000,"ria":true},{"id":16328,"topic":"发怒的三个步骤","learn_goal":"","remark":"当孩子出现不良行为时，\n家长就只能忍忍忍，不能冲他发火吗？\n父母一味地忍气吞声，\n真的就是美德，是正确的吗？\n今天我们一起来学习如何正确地表达我们的愤怒。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍、分组、学习目标【1分钟】\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习目标均包含学习者可被观察到/被测量到的行为或动作，现场学习者设计都清晰体现了各自的学习目标。\u003c/p>\u003cp>大家晚上好！非常感谢大家在百忙之中抽出时间来参加我的线下过级活动。\u003c/p>\u003cp>我叫陈芳。三个标签简单的介绍一下我自己。\u003c/p>\u003cp>第一个：季草集美业顾问；\u003c/p>\u003cp>第二个：孩子的学习提升导师；\u003c/p>\u003cp>第三个：正在努力晋级的拆书家\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>好的，由于今天的过级环节需要分组讨论一下，下面我来进行一下分组。在坐的刚好有 10 位伙伴，我们就相对的两位老师为一组吧。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在大家跟随我完成本次的RIA现场学习后，学习者能够运用“发怒”的三种方法来合理的表达愤怒，避免矛盾升级，避免给孩子带来伤害。\u003c/p>\u003cp>\u003cstrong>二、图书介绍【1-2分钟】\u003c/strong>\u003c/p>\u003cp>【拆书技能】选择图书是实用类或理论类图书；在 FAB 介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>\u003c/p>\u003cp>那今天我要给大家介绍的这本书是《孩子，把你的手给我》。作者是美国著名成人心理学教授，儿童心理学专家海姆·G·吉诺特博士。作者通过这本书教会我们如何提高沟通的技巧，以共情关爱的方式去了解孩子的感受，从而实现与孩子之间真正有效的沟通方式。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>\u003c/p>\u003cp>本书英文第一版出版于1965年，至今将近60年。与同类书籍相比，本书中提出的许多理念都是具有开创性的。吉诺特博士的学生阿黛尔·法伯和伊莱恩·玛兹丽施在一系列亲子教育书中传播的理念，其中很大一部分的源头就来自于这本书。\u003c/p>\u003cp>\u003cstrong>【B1】\u003c/strong>\u003c/p>\u003cp>如果你还在为不知道怎么跟孩子沟通而苦恼，如果你的孩子经常让你情绪愤怒，那么这本书将教会你如何与孩子实现真正有效的沟通方法。\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>\u003c/p>\u003cp>当孩子出现不良行为时，家长只能忍忍忍，不能冲他发火吗？父母一味地忍气吞声，就是正确的吗?\u003c/p>\u003cp>今天这个片段将教会你一个不一样的解答方法。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>大家手上拿到的，是我今天准备的原文拆页。现在请大家花2分钟的时间阅读一下，阅读完成的伙伴可以举手向我示意一下。好的，现在开始。\u003c/p>","ratings_count":1,"texts":[{"id":20436,"quote":"\u003cp>\u003cstrong>三、阅读原书拆页【1-2分钟】\u003c/strong>\u003c/p>\u003cp>【拆书技能】【R】所选拆页，可以是简单How的指令，也可以是隐含How的案例或故事；且总内容未超过 2 页图书内页。\u003c/p>\u003cp>\u003cstrong>发怒的三个步骤\u003c/strong>\u003c/p>\u003cp>在平静时期，让自己做好应付紧张时刻的准备，应该承认下面的事实：\u003c/p>\u003cp>1、我们接受这个事实：在跟孩子打交道的时候，我们有时会发脾气。\u003c/p>\u003cp>2、我们有权生气，而不必感到内疚或者羞愧。\u003c/p>\u003cp>3、除了安全考虑，我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格，我们可以表达我们的愤怒。\u003c/p>\u003cp>这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”：“我觉得讨厌。”“我觉得被激怒了。”\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有起效果，那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>“我生气了。”\u003c/p>\u003cp>“我很生气。”\u003c/p>\u003cp>“我非常非常生气。”\u003c/p>\u003cp>“我气极了。”\u003c/p>\u003cp>有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>\u003cp>“当我看到鞋子、袜子、衬衫、运动衫扔到满地都是时，我很生气，生气极了。我真想打开窗户，把这一摊乱七八糟的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟，我很生气，心里面像有团火在烧，我绝不允许你再伤害他。”\u003c/p>\u003cp>“看到你们所有的人一吃完晚饭就冲出去看电视，把那些脏兮兮的盘子，油腻腻的锅留给我时，我非常愤慨！气得我简直七窍冒烟！我真想把所有的盘子砸到电视上去！”\u003c/p>\u003cp> “我叫你吃晚饭，而你却不来，我很生气，非常生气，我对自己说：‘我煮了一餐好吃的，希望获得赞赏和感激，而不是失望！’”\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导【3-4分钟】\u003c/strong>\u003c/p>\u003cp>【拆书技能】【I】环节，给出了比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译。\u003c/p>\u003cp>好的，我看到大部分伙伴已经阅读完了。没有读完也没有关系，接下来我会详细讲解。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段告诉我们，在面对孩子不良的行为时，如何将自己的情绪安全地、有效地表达出来，不攻击孩子的人格，不做过激的行为去伤害孩子。\u003c/p>\u003cp>\u003cstrong>【Why】（不这么做的坏处）\u003c/strong>\u003c/p>\u003cp>当孩子出现不良行为举止时，使我们感到很生气时，我们一般会怎么做呢？是没完没了的唠叨？是直接破口大骂？还是大打出手，来发泄自己的情绪呢？往往我们这样做的后果就是换来孩子的反抗，或是一时的屈服，实际是没有从根本上解决问题，反而伤害了孩子的身心健康，破坏了与孩子之间的亲子关系，从而使孩子心中对家长堆积了很多的怨恨。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>我跟大家分享一个我自己与孩子之间的一个失败的案例。\u003c/p>\u003cp>上个月的一个晚上，在家里书房里，大宝打开电脑。在电脑还没有运行正常的情况下，她就急切的把鼠标一通乱点，导致电脑死机无法正常运行了。结果小孩嘴里还一直叫骂“什么破电脑”。\u003c/p>\u003cp>我在旁边提醒她，不要着急，耐心的等一会，等程序运行完了再打开网页。大宝当时不耐烦的答应着“哦哦哦……”，但是手还是拿着鼠标跟点炮一样的，啪啪啪……。\u003c/p>\u003cp>我见她依然我行我素的，也没有忍住情绪，一巴掌过去，打在了她握鼠标的手上，并大声的怒吼到“你今天不准再碰电脑了”。当时大宝也是怒气冲冲的回到卧室，把房门哐当一声关上了。\u003c/p>\u003cp>当听到关门声的那一瞬间，我才突然意识到，似乎自己刚才的反应有些过激了。这样可能不仅会导致孩子今天无法完成学校布置的编程作业；而且可能也会影响孩子以后遇到问题，她可能也会像妈妈这样怒吼打骂的行为去处理问题。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那我们如何正确的发泄我们的情绪，不让类似的事情再发生呢？下面我们一起来学习“发怒”的三种方法。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 确定事实。\u003c/strong>\u003c/p>\u003cp>首先确定我们的情绪，并且把我们的情绪明确地表达出来。\u003c/p>\u003cp>例如：这件事情，让我很不开心。\u003c/p>\u003cp>如果孩子听到这样的说明，就改正不良行为，那就皆大欢喜。\u003c/p>\u003cp>\u003cstrong>2. 加强程度\u003c/strong>\u003c/p>\u003cp>如果对方任然没有感受到我们愤怒的情绪，那我们就可以加强表达的程度，使用第一人称代词“我”来表达自己此时的感受。\u003c/p>\u003cp>例如：“我现在\u003cstrong>很\u003c/strong>生气”，“我现在\u003cstrong>非常非常\u003c/strong>地生气”。\u003c/p>\u003cp>\u003cstrong>3. 表达感受\u003c/strong>\u003c/p>\u003cp>这里的表达感受，其实是为了解释生气的原因，更好地让对方与我们产生共情。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那我们该怎么做才能让对方感受和理解我们的情感呢？我用了两个步骤来进行详细表达。\u003c/p>\u003cp>\u003cstrong>【细化行动步骤】\u003c/strong>\u003c/p>\u003cp>第一步：说出内心的想法\u003c/p>\u003cp>当我下班回家，看到家里杂乱场面的时候，我就有了破坏性的想法。比如就像片段里的看到鞋子、袜子满地都是，就想 “打开窗户”、“扔到大街上”。\u003c/p>\u003cp>第二步：说出期望的行为\u003c/p>\u003cp>可以说妈妈希望看到的是摆放整齐的房间，希望听到你们有条理地表达，希望你们赶快把饭吃完。这些都是可以告诉孩子的期望的行为。\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>\u003c/p>\u003cp>那刚刚和大家一起学习了“发怒”的三种方法，再回到我前面的案例上，我一定会这样做：\u003c/p>\u003cp>1. 确认事实：明确地说出来，我看到你没等电脑完全开好机开始操作，还说电脑反应太慢，让我很不开心。\u003c/p>\u003cp>当我把这种不开心的状态明确告诉孩子，如果孩子依然我行我素，这个时候，我就可以执行第二步。\u003c/p>\u003cp>2. 加强程度：我可以目光严肃、认真地注视孩子，说“我现在很生气，我现在非常非常地生气”。\u003c/p>\u003cp>3. 表达感受：我可以说出我的想法。比如，我可以说：“刚刚妈妈看到你又是生气骂电脑，又是态度不耐烦，我当时真的很生气，恨不得拔掉电源，让你去面壁反思”。\u003c/p>\u003cp>当我正确地把情绪表达出来之后，孩子会有一些触动的。待孩子情绪缓和一下，我们可以跟孩子说：“妈妈希望你耐心友好地对待我们的电脑，它可以满足我们学习中的很多需求，如果你这么暴力的对它，它肯定会罢工啊。”\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>这个方法适用于具有一定理解能力的儿童，比如幼儿园以上的未成年子女。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A3】促动参与【10-15分钟】\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A3】环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那接下来我提供一个场景，请大家运用今天所学的这三种方法来进行演练一下。\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>\u003c/p>\u003cp>假设这个场景：暑假开学之后，周一的一个早晨，你一个人忙出忙进，很早就起床给孩子们准备上学前的一系列，早饭、水杯、餐具等，这时孩子的房间传来了一阵催魂夺命的嚎叫声“妈妈，我的袜子找不到了，为什么我的袜子都是一样一只”。此时的你正打着鸡蛋准备往烧热的油锅里倒。听到孩子的喊叫，你一瞬间血压高升，头要炸了。于是，你怒气冲天地走到她房间去，接下来你会跟孩子怎么进行沟通和交流？\u003c/p>\u003cp>请大家现在花5分钟时间在小组内讨论一下，我一会儿请两位小伙伴来演练一下这个场景。现在开始。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>张兮吾老师饰父亲\u003c/p>\u003cp>张军老师饰儿子\u003c/p>\u003cp>子：爸爸，我的袜子呢？我找不到袜子了。快来给我找袜子。\u003c/p>\u003cp>父：在柜子里，自己拿。\u003c/p>\u003cp>子：我找不着。再找不着袜子，我上不了学了。\u003c/p>\u003cp>父：爸爸在煎鸡蛋啊。爸爸要煎鸡蛋的。\u003cstrong>【确认事实】\u003c/strong>\u003c/p>\u003cp>子：不要煎了。我不穿鞋了，今天不穿鞋了。\u003c/p>\u003cp>父：（心理活动：是吗？胆还挺肥的。）我先跟你说一下，爸爸今天早晨要给全家人做早饭，这个时候你来烦我袜子的事情，我非常生气。自己回去找。\u003cstrong>【加强语气】\u003c/strong>\u003c/p>\u003cp>子：找不着袜子，我该怎么上学呢？\u003c/p>\u003cp>父：我都跟你说过了，我要煎鸡蛋啊。\u003c/p>\u003cp>子：我今天不吃鸡蛋了，我就要找我的袜子。\u003c/p>\u003cp>父：你不吃别人要吃呀。\u003c/p>\u003cp>子：那今天找不着袜子，我就不去上学了。\u003c/p>\u003cp>父：\u003cstrong>【表达感受】\u003c/strong>爸爸刚才跟你说了，早上我最忙的时候，你因为一双袜子来打扰我。我是非常生气的。另外呢，像找袜子、打扮自己这种事情，爸爸希望你为自己安排好。你想呈现一个什么样的自己？你想以什么样的形象出现在同学们面前？你要有这样的自主性。把自己的衣服、袜子整理得妥妥当当的。睡觉之前就要收拾好。这样早上就可以直接用了，而且，这样的话爸爸一定会特别开心\u003cstrong>【说出期望的行为】\u003c/strong>。\u003c/p>\u003cp>子：好吧，那我明天找好了再睡觉，我再找一找吧。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>感谢两位张老师的精彩表演。两位老师通过孩子找袜子、爸爸煎鸡蛋这样的一个故事，把我们今天学到的三种方法运用得活灵活现，实现了爸爸与孩子之间的有效沟通，避免了一场亲子大战。\u003c/p>\u003cp>【拆书技能】【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/p>\u003cp>\u003cstrong>六、总结【1分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书技能】：\u003c/strong>总时长没有少于20分钟，没有超过25分钟。\u003c/p>\u003cp>好的，希望我今天分享的“发怒”的三种方法：\u003c/p>\u003cp>1. 确定事实\u003c/p>\u003cp>2. 加强程度\u003c/p>\u003cp>3. 表达感受\u003c/p>\u003cp>能让孩子知道我们发怒的原因，而不是单纯的情绪发泄。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1690723999000,"updated_at":1690858473000,"ria":true},{"id":16314,"topic":"情绪管理","learn_goal":"","remark":"激动情绪是不定时炸弹，处理不好坏事伤人毁自己，用三步法正确处理，生活快乐，工作顺利","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"心欢喜","city":"郑州市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>【开场】大家好，我是今天的拆书家欢喜，很高兴和大家一起展开今天的学习主题：如何处理激动情绪。\u003c/p>\u003cp>【分组】希望本次RIA现场学习后，各位能够学会运用定义情绪、加强表达和坦陈希望的三个步骤，正确处理激动情绪，先做到自我平和，精确表达，从而增加与对方达成有效沟通的可能性。\u003c/p>\u003cp>为了方便学习过程中充分交流讨论，我们来进行一下分组。我们左手边一组，右手边一组，这样分开。谢谢！\u003c/p>\u003cp>↓技能点：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标。\u003c/p>\u003cp>【学习目标】设定学习目标。要求：可观察/可测量的行为或动作\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够学会运用定义、加强表达和坦诚希望的三个步骤，正确处理激动情绪，先做到自我平和，精确表达，从而增加与对方达成有效沟通的可能性。\u003c/p>\u003cp>↓技能点：在FAB介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/p>\u003cp>下面我先来介绍一下我今天拆解这本书《孩子，把你的手给我》。\u003c/p>\u003cp>本书有三个特征：\u003c/p>\u003cp>1、有效性，改变了美国500万+家庭的亲子沟通方式；\u003c/p>\u003cp>2、实践性，内容是作者毕生的一线工作经验的条理化和系统化，可以起而行之。\u003c/p>\u003cp>3、专注性，主要从沟通的角度，让父母有深沉的爱也有正确的方法，让语言的力量以正向的价值而不是巨大的破坏去成就而不是伤害孩子。\u003c/p>\u003cp>这本书的优势：1、作者不是坐而论道，而是毕生致力于教育工作，保持在儿童面前，他说只有与孩子朝夕相处的人才能把孩子培养成一个品行高洁的人。2、倡导先成人再成事，注重语言的力量和行为的示范，针对亲子教育的日常状况和精神难题，提供具备可操作性的解决方案，把父母期望的目标转化为每天的实践。3、语言自然简洁，十分好读。\u003c/p>\u003cp>你对孩子的期待目标是什么？孩子的表现与你的期待一致吗？为什么是这个结果？大家都在感慨别人家的孩子，这有标准吗？又怎么做到呢？\u003c/p>\u003cp>本书致力于把父母的期待目标转变为日常的践行，通过沟通与陪伴，帮父母与自己的孩子一起成长。\u003c/p>\u003cp>↓技能点：选择图书是实用类或理论类图书。\u003c/p>\u003cp>《孩子，把你的手给我》，这是一本切实可用的亲子教育类图书。\u003c/p>\u003cp>我们今天拆页的片段内容提供了处理激动情绪的方法，通过定义情绪，加强表达和坦陈希望三个步骤，正确处理激动情绪，先做到自我平和，精确表达，从而增加与对方达成有效沟通的可能性。\u003c/p>","ratings_count":1,"texts":[{"id":20420,"quote":"\u003cp>↓技能点：【R】所选拆页，包括How的指令；且总内容未超过2页图书内页。\u003c/p>\u003cp>处理激动的情绪的第一步是给它们\u003cstrong>明确的定义\u003c/strong>。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”:“我觉得讨厌”“我觉得被激怒了”。\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有产生效果，那么采取第二个步骤，在\u003cstrong>表达时加强\u003c/strong>愤怒的强度：\u003c/p>\u003cp>“我生气了。”\u003c/p>\u003cp>“我很生气。”\u003c/p>\u003cp>“我非常非常生气。”\u003c/p>\u003cp>“我气极了。”\u003c/p>\u003cp>有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤：\u003cstrong>解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/strong>\u003c/p>\u003cp>“当我看到鞋子、袜子、衬衫、运动衫扔得满地都是时，我很生气，生气极了。我真想打开窗戶，把这一摊乱七八糟的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟，我很生气，心里面像有团火在烧，我决不允许你再伤害他。”\u003c/p>\u003cp>“看到你们所有的人一吃完晚饭就冲出去看电视，把那些脏兮兮的盘子、油腻腻的锅留给我时，我非常愤慨！气得我简直七窍冒烟！我真想把所有的盘子砸到电视上去！”\u003c/p>\u003cp>“我叫你吃晚饭，而你却不来，我很生气，非常生气，我对自己说：‘我煮了一餐好吃的，希望获得赞赏和感激，而不是失望！”\u003c/p>\u003cp>这个方法可以帮助父母释放怒气，而不致引起伤害，而且，它甚至可以是一堂重要的课，教会孩子如何安全地表达愤怒。孩子可能会明白他自己的愤怒也不是什么大的灾难，可以释放出来，而不会伤害任何人。这堂课不仅仅需要父母把怒火发泄出来，还需要父母向孩子指出情感表达的可接受的方式，要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>\u003cp>——海姆·G·吉诺特 —《孩子，把你的手给我》—电子版：P91-P93\u003c/p>","explains":"\u003cp>↓技能点：【I】的讲解，拆书家提到了不那么做的坏处、找出人们的通常做法，并举出了具体的反面例子，而且使用了片段包含的技能把反面例子加工成正面例子。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>本拆页讲的是通过定义情绪、加强表达和坦陈希望三个步骤，正确解决激动情绪的沟通方法。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>激动情绪是沟通内容的重点，沟通氛围的保持，沟通方向的节点，也是沟通目标的切口。所以：\u003c/p>\u003cp>激动情绪处理不好，会有三种不良后果：1、破坏沟通氛围，导致沟通终止或制造矛盾；2、偏离沟通内容，让沟通变成吵架或语言攻击；3、影响沟通结果，好的结果没了可能，坏的结果却无限可能。最终伤害相互关系。\u003c/p>\u003cp>相应的，处理好激动情绪会让氛围融洽、内容清晰，结果呈现，并且可能创造更多的额外价值。\u003c/p>\u003cp>【举个例子】（反例）\u003c/p>\u003cp>上周末，孩子用手推车把妈妈的花盆撞倒破碎了。爱人非常生气，先是责怪我没有看好孩子，又多次拒绝或不理睬孩子的道歉。我逐渐感觉到很愤怒，但我没有说，我意识到情绪，却放任它默默积压。\u003c/p>\u003cp>当孩子又去找妈妈，还是不被理睬的时候，我的情绪爆发了，指责爱人刻薄寡恩，把孩子排在自己感受的后面。爱人愤怒反击：道歉就要被原谅吗？我偏不。孩子就什么都要原谅吗？我偏不。\u003c/p>\u003cp>结果，我们大吵一架，孩子吓得哭都没有哭出来，应该受到了更大的二次伤害吧。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>处理好激动情绪，才能确保沟通的持续和有效。那么，如何正确处理激动情绪呢？拆页的三步法：\u003c/p>\u003cp>1、明确情绪的产生：\u003c/p>\u003cp>用第一人称“我”来标注。比如：我觉得不舒服，我觉得被冒犯了。这是在提醒自己，情绪来了，也是在提醒对方。\u003c/p>\u003cp>2、加强表达的程度：\u003c/p>\u003cp>如果第一步无效，就加强陈述情绪的程度。比如：我生气了，我特别生气，我要爆发了。情绪明确之后，需要被更清晰地看到。\u003c/p>\u003cp>3、坦陈感受和希望：\u003c/p>\u003cp>用事实说明情绪产生的原因，准确说出内心感受，同时用可执行的语言表达希望。一个好的句式是：我看到……我感到……我希望……\u003c/p>\u003cp>【举个例子】（正解）\u003c/p>\u003cp>回到刚才的例子，孩子打碎花盆，妈妈生气不原谅，我该怎么办呢？用这个方法，正确的处理路径是：\u003c/p>\u003cp>1、当我开始感受到自己的愤怒时，就要表达出来：孩子把你的花盆打破了，你很难过，他却意识不到，不知道怎么回事，不知道这会不会让你更生气。不过一再看到你不理他，推开他，我也感到很难受，我觉得你把孩子放在花盆后面了，孩子也有自己的感受，这让我有点生气了。\u003c/p>\u003cp>2、当孩子又去找你，你还是不理他，我看到他失望和受伤的眼神时，我更加生气了，特别难过，甚至很愤怒了，我们是成人，我们应该比孩子更懂事一点点。我们犯错都需要被原谅，为什么孩子犯错要如此苛责呢？\u003c/p>\u003cp>3、我看到孩子一次又一次跟你道歉，你却一直不理睬，我感到很难受，似乎在你眼里花盘比孩子更重要，我想你心里不是真的这么想。我希望你抱抱孩子，让他认识到错误，但这并不是一个足以让他感觉好像要失去妈妈的错误。如果你能带着他跟你一起去重新买一个花盆，带他种下一颗花，告诉他你与花的故事，我想这对他会是很好的一个教育。我去收拾，你抱抱他吧。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个处理激动情绪的方法，适用于你重视沟通对象且对沟通目标有一个正向预期的时候，当你感到自己要火了，对方要怒了，事情要失控了的时候，为了避免情绪宣泄和语言暴力造成不可挽回的恶性结果，就可以深呼吸三次，开始三个步骤，定义情绪、加强陈述和表达希望，来尝试改变沟通。\u003c/p>","interaction":"\u003cp>↓技能点：【A1】显像提问清晰，其中包含具体的情景。有学习者分享了自己根据这个场景联系出的过往情景或具体体验。\u003c/p>\u003cp>接下来，要请大家回想一下，你最近一周或一个月，有没有因为激动情绪爆发而导致了什么不良沟通结果的情况？\u003c/p>\u003cp>也许是和孩子谈学习习惯，和爱人盘点家庭债务，和甲方谈执行方案或者和同事明确工作责任，那是什么情况下，和谁的沟通呢？是谁先有了激动情绪？怎么处理的？结果怎么样？\u003c/p>\u003cp>请大家回想一下用1分钟时间写在便签上，然后每人用大约1分钟时间在小组内做分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：梦梦\u003c/p>\u003cp>上周，我的一个快递到了，给爱人发信息，说你下班帮我取一下快递吧。他说，我哪有时间给你取快递？\u003c/p>\u003cp>一句话把我气死了，我心想这平常让你帮我取个快递，你都没有时间？那还能指望你干什么？我们大吵了一架。到现在还在冷战中。\u003c/p>\u003cp>↓技能点：【A1+】反思加工指令清晰。有学习者根据指令，联系出了假如再遇到同样情况时，自己的具体做法。\u003c/p>\u003cp>接下来大家仔细想一下你刚才分享的真实经历，如果再次回到那个场景之中，你将如何运用我们今天学习的三步法，更好地去处理激动情绪呢？\u003c/p>\u003cp>请在便签上写下具体的应用内容，包括这三个步骤：明确定义、加强描述和表达希望。\u003c/p>\u003cp>并且，在小组内分享，还是每人约1分钟的时间。之后，我会邀请一位小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：梦梦\u003c/p>\u003cp>我要这么解决这个事情？\u003c/p>\u003cp>第一步，觉察到自己的情绪，因为他说这话，我就感觉到有点生气了。\u003c/p>\u003cp>第二步，我就要告诉他，你这样让我很生气，因为取个快递两分钟的时间，你都没有，这很不合理，我感觉到自己没有被重视。\u003c/p>\u003cp>第三步，我希望你下班之后抽出两分钟时间帮我取一下快递，如果实在不行，我自己取，但我们不要因为这件小事吵架了。\u003c/p>\u003cp>——感谢梦梦的分享。\u003c/p>\u003cp>从梦梦的分享中我感受到了你的真诚，你的收获和你传达出来的正能量，相信这对大家都是有益的。\u003c/p>\u003cp>处理激动情绪是有方法可以使用的，我们很多时候不是愚钝，也不是恶意，更不是为了解决对方，我们只是看错了角度，用错了方法。\u003c/p>\u003cp>通过今天的学习，我们掌握了处理激动情绪的方法：\u003c/p>\u003cp>首先能明确定义，我感到怎么样了；\u003c/p>\u003cp>其次加强描述，我现在非常怎么样了；\u003c/p>\u003cp>最后我为什么激动，我感受是什么，以及我希望可以怎么样。\u003c/p>\u003cp>通过这三个步骤，正确识别、理解及处理激动情绪，相信沟通可以让生活更美好。\u003c/p>\u003cp>大家的分享也让我受益良多，我的拆页就到这里，我们同学共进，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1690514320000,"updated_at":1690617387000,"ria":true},{"id":15907,"topic":"发怒的三个步骤","learn_goal":"","remark":"当孩子出现不良行为时，家长就只能忍忍忍，不能冲他发火吗？\n父母一味地忍气吞声，真的就是美德，是正确的吗？\n错！\n今天我们一起来学习如何正确地表达我们的愤怒\n通过现场学习后，学习者能够在发怒的或生气的情况下，\n学会运用“发怒的三个步骤”来合理的表达愤怒，避免矛盾升级，避免给他人带来伤害","level":"TF2-3","duration":25,"status":19,"type":0,"chaishujia":{"username":"季草集美业","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>一、自我介绍、学习目标、分组\u003c/strong>\u003c/p>\u003cp>【拆书技能】：学习目标均包含学习者可被观察到/被测量到的行为或动作，现场学习者设计都清晰体现了各自的学习目标。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家晚上好！非常感谢大家在百忙之中抽出时间来参加我的线下过级活动。\u003c/p>\u003cp>我叫陈芳，我有个姐姐叫陈芬，我妈妈希望我们姐妹俩像花朵一样美丽，所以以“芬芳”给我们取名。\u003c/p>\u003cp>三个标签简单地介绍一下我自己。\u003c/p>\u003cp>第一个标签：季草集美业顾问；我目前拥有一个自己小小的美容工作室。\u003c/p>\u003cp>第二个标签：孩子的学习提升导师；这是我和老公共同学习沟通的技巧和方法，可以实现与孩子之间的有效交流。\u003c/p>\u003cp>第三个：拆书帮一级拆书家；目前正在努力向二级奋斗。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在大家跟随我完成本次的RIA现场学习后，学习者能够在发怒或生气的情况下，学会运用“发怒的三个步骤”来合理的表达愤怒，避免矛盾升级，避免给他人带来伤害。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，由于今天的过级环节需要分组讨论一下，下面我来进行一下分组。我们有 9 位伙伴，就邻近的 3位老师为一组吧。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003c/p>\u003cp>【拆书技能】选择图书是实用类或理论类图书；在 FAB 介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>\u003c/p>\u003cp>今天我要给大家介绍的这本书是《孩子，把你的手给我》。作者是美国著名成人心理学教授、儿童心理学专家海姆·G·吉诺特博士。作者通过这本书教会我们如何提高沟通的技巧，以共情关爱的方式去了解孩子的感受，从而实现与孩子之间真正有效的沟通方式。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>\u003c/p>\u003cp>本书英文第一版出版于1965年，至今已经接近 60 年了，依然在全世界广受欢迎，真正做到了历久不衰。其中的许多理念，更被吉诺特教授的学生阿黛尔·法伯和伊莱恩·玛兹丽施在《如何说孩子才会听，怎么听孩子才肯说》等一系列亲子教育书籍中发扬光大。本书在美国的销量达到了500多万册，并被翻译成31种语言，畅销全世界，改变了无数家长与孩子之间的沟通问题。\u003c/p>\u003cp>\u003cstrong>【B1】\u003c/strong>\u003c/p>\u003cp>如果你还在为不知道怎么跟孩子沟通而苦恼，如果你的孩子经常让你情绪愤怒，那么这本书将教会你如何与孩子实现真正有效的沟通方法。\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>\u003c/p>\u003cp>当孩子出现不良行为时，家长只能忍忍忍，不能冲他发火吗？父母一味地忍气吞声，就是正确的吗？\u003c/p>\u003cp>答案当然是“错”……\u003c/p>\u003cp>今天这个片段将教会你一个不一样的解答方法。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>这份是我今天准备的原文拆页。现在请大家花2分钟的时间阅读一下，阅读完成的伙伴可以举手向我示意一下。好的，现在开始。\u003c/p>","ratings_count":1,"texts":[{"id":19993,"quote":"\u003cp>\u003cstrong>三、阅读原书拆页\u003c/strong>\u003c/p>\u003cp>【拆书技能】【R】所选拆页，可以是简单How的指令，也可以是隐含How的案例或故事；且总内容未超过 2 页图书内页。\u003c/p>\u003cp>\u003cstrong>发怒的三个步骤\u003c/strong>\u003c/p>\u003cp>在平静时期，让自己做好应付紧张时刻的准备，应该承认下面的事实：\u003c/p>\u003cp>1、我们接受这个事实：在跟孩子打交道的时候，我们有时会发脾气。\u003c/p>\u003cp>2、我们有权生气，而不必感到内疚或者羞愧。\u003c/p>\u003cp>3、除了安全考虑，我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格，我们可以表达我们的愤怒。\u003c/p>\u003cp>这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”：“我觉得讨厌。”“我觉得被激怒了。”\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有起效果，那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>“我生气了。”\u003c/p>\u003cp>“我很生气。”\u003c/p>\u003cp>“我非常非常生气。”\u003c/p>\u003cp>“我气极了。”\u003c/p>\u003cp>有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>\u003cp>“当我看到鞋子、袜子、衬衫、运动衫扔到满地都是时，我很生气，生气极了。我真想打开窗户，把这一摊乱七八糟的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟，我很生气，心里面像有团火在烧，我绝不允许你再伤害他。”\u003c/p>\u003cp>“看到你们所有的人一吃完晚饭就冲出去看电视，把那些脏兮兮的盘子，油腻腻的锅留给我时，我非常愤慨！气得我简直七窍冒烟！我真想把所有的盘子砸到电视上去！”\u003c/p>\u003cp>“我叫你吃晚饭，而你却不来，我很生气，非常生气，我对自己说：‘我煮了一餐好吃的，希望获得赞赏和感激，而不是失望！’”\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【拆书技能】【I】环节，给出了比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译。\u003c/p>\u003cp>我看到大多数伙伴已经阅读完成了。没有读完也没关系，接下来我会详细地详解。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段主要讲的是，在面对孩子不良的行为时，我们有权力生气，在生气或发怒的情况下，运用“发怒的三个步骤”安全有效地表达我们的愤怒，不攻击孩子的人格，不做过激的行为去伤害孩子。\u003c/p>\u003cp>\u003cstrong>【Why】（不这么做的坏处）\u003c/strong>\u003c/p>\u003cp>当孩子出现不良行为举止时，使我们感到很生气时，我们一般会怎么做呢？是没完没了地唠叨？是直接破口大骂？还是大打出手，来发泄自己的情绪呢？往往我们这样做的后果，只会换来孩子的反抗，或是一时的屈服，实际是没有从根本上解决问题，反而伤害了孩子的身心健康，破坏了与孩子之间的亲子关系，从而使孩子对家长堆积了很多的怨恨。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>我分享一个我自己不太好的案例。上个月的一个晚上，在家里书房里，大宝打开电脑，在电脑还没有运行正常的情况下，她就急切的把鼠标一通乱点，导致电脑卡死，死机一样无法正常运行了。大宝嘴里还一直叫骂“什么破电脑”。我一直在旁边提醒她，不要着急，耐心地等一会，等程序运行完了再打开网页。她当时不耐烦地答应着“哦哦哦……”，但是手还是拿着鼠标跟点炮一样的，啪啪啪……。我见她依然我行我素的，我也急了，没有忍住情绪，一巴掌过去，打在了她握鼠标的手上，并大声地怒吼到“你今天不准再碰电脑了”。大宝也是怒气冲冲地回到卧室，把房门哐当一声关上了。\u003c/p>\u003cp>听到关门的声音，我才突然有点自责，似乎自己刚才的反应有些过激了。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那我们如何正确地发泄情绪，不让类似的事情再发生呢？下面我们一起来学习“发怒的三个步骤”。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 承认事实。\u003c/strong>\u003c/p>\u003cp>首先我们要接纳和孩子一起相处，孩子做出不良行为时，在不伤害孩子人格及人身安全的前提下，我们是有权力生气的，不必感到自责或内疚。\u003c/p>\u003cp>\u003cstrong>2. 表达感受，加强愤怒的强度\u003c/strong>\u003c/p>\u003cp>我们可以使用第一人称代词“我”来表达自己此时的感受。例如，可以跟孩子说：“我现在很生气”。如果依然没有效果，我们可以加强语气，严肃地看着孩子，说：“我现在非常非常地生气”。\u003c/p>\u003cp>\u003cstrong>3. 解释我们生气的原因，说出内心的想法和希望孩子的行为。\u003c/strong>\u003c/p>\u003cp>第三步里描述了三个动作，分别是第一，解释生气的原因；第二，说出内心的想法；第三，希望孩子的行为。其中，说出内心的想法和希望孩子的行为，这个大家应该很好理解吧，也比较容易做到。\u003c/p>\u003cp>但是，许多人其实解释不清楚自己生气的原因的。他们会用语言或动作直接表达生气。但对方只能看到你生气的状态，并不一定了解你生气的原因。所以，务必要把生气的原因说清楚。\u003c/p>\u003cp>那么，如何能把生气的原因说清楚呢？我接着作者的介绍，把解释原因这个步骤细化为两个行动步骤：\u003c/p>\u003cp>\u003cstrong>【细化行动步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 描述期望的状态\u003c/strong>。\u003c/p>\u003cp>比如，可以说妈妈希望看到的是摆放整齐的房间，可以说希望听到你们有条理地表达，或者说希望你们赶快把饭吃完。这些都是描述家长期望的状态。\u003c/p>\u003cp>\u003cstrong>2. 描述不好的现状\u003c/strong>。\u003c/p>\u003cp>不带评判地描述看到的、听到的状态。比如房间摆放较乱，比如孩子大喊大叫等，比如吃饭时话多等。只需要简单、客观地描述出现状即可。\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>\u003c/p>\u003cp>那刚刚和大家一起学习了“发怒的三个步骤”，再回到我前面跟孩子发生冲突的案例上，我一定会这样做：\u003c/p>\u003cp>1. \u003cstrong>承认事实\u003c/strong>；\u003c/p>\u003cp>在不伤害孩子人格和人身安全的前提下，我有权力生气，不必为自己的行为而感到自责和内疚，从心理上接受这个事实。\u003c/p>\u003cp>2. \u003cstrong>表达感受\u003c/strong>；\u003c/p>\u003cp>表达我此时的感受并加强愤怒的强度。我可以目光严肃、认真地注视孩子，跟她说：“我现在很生气，我现在非常非常地生气”。\u003c/p>\u003cp>3. \u003cstrong>解释原因\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>关于描述期望的状态\u003c/strong>，我会跟孩子说：“妈妈希望你能耐心地等待电脑程序运行完，再点击你要打开的网页。”\u003c/p>\u003cp>\u003cstrong>关于描述不好的现状\u003c/strong>，我会跟孩子说：“我已经很耐心地提醒你很多次了，电脑开启后，需要耐心给它一点时间，等它运行完程序，可是你不听，最后电脑肯定会卡机死机啊。”\u003c/p>\u003cp>用完以上这三个方法跟孩子沟通，我相信孩子也会对我们与她的沟通方式所打动，对自己的不良行为有所收敛。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>这个方法不仅适用于跟孩子之间的沟通，也适合跟同事，朋友，家人之间的沟通。如果是跟长辈或老师及不熟的人，就不太合适。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>【拆书技能】【A3】环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>那接下来我提供一个场景，请大家运用今天所学的这三个步骤来进行演练一下。\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>假设这个场景：一个周一的早晨，你一个人忙出忙进，很早就起床给孩子们准备上学前的一系列，早饭、水杯、餐具等。这时孩子的房间传来了一阵急促的、催魂夺命的嚎叫声：“妈妈，我的袜子找不到了，为什么我的袜子只有一只”。此前，你也经常告诉孩子，如果有衣服或者袜子类的找不到，它可能就在阳台的晾衣架上，可以自己去阳台找。显然此时孩子并没有把你的话听进去。你此时也是怒气冲冲地走到她房间去，接下来你会跟孩子怎么进行沟通和交流？\u003c/p>\u003cp>请大家现在花4分钟时间在小组内讨论一下，我一会儿请两位小伙伴来演练一下这个场景。\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>陈晓庆老师：饰母亲\u003c/strong>\u003c/p>\u003cp>\u003cstrong>丹丁先生：饰儿子\u003c/strong>\u003c/p>\u003cp>子：我的袜子呢？我的袜子呢？我的袜子呢？\u003c/p>\u003cp>母：昨天晚上给你放到床头柜上的呢。你自己先找找吧，妈妈现在正忙着呢。\u003c/p>\u003cp>子：找不到啊。快点，快点，马上要上学了啊。快点，来帮我找。\u003c/p>\u003cp>母：（来到儿子房间）给，就这双，快点穿上吧。\u003c/p>\u003cp>子：不要。这个袜子不行，太大了。\u003c/p>\u003cp>母：那你想要穿什么样的袜子？这不就是给你买的吗？\u003c/p>\u003cp>子：不行，学校不允许穿这种颜色的袜子。\u003c/p>\u003cp>母：那你就不要穿袜子了，就光脚穿球鞋吧。\u003c/p>\u003cp>子：不行，还是要给我找。\u003c/p>\u003cp>母：我昨天晚上 8:00 就把衣服给你找好了。现在你又说袜子不好。妈妈非常生气。我把衣服帮你放好，本来希望你一起来就能自己穿好衣服。但是，我看到你要妈妈帮你找衣服，找好后你又嫌这嫌那。我觉得这样不好。我希望你现在要么把袜子穿好，要么就不要穿袜子了。\u003c/p>\u003cp>子：好吧，那我就穿上这双吧。\u003c/p>\u003cp>\u003cstrong>【反馈】\u003c/strong>\u003c/p>\u003cp>好的，感谢陈老师和丁舵给大家带来的精彩表演。\u003c/p>\u003cp>两位老师把今天的这三个步骤用得很恰当的，我们也可以看到，两位老师运用了这三个发怒的步骤，提高了与孩子之间的有效沟通，避免了孩子抵触反抗的情绪，减少了伤害孩子心理健康的问题，同时也避免了一场亲子大战。\u003c/p>\u003cp>【拆书技能】【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/p>\u003cp>\u003cstrong>六、总结\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书技能】：\u003c/strong>总时长没有少于20分钟，没有超过25分钟。\u003c/p>\u003cp>希望我今天分享的“发怒三步法”：\u003c/p>\u003cp>1. 承认事实\u003c/p>\u003cp>2. 表达感受\u003c/p>\u003cp>3. 解释原因\u003c/p>\u003cp>能让孩子知道我们发怒的原因，而不是单纯地情绪发泄。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1685428497000,"updated_at":1686549878000,"ria":true},{"id":15807,"topic":"孩子，把你的手给我","learn_goal":"","remark":"无","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"艾玛舟","city":"苏州市"},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>开场：自我介绍\u003c/p>\u003cp>大家好，我是周艳，很高兴和大家相聚在这里。我首先是一个7岁男孩的妈妈，是孩子让我成长，我非常享受妈妈这个身份。其次是我一个外企学习发展部负责人，这样的一个身份把我和学习阅读紧紧的绑定在一起，从而让我能有学以致用的舞台。再次，我是拆书帮三级拆书家垭兰师父的徒弟，正式踏入拆书帮的花园，我看到很多美丽的娇艳的绽放的花朵，我也很庆幸，我也有一个自己的师父一路指引着我。\u003c/p>\u003cp>书籍介绍\u003c/p>\u003cp>我带给大家的拆页来自《孩子,把你的手给我》\u003c/p>\u003cp>美国，海姆·G·吉诺特,心理学博士、临床心理家、儿童心理学家、儿科医生；纽约大学研究生院兼职心理学教授、艾德尔菲大学博士后。\u003c/p>\u003cp>吉诺特博士的一生并不长，他将其短短的一生致力于儿童心理研究以及对父母和教师的教育。他依靠他的职明才智做了很多创造性的工作，取得了巨大的成就。他在他的书中、演讲中、专栏中宣传的如何跟孩子沟通的创新思想不仅在美国，甚至在全世界都获得巨大反响。\u003c/p>\u003cp>和孩子对话是一门有规则的独特艺术，有它自己的含义。孩子的信息里经常有需要解读的密码。在心理疗法中，从不会对孩子说，“你是个好孩子”或者“你很棒”。不要恐吓、贿赂，也不要许诺、挖苦。培养孩子的责任感，就是在跟他们有关系的事情上让他们有发言的机会。父母知道每个孩子都会担心和焦虑，但是他们不明白这些焦虑的来源。\u003c/p>","ratings_count":1,"texts":[{"id":19895,"quote":"\u003cp>处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”:“我觉得讨厌”“我觉得被激怒了”。\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有产生效果，那么采取第二个步骤。在表达时加强愤怒的强度：“我生气了。”“我很生气。”“我非常非常生气。”“我气极了。”有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。\u003c/p>\u003cp>但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>\u003cp>“当我看到鞋子、袜子、衬衫、运动衫扔得满地都是时，我很生气，生气极了。我真想打开窗戶，把这一摊乱七八糟的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟，我很生气，心里面像有团火在烧，我决不允许你再伤害他。”“\u003c/p>\u003cp>看到你们所有的人一吃完晚饭就冲出去看电视，把那些脏兮兮的盘子、油腻腻的锅留给我时，我非常愤慨！气得我简直七窍冒烟！我真想把所有的盘子砸到电视上去！”\u003c/p>\u003cp>“我叫你吃晚饭，而你却不来，我很生气，非常生气，我对自己说：‘我煮了一餐好吃的，希望获得赞赏和感激，而不是失望！&#x27;”\u003c/p>\u003cp>这个方法可以帮助父母释放怒气，而不致引起伤害，而且，它甚至可以是一堂重要的课，教会孩子如何安全地表达愤怒。孩子可能会明白他自己的愤怒也不是什么大的灾难，可以释放出来，而不会伤害任何人。这堂课不仅仅需要父母把怒火发泄出来，还需要父母向孩子指出情感表达的可接受的方式，要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>这个片段讲的是如何使用正确的方式来表达发怒，避免乱发脾气指责和攻击孩子品格。\u003c/p>\u003cp>Why\u003c/p>\u003cp>不正确的发怒方式往往容易用错表达的方式，如嘲讽，大声吼叫。这样的方式很容易直接攻击孩子品格，带给孩子恐惧，打击孩子的自信心，让孩子认为自己是不好的。如你已经三番五次跟孩子交代过玩过的玩具要收拾和整理，但当你推开门，看到家里满地狼藉，一片混乱的时候，你可能会怒火中烧，如你不乖，不听话，不爱干净，不遵守规则等恶狠狠的话脱口而出。相反的，如果你正确而清楚表达了自己的怒气时，孩子不仅仅知道自己的行为是错误的，而且还能承认错误，做出改变。\u003c/p>\u003cp>想象一个小长假的一天，你已经提醒孩子写作业提醒了4-5次，眼看一天时间就要结束，孩子仍然无动于衷的情况下，你会怎么处理？\u003c/p>\u003cp>在阅读的过程中我发现有一个片段可以正确的传达我们的愤怒。\u003c/p>\u003cp>How\u003c/p>\u003cp>正确表达愤怒可以通过3个步骤来实现\u003c/p>\u003cp>1.第一步：陈述事实，表达感受，表达自己的感受，避免对孩子直接指责。如，我生气了，你语文作业还没开始写，我提醒你三次了。\u003c/p>\u003cp>2.第二步：加强愤怒，用程度副词加强表达，如 我提醒你那多次你还是在玩玩具，我非常生气，我真的想把你的作业都扔出去，这样我就不用提醒你了。\u003c/p>\u003cp>3.第三步：解释原因，说出想法和希望。如 我提醒你写语文作业很多次，你手里拿的还是玩具，而不是语文作业，我觉得非常恼火，我希望当我提醒你的时候，你能行动起来而不是对我的提醒无动于衷，合理安排时间。\u003c/p>\u003cp>三个步骤是层层递进的，有时候第一个步骤就能起到提醒效果，而有时候需要用第三步的方式来实现，总之通过正确的愤怒表达可以表达自己的情绪，影响对方的行动，而不是诋毁和指责。\u003c/p>\u003cp>Where\u003c/p>\u003cp>表达愤怒的三步骤可以用在和孩子的互动场景中，在生活和工作中需要表达愤怒的场景中也同样适用。\u003c/p>","interaction":"\u003cp> A1\u003c/p>\u003cp>昨天晚上我的女性朋友丽丽因为加班原因回到家里已经8点了，不幸的是，她再一次和自己的婆婆之间发生了不愉快。一回到家婆婆大人就黑着脸，骂骂咧咧表达愤怒，抱怨丽丽的老公刚子不回家不提前说一声，导致做饭也做多了，孩子不听话在别人家喊不回来导致婆婆无法做晚饭，抱怨夫妻俩人不管小孩。一通抱怨之后，丽丽直接被带跑偏了，她觉得自己已经在需要兼顾工作的情况下非常关照家里和孩子，而还要被婆婆指责。于是她没好气的对婆婆说，你儿子的不对，你当着他的面说啊，跟我说有什么用。俩人关系陷入了僵局。\u003c/p>\u003cp>\u003cstrong>激活经验（4分钟）：\u003c/strong>\u003c/p>\u003cp>冲突是常见的，而表达愤怒确实是很多人不会掌握的。我邀请大家回想一下自己的相关经历，不管是在家里或者是在公共环境中，你和孩子之间你怒火中烧，孩子也强力反抗，鸡飞狗跳的情景。又或者是你是如何成功的Hold住局面的经历，请大家思考一下，稍后我们请1个小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>学习者倩倩提供的案例：\u003c/strong>\u003c/p>\u003cp>老公一到家就坐在沙发上打游戏看电视，不管孩子写作业，我非常生气，因此和老公直接发生了冲突。说他有时候也好像听不到一样。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用（4分钟）：\u003c/strong>\u003c/p>\u003cp>大家刚才探讨了自己的体验和经历，也总结了很棒的正确的表达愤怒的方法。接下来我请大家结合今天的分享，写下今后如何应对的规划，请写具体的做法，要有明确的时限，有可以量化或可以观测的预期结果。 请大家根据刚才的事例，讲一下今后如何应用发怒三部步法来应对，在小组内分享。\u003c/p>\u003cp>\u003cstrong>学习者倩倩的A2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>之前对老公是一顿职责谩骂，问题没有解决，两个人都不开心。运用表达愤怒三步法\u003c/strong>\u003c/p>\u003cul>\u003cli>我看到孩子写作业的时候你看电视，而且声音很大，影响到了孩子的写作业。\u003c/li>\u003cli>我已经提醒了你N次了，而且你仍然在看，而且声音没有降低，我非常恼火，我真想把电视砸了。\u003c/li>\u003cli>我不是说阻止你看电视，而是希望你能选择一个合适的时间。孩子写作业的时候，我希望可以为他营造良好的环境，如果你特别想看，可以到房间去，这样不会影响孩子写作业。\u003c/li>\u003c/ul>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>希望今天大家今天学会的发怒三步骤的方法和行动计划，都能用起来。这样才会让我们不断的成长和进步，感谢大家到来，希望分享对大家有帮助，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1684285971000,"updated_at":1684474604000,"ria":true},{"id":13731,"topic":"发怒的三个步骤","learn_goal":"","remark":"沟通需要方法，发怒同样需要方法，\n掌握好发怒的三步法，可以有效降低孩子产生敌对\n情绪，而是明白家长发怒的程度和原因，使孩子在\n不恐慌中解决问题，增强有效沟通。要改变根深蒂\n固的习惯思维和条件反射，请牢记这句话“教育孩\n子也需要技巧”","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"流沙103","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>开场：\u003c/p>\u003cp> 大家好，我是刘莎。三个标签来介绍我自己。我是第六届微课大赛大赛的全国九强。我是一名瑜伽教练，同时也是手作沙龙代领人。感谢大家这么晚在线上还能陪伴着我们一起学习的成长。那么对于拆书帮，在去年2021年的四月份加入会员，经过参加一些活动，开始对拆书帮有所了解。拆书帮本身是一个非盈利性的组织，是赵周老师为了青年人更好的能够去促动学习，帮助更多的人把书籍拆为己用的这么一个组织，那么赵周老师。不会用解决我们的这些实用性的。拆书法是一种学习的方法论，它可以解决我们在现实当中看书看不进去，学不会，不会用等问题，来提升我们读书的一个能力和效率。在这个RIA便签法当中，R是代表阅读原文，也就是我们整本书的某一个片段。I是我们拆书拆书家的拆解和引导，A又分两部分，A1是过去的一些故事。A2是将来的一些行动计划。RIA便签法能够触动我更高效，更完整的去学习。那么好，言归正传，把我们的注意力放到今天我给大家带来的片段上，我今天练级的级别是TF1-1，片段来自于《孩子把你的手给我》这本书，作者是美国作家\u003ca href=\"https://book.douban.com/author/290004\">海姆·G.吉诺特。那么现在给大家两分钟的时间，大家阅读一下原文。嗯，阅读完了之后，小伙伴们可以在屏幕上敲一，我就知道大家阅读完了。好的，我们可以开始阅读了。\u003c/p>","ratings_count":2,"texts":[{"id":17762,"quote":"\u003cp> 处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”:“我觉得讨厌”“我觉得被激怒了”。 如果简短的陈述和拉长着的脸并没有产生效果,那么采取第二个步骤。在表达时加强愤怒的强度：  “我生气了。”  “我很生气。”  “我非常非棠生气。  “我气极了。”  有时,仅仅表达出我们的感受(不用解释原因)就能让孩子停止不端行为。但是,有时候,可能需要采取第三个步骤解释我们生气的原因,说出我们内心的想法,以及我们希望的行为。“当我看到鞋子、袜子、衬衫、运动衫扔淂满地都是时  我浪生气,生气极了。这堂课不仅仅需要父母把怒火发泄出来,还需要父母向孩子指出情感表达的可接受的方式,要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>","explains":"\u003cp>好的，我看大家已经看完拆页了\u003c/p>\u003cp>【what】本片段讲述了父母正确发泄愤怒的“三部曲”，既宣泄了自己的不满情绪，也不会因为怒发冲冠而伤害到孩子的自尊心。\u003c/p>\u003cp>【why】当孩子不符合自己心意的时候，家长总是控制不住情绪，冲动的举动和言辞重伤孩子，事后又会后悔、愧疚。片段中的方法既不憋屈自己，也不伤孩子，就事论事，妥帖处理敏感的亲子关系。\u003c/p>\u003cp>【how】发泄情绪，消除愤怒的正确“打开方式”：\u003c/p>\u003cp>1、接受事实：接受自己生气的事实，把自己情绪的主体，压抑情绪并不能改变现状。\u003c/p>\u003cp>2、识别强度：愤怒的情绪也是有“级别”的，可以根据现状加以识别愤怒等级。\u003c/p>\u003cp>3、说出原因：让孩子知道家长生气的原因，让他知道如何改变才能化解家长的愤怒。\u003c/p>\u003cp>【where】有效发泄愤怒的“三部曲”还可以用在夫妻关系和同事关系中。\u003c/p>","interaction":"\u003cp>Ａ1\u003c/p>\u003cp>故事：上周末带着孩子和朋友们聚会，由于孩子吃零食喝饮料没有节制，导致转天开始拉肚子。我气呼呼的冲孩子嚷嚷：“不知道自己的肠胃弱吗？还不知道自己克制少喝点凉饮料，看，拉肚子了吧。”孩子弱小无力反驳，眼泪啪嗒啪嗒的往下掉。\u003c/p>\u003cp>反思：因为心疼孩子，心里着急，一时没忍住，实际上拉肚子已经成为事实，生气是正常的，为了发泄自己的情绪直接把全部的锅都甩给了孩子，却没有说清生气的原因。\u003c/p>\u003cp>A2\u003c/p>\u003cp>目标：本周再遇上孩子写作业拖拉的时候，改变大吼大叫得方式\u003c/p>\u003cp>行动：发现孩子写作业拖拉，不专心时\u003c/p>\u003cp>1、接受自己生气的事实，把自己作为生气的主体，强调“我”生气了。\u003c/p>\u003cp>2、再识别生气的程度，我“特别”生气。\u003c/p>\u003cp>3、说出生气原因，跟孩子说：我特别生气，因为你刚刚写作业一点都不专心，如果你是因为不会可以请教妈妈或老师，边写边东瞧瞧西看看拖拖拉拉才是让我特别生气的原因，妈妈希望你能自己有计划的安排好时间，学时专心学，玩时专心玩。\u003c/p>\u003cp> 希望大家通过今天一同学习，能够用到三步法有效改善愤怒，使生活更加美好，我今天的拆书分享就到这里，感谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1657329640000,"updated_at":1658283617000,"ria":true},{"id":13571,"topic":"《LED情绪缓解法》","learn_goal":"","remark":"LED情绪缓解法","level":"TF2-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"王文婷Jessica","city":"深圳市"},"club":{"name":"深圳智成分舵","city":"深圳"},"prologue":"\u003cp>在跟随我完成本次RIA现场学习后，学习者将能够运用一套与青少年孩子沟通的“LED”三步骤，在孩子被某件事情困扰而产生情绪的时候，帮助孩子舒缓情绪，增进相互理解并促进亲子关系。\u003c/p>\u003cp>尊敬的观察家、各位亲爱的小伙伴，晚上好！ \u003c/p>\u003cp>我是今天晋级2-2的王文婷。 用3个标签介绍自己，分别是“蒙特梭利主教”蒙特梭利主班老师、“妈妈”和“儿童游戏式学习法研究者”。\u003c/p>\u003cp>现在我把大家分成两个组——这边的朋友是一组，那边的朋友是一组。 每组里面头发最长的那位伙伴担任组长，待会儿来组织一下分享。\u003c/p>\u003cp>今天给大家带来的拆页来自（F）《孩子，把你的手给我II》，本书是美国著名的心理学博士、儿童心理学家海姆·吉诺特所著，传授与青少年孩子实现真正有效沟通及和谐相处的方法。 （A）相比其他同类书籍，这本书一出版就登上《纽约时报》畅销书排行榜，并在榜单上停留了25周之久，并且被翻译成31种语言引入全球各地。 在国内，这本书的豆瓣评分高达8.8分，被奉为“教子经典”。(B1)众所周知，十几岁的青少年孩子具有不同于低龄儿童的特质，给父母们带来许多挑战和困扰。 这本书就教给父母们很多实用的知识和技巧，帮助父母与青少年孩子相互尊重、和谐共处。（B2）今天的拆页将聚焦于当孩子被某件事情所困扰而产生情绪的时候，如何同孩子沟通，以帮助孩子纾解情绪、增进相互理解并促进亲子关系。\u003c/p>","ratings_count":2,"texts":[{"id":17599,"quote":"\u003cp>这次要拆的原文片段来自于这本书的第3章，“首要原则是不伤害孩子”。 现在，请大家用2分钟的时间阅读下手中的拆页，阅读完后请举手示意我。\u003c/p>\u003cp>向十几岁的孩子表明沟通和交谈的富有成效的方法，是父母的责任。比如:\u003c/p>\u003cp>专注地倾听\u003c/p>\u003cp>复述对方的要点\u003c/p>\u003cp>不要批评和骂人\u003c/p>\u003cp>陈述自己的观点\u003c/p>\u003cp>当我们更注意地听并以一种同情的语调做出回应时，就能得十几岁孩子的注意。当我们将孩子说的不清楚的事情清晰地表达出来时，就能赢得孩子的心。当我们真诚，当我们使用的言词适合自己情感的时候，就能得孩子的尊重。下面几个故事，说明了父母怎样来使用承认孩子感受的方法。\u003c/p>\u003cp>十五岁的科拉正在抱怨，因为她的妹妹溜冰去了，弟弟打保龄球去。\u003c/p>\u003cp>科拉:他们总是有事可干一去溜冰、打保龄球。我在他们这么大的时候，什么事都不让我干。你们从来不带我去溜冰。\u003c/p>\u003cp>母亲:哦，亲爱的，你知道那个时候你的医生不允许你去溜冰。\u003c/p>\u003cp>父亲:你忘了你那时病了。再说，我们在一起干过很多事情。\u003c/p>\u003cp>科拉:我不记得干过什么事情。你们没有带我去过任何地方。\u003c/p>\u003cp>母亲和父亲(异口同声地反驳):但是，科拉，我们确实带你出去过。你不记得带你去马戏团了?不记得带你去加拿大旅游了？\u003c/p>\u003cp>这时，母亲改变了方法。\u003c/p>\u003cp>她立即理解了科拉的感受，并跟丈夫说:“科拉觉得自己被剥夺了玩的机会!她真的觉得自己被忽略了!”“没错，我就是这种感觉。”科拉大声地肯定道。\u003c/p>\u003cp>母亲:原因并不重要。如果你是这种感受，那事情对你来说就是这样。\u003c/p>\u003cp>科拉(平静地):没错!\u003c/p>\u003cp>这个问题引起的紧张消除了，争论停止了。这位母亲说这件事让我明白了，推理和逻辑无法让一个处于一定情感状况的十几岁孩子的需要得到满足。还让我知道了，可以在处理孩子情绪的过程中改变方法。\u003c/p>","explains":"\u003cp>\u003cstrong>【Why】\u003c/strong>孩子与我们成年人一样，也会因为某些事件产生情绪困扰，回想以前，当发现孩子莫名其妙地冲我们发脾气或者说些明显带情绪的话语的时候，我们不是试图跟孩子讲道理，就是大声斥责孩子，最终孩子可能再也不愿意跟我们沟通交流了。本章就提供了一种以孩子能接受的方式，回应和支持孩子，承认并映射孩子的感受，最终舒缓双方情绪，增进亲子关系。 \u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这段拆页就介绍了一个当孩子因为某些事产生情绪困扰的时候，家长可以运用的沟通三部曲。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>具体来说，就是这样的3个步骤——\u003c/p>\u003cp>L：1、Listen专注倾听，停下手中的事，注视孩子的眼睛，认真倾听TA说的话；\u003c/p>\u003cp>E：Empathize2、同理感受，站在孩子的角度，表达TA的感受；\u003c/p>\u003cp>D：Describe 3、描述观点，说出自己针对这件事的看法，注意态度要真诚，内容要客观。\u003c/p>\u003cp>在整个过程中，家长都要小心避免对孩子批评、指责，更不要说打骂。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>这个三部曲不仅适用于当青少年孩子出现情绪困扰时，家长予以应对，也适用于其他年龄段的孩子，甚至成人遭遇类似问题的时候，我们去协助对方纾解情绪并增进相互之间的理解。\u003c/p>\u003cp>举个例子，有一次我跟女儿去逛商场，在我们即将要离开的时候，我女儿要买一张带钻的贴纸，我看了下价格，一张贴纸要十几块。我就不同意买。我女儿开始发脾气，双手抱胸，嘴里发出“哼哼声”，同时不肯离开商场。我蹲下来，看着她，问：“你怎么了？”她说：“你每次都只买你喜欢的东西，我喜欢的都没有买。” 我认真地听她说话。 这是第一步：专注倾听。\u003c/p>\u003cp>我接着说：“这个贴纸亮闪闪的，很漂亮，你真的很想要”。 这是第二步：同理感受。\u003c/p>\u003cp>我女儿点头说：“恩，是的。” 我打开手机淘宝边给她看边说：“你看下，同款贴纸在淘宝上才卖5块钱，节约下来的钱，我们可以买点好吃的。”这是第三步，描述观点。\u003c/p>\u003cp>\u003cstrong>【异议处理】\u003c/strong>可能有人会提出来，如果孩子听你说完，还是我行我素怎么办？是的，LED三个步骤主要是帮助孩子舒缓情绪，同理孩子感受，因为只有情绪被处理好了，孩子的抵抗心理也会逐渐减少甚至消失，这样孩子也会更加乐意接受你的观点。如果你说完孩子还是继续发脾气怎么办呢？这就需要我们静下来，仔细回忆一下孩子发脾气之前，TA在做什么，然后用诚恳的态度去跟孩子交流，引导孩子表达，再认真听孩子说什么，这样就可以进入“LED”三步骤了。\u003c/p>","interaction":"\u003cp>接下来我们来做一个运用刚才学习到的内容的活动——\u003c/p>\u003cp>第一步，请你想象一下，在未来一周内你可能就会遇到的一个生活或工作中的被某件事情困扰而产生情绪的实际场景，比如孩子想要去同学家，但是因为作业没有完成所以你不同意，于是孩子大发脾气，或者你一回家，婆婆就开始抱怨你今天加班加太迟了，她带了很久的孩子非常辛苦，手都举不起来了。本来应该今天给同事交材料，但是因为领导迟迟无法决定用哪份材料，以至于你工作超期，同事一看到你就冲你发脾气，说你耽误了他的工作。 请想一下，那会是一个什么样的场景呢？ 请写在便签上。 \u003c/p>\u003cp>\u003cstrong>【学习者案例记录1】\u003c/strong>\u003c/p>\u003cp> 我们班级小朋友进班之后，是需要更换室内鞋的，有个小朋友上学期就是怎么样都不肯更换，你让他换，他就尖叫，好不容易请他脱下来室外鞋，他还会丢的特别远。现在疫情停课这么长时间了，马上又要开课了，我担心这个小朋友又会出现同样的事情。\u003c/p>\u003cp>第二步，根据刚才你想象到的那个情境，再设想一下：现在那个产生情绪的人就在你面前，你正想开导开导TA。 突然，你想起来今天在拆书晋级的现场听到的“沟通三部曲”的内容。 那么按照这3个步骤—— 1、专注倾听；2、同理感受；3、描述观点——你可以怎么样帮助TA纾解情绪、增进理解呢？ 请思考一下，然后在便签上写下你的具体做法。\u003c/p>\u003cp>有没有哪位朋友愿意跟大家分享一下？ 有请——\u003c/p>\u003cp>\u003cstrong>【学习者案例记录2】\u003c/strong>\u003c/p>\u003cp>第一，我会认真倾听这个小朋友为什么不愿意换室内鞋的原因，可能他会说，妈妈给他的新鞋子特别不好脱。\u003c/p>\u003cp>第二，我会认同他的感受，我会说，是的，这个鞋子带了鞋带，有点紧，不好脱。也不好穿。\u003c/p>\u003cp>第三，我会跟他说，今天我会帮助他一起脱跟穿鞋子，放学以后，我还会跟你妈妈说，请他帮你换一双你能自己穿脱的鞋子好吗？\u003c/p>\u003cp>通过这三个步骤，让孩子舒缓情绪，并且自愿去更换室内鞋。\u003c/p>\u003cp>今天向大家介绍了一套因某事产生情绪困扰的时候，帮助对方纾解情绪、增进相互理解的LED沟通三部曲：\u003c/p>\u003cp>1、专注倾听；2、同理感受；3、描述观点。\u003c/p>\u003cp>希望能帮助大家更好地应对生活和工作中的类似场景，并且增进与对方的关系， 谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1655102788000,"updated_at":1657166255000,"ria":true},{"id":12832,"topic":"对生气孩子的回应：方法最重要","learn_goal":"","remark":"当孩子生气有情绪的时候，讲道理、给建议是不奏效的。只有情绪被看见、被理解，情感上得到安慰，他们才会听得进“谏言”。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"杨飞","city":""},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>各位小伙伴，上午好！我叫果妈，是一名大学老师、有书读书会的组织者之一、二胎宝妈。现在我们做一下分组，请从我右手边开始两人分为一组，等会会有小组讨论，谢谢。\u003c/p>\u003cp>\u003cstrong>【场景法介绍图书】\u003c/strong>简单的介绍一下今天带拆的图书：\u003c/p>\u003cp>\u003cstrong>【事件】\u003c/strong>你和孩子约好周末去郊游，突然接到老板电话要求紧急加班，你和孩子讲道理，可孩子说这是你们早就约定好的事情，非常生气，听不进任何解释，你觉得孩子不讲理，批评了他两句就急着走了，留下孩子哇哇大哭；弟弟打碎了哥哥心爱的玩具车，哥哥生气直瞪眼睛，你说就一个玩具，不值得生这么大的气，下次给你再买一个。\u003c/p>\u003cp>\u003cstrong>【提问\u003c/strong>】大家想一想，遇到这类事情，你之前的处理效果怎么样？面对生气的孩子，想不想让对方情绪稳定下来，并听从你的建议或意见呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>当孩子正在生气的时候，你如果只是给他讲道理、批评、嘲笑、建议等等，是不奏效，只会让他越来越生气，导致对抗加剧。长此以往就会积累负面情绪，影响双方的有效沟通。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>那么《孩子，把你的手给我》中回应生气的孩子的四个步骤会告诉你怎样去化解孩子的情绪、指出问题所在，并最终给出解决问题的建议，只有这样才能平息孩子的情绪、解决问题。\u003c/p>","ratings_count":1,"texts":[{"id":16790,"quote":"\u003cp>\u003cstrong>【R】原文片段：\u003c/strong>\u003c/p>\u003cp>《孩子，把你的手交给我》P47--48\u003c/p>\u003cp>汤姆和他的朋友吉姆，两个人都才三岁，他们在玩玩具木琴。吉姆的音锤卡住了，生气地哭了起来。他的妈妈警告他说：“你没有理由大哭大闹的，我不会给你修音锤，除非你停止尖叫。”吉姆继续哭闹，于是他的妈妈拿走了玩具。这一下，吉姆大发脾气，场面颇为壮观。\u003c/p>\u003cp> 与吉姆的例子形成对照的是，汤姆的音锤也卡住了，他也哭了起来，他的妈妈对他说：“你哭是因为音锤卡住了，我们需要修好它。”哭声停止了。现在，无论什么时候音锤被卡住，汤姆都不会再哭，而是拿过去让妈妈修理。\u003c/p>","explains":"\u003cp>今天分享的主题是对生气孩子的回应：方法最重要。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次RIA学习后，希望大家能够运用（行为）回应生气对象的四步骤（澄清），来接纳生气者的情绪，寻找情绪的源头，从而解决他的情绪问题。\u003c/p>\u003cp>【A1】大家自测：\u003c/p>\u003cp>为了让大家能够更加清晰地了解自己面对情绪对象尤其是亲密家人或朋友时的应对能力，请大家做一个简单的测试。以下5个题目请按照1-5分的标准给自己打分，1代表完全不符合，5代表完全符合。\u003c/p>\u003cp>请大家花1分钟的时间，仔细阅读下面表格中的每句话，根据自己实际情况凭第一直觉为自己打分，并汇总分数，做好的小伙伴可以示意我一下：\u003c/p>\u003cp>【自测解释】\u003c/p>\u003cp>这个自测能帮我们了解自己在面对有情绪的家人或朋友时的应对能力。总分25分。\u003c/p>\u003cp>请大家对照一下自己的得分：\u003c/p>\u003cp>【结果】\u003c/p>\u003cp>请总分20分以上的小伙伴请举手：\u003c/p>\u003cp>说明你已经有很好的同理心和解决问题的能力。通过本次拆书学习，可以更进一步巩固这种能力哦。\u003c/p>\u003cp>请总分10-19分的小伙伴举手：\u003c/p>\u003cp>说明你有较好的同理心和解决问题的能力。通过这次学习，可以提升咱们的共情能力和解决问题的能力。\u003c/p>\u003cp>请总分10分以下的小伙伴举手：\u003c/p>\u003cp>你们可能会是这次拆书进步最大的人哦，平常的你可能会被对方的情绪感染而变得烦躁，今天的学习会给你不同的视角和思路！\u003c/p>\u003cp>现在，让我们一起学习一下手中的这个拆页，它将让我们在面对一个生气的对象时，如何不被他带着情绪走，能够接纳对象的情绪和冷静解决问题。\u003c/p>\u003cp>\u003cstrong>【I:拆书家讲解引导】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者互动：\u003c/strong>\u003c/p>\u003cp>拆页片段给了两个场景，对应两种不同的处理方法，你会选择哪个妈妈的应对方法呢？\u003c/p>\u003cp>预估的回答：我会选择汤姆妈妈的应对方法\u003c/p>\u003cp>那么，你觉得汤姆妈妈值得称赞的点是什么？\u003c/p>\u003cp>预估的回答：我觉得汤姆妈妈值得称赞的地方是能先看到和接纳孩子的情绪，再处理引起情绪的问题\u003c/p>\u003cp>面对情绪对象，你和他进行沟通时，你会先针对他的感受还是对其行为做出反应？\u003c/p>\u003cp>新增：预估的回答：先处理情绪再处理问题。\u003c/p>\u003cp>通过大家的回答，我觉得大家对拆页中两个场景的两种处理方法有了正确和准确的判断，很棒，为大家敏锐的观察力和共情力点赞！\u003c/p>\u003cp>【What】没错，面对情绪对象，先处理情绪再处理问题。原文片段用两个案例做对照，就很好地给我们展示了这种方法的效果，具体一点就是，通过“确认情绪、接受情绪、发掘问题、解决问题”这四步来帮助我们理解和接纳对象的情绪，并最终解决问题。\u003c/p>\u003cp>【Why】在我们的生活中，经常会碰到孩子、家人、朋友等生气的情况，如果我们被他们的情绪带偏，以怒制怒，或者马后炮，那么对情绪对象来说，这种处理方式只会火上浇油。如果能先处理好他们的情绪，积极寻找情绪的根源，并解决它，那么这样的沟通才具有建设性，才能更好地促进双方关系的融洽。\u003c/p>\u003cp>【how】回应生气孩子的四步骤具体如下：\u003c/p>\u003cp>\u003cstrong>第一步：确认情绪。\u003c/strong>观察孩子的情绪，看到他闷闷不乐或者哭鼻子，你冷静下来询问和确认孩子的感受，“你看上去好像很生气/伤心？”\u003c/p>\u003cp>\u003cstrong>第二步：接纳情绪\u003c/strong>。真诚地接纳他的感受，并给予理解。“怪不得你不高兴，要是我也会这样。”\u003c/p>\u003cp>\u003cstrong>第三步：发掘问题。\u003c/strong>问问题以寻找引起孩子情绪的原因，并得到确认。“你生气/伤心是因为妹妹抢了你的玩具？”\u003c/p>\u003cp>\u003cstrong>第四步：解决问题。\u003c/strong>引导孩子把注意力集中到解决问题上，找到解决当下的问题的方法。这个四步骤中，接纳情绪和发掘问题在不同情况可能会顺序调换。有时候可能是先发掘问题再接纳情绪哦。\u003c/p>\u003cp>\u003cstrong>失败案例：\u003c/strong>学校组织观影集体活动，8岁的小七看完电影后回到家，心情不佳，很生气的样子。我问他怎么回事，他说看电影的时候被前面两个高年级的大个子挡住了，那场电影是他期待已久的，观影体验非常不好，他觉得生气。我说，你不能请那个高个子跟你换一下座位吗？小七不耐烦地说，大家都想坐前面呢。那你应该早点去选一个好一点的位置的！小七听了更加烦躁了。\u003c/p>\u003cp>\u003cstrong>反例变正例：\u003c/strong>\u003c/p>\u003cp>运用回应生气孩子的四步骤，我会说：宝贝你看上去好像不开心。\u003cstrong>（确认情绪）\u003c/strong>\u003c/p>\u003cp>小七：我非常生气！有两个高个子坐在我前排，把荧屏都挡住了。\u003c/p>\u003cp>我：怪不得你不高兴，要是我也挺生气的。\u003cstrong>（接纳情绪）\u003c/strong>\u003c/p>\u003cp>小七：那可不嘛。\u003c/p>\u003cp>我：那观影体验恐怕就大打折扣了吧？这也是你这么生气的原因啰？\u003cstrong>（发掘问题）\u003c/strong>\u003c/p>\u003cp>小七：是的。我最喜欢看这种革命影片了。\u003c/p>\u003cp>我：那下次学校如果还组织大家观影的话，你可要去得早一点，占个好位子了。或者，有高个子在前面的时候，看能不能跟人家商量着换个位置啰？\u003cstrong>（解决问题）\u003c/strong>\u003c/p>\u003cp>小七：嗯，必须滴！\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>有伙伴说，看到孩子生气时只会骂骂咧咧或者哭哭啼啼，特别还是男孩子时，就很容易被他的情绪弄恼火，什么冷静和温柔，什么接纳情绪，完全就不存在了。那么，要想平息孩子的情绪，首先大人的情绪应该是平稳的、可控的，然后我们要能接住孩子情绪，带着孩子解决情绪的根源问题。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>应对情绪对象的四步法非常适用与有情绪的亲密关系如家人、朋友、同事的沟通，如果对方情绪比较激烈的话，还可以给对方一个充满爱意的抱抱或拍拍肩。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】：现场演练\u003c/strong>\u003c/p>\u003cp>那接下来我们针对学习的方法，我将给出一个场景，大家分组演练。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>晚上十点嘟爸到家不洗漱就上床躺着，嘟妈再三催促其洗漱，都不予回应。以为是应酬嗨了，正准备一番苦口婆心地说教，刚好嘟爸的同事打来电话，道出原委，原来嘟爸带领的小团队为单位的宣传日做了一份策划、准备好了物资，并跟单位内外的相关部门做了衔接，为此嘟爸还累倒了，休息了一天回去上班，谁知方案被另一小团队提出了诸多意见，并进行了大幅修改。一把手是个老好人，关键时候谁都不得罪，和稀泥。\u003c/p>\u003cp>【指令】接下来按我们开场的两两分组进行演练，一个扮演嘟爸，一个扮演嘟妈，给大家8分钟时间，讨论时请运用今天拆页分享的应对情绪对象的四步法来解决对象的情绪问题。最后我会邀请一组小伙伴来一个现场演练分享。\u003c/p>\u003cp>嘟妈(学习者扮演）：老公，你今天是不是不开心呀？平时看你是个喝酒有分寸的人啦，今天怎么喝多了点，还闷闷不乐哦？\u003cstrong>（确认情绪）\u003c/strong>\u003c/p>\u003cp>嘟爸(学习者扮演）：今天是有点不开心，有点累了。\u003c/p>\u003cp>嘟妈(学习者扮演）：是的，我看出来了。刚刚你同事打电话过来了。是这次宣传活动让你觉得闹心了吗？\u003cstrong>（发掘问题）\u003c/strong>\u003c/p>\u003cp>嘟爸(学习者扮演）：确实是的，我为这次活动做了很多准备工作，谁知我一天没去，方案就被推倒，换了。和我衔接的外单位的人知道了都觉得搞笑咧。\u003c/p>\u003cp>嘟妈(学习者扮演）：那是有蛮烦人的，临时换方案，让之前的努力都白费了，换成是我、我也生气。\u003cstrong>（接纳情绪）\u003c/strong>\u003c/p>\u003cp>嘟爸(学习者扮演）：嗯，要是早说，我还可以早点改，临时换方案、换团队，所以有点烦躁、郁闷。\u003c/p>\u003cp>嘟妈(学习者扮演）：那下次遇到这种情况，可要提前和老大沟通好，确定谁负责这个活动，然后和单位其他人员做个活动预报，收集反馈建议，把单位内部略顺和安排妥当了，再着手去和外单位衔接。\u003cstrong>（解决问题）\u003c/strong>\u003c/p>\u003cp>嘟爸(学习者扮演）：是的，确定谁负责，收集反馈，这样做出来的方案在执行的过程中就不会有太大的变化，也避免老大在面对这种矛盾对抗的时候打哈哈。\u003c/p>\u003cp>嘟妈(学习者扮演）：那这事就翻篇了，别不高兴了哈。\u003c/p>\u003cp>【A2】催化应用目标【布置作业】（特定任务）\u003c/p>\u003cp>本着我们拆书的价值观之一：拆为己用。下面来个课后作业来帮助大家更好的学以致用，需要大家在本次拆书结束后完成如下作业：\u003c/p>\u003cp>在未来2周里，大家会遇到情绪对象时，运用今天拆页中方法的四步骤来积极应对和解决对方的情绪问题。接下来的2周内请将你们的作业发送到我们会员群里。\u003c/p>\u003cp>学习者：我孩子两岁了，到了调皮捣蛋的年纪，我就看她皮，有时候自己的情绪就容易上来。就比如昨天晚上她要玩泡泡机，谁知那泡泡机坏了，她就特别生气，还冲着我说：“妈妈再给我买一个新的！”我当时也来了情绪，“泡泡机还不是你弄坏的！什么东西都不好好珍惜，只知道破坏。”现在反思之后，如果下次还遇到这样的情形或类似的状况，我会运用今天所学的四步骤，我会这样说：“芒果，你看上去好像很失落哦？你很喜欢玩这个泡泡机，可是现在它不能很好地运作起来了。你现在不开心是因为泡泡机不能使用了，是吗？喜欢的东西坏了不能玩了，换成我也是会伤心的。那我们一起来看一看，能不能修好它呢？是不是电池没电啦？是不是开关没开到位？还是哪里短路啦？如果实在都不行的话，那我们下次再去买一个啰？”\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>好了，我今天的拆书就到这里啦。希望今天的学习可以帮助大家。谢谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1640138305000,"updated_at":1640262439000,"ria":true},{"id":11814,"topic":"如何表达我们的愤怒20210411","learn_goal":"","remark":"过级活动","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"贺楚瑜","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>大家好！我是今天的拆书家楚瑜。三个标签介绍自己：企业网络安全规划高级主管、一级拆书家、儿童心理学在读研究生。\u003c/p>\u003cp>今天我们要聊的话题是“孩子，我们陪你快乐成长”，\u003cstrong>“表达’我的\u003cem>愤怒边界\u003c/em>‘ 方法最重要”\u003c/strong>。\u003c/p>\u003cp>首先我们进行【分组】。\u003c/p>\u003cp>活动前了解到，各位均已是孩子的父母，稍后的讨论我们就按照就近原则，每两人一组，共3组的方式进行讨论。\u003c/p>","ratings_count":1,"texts":[{"id":15758,"quote":"\u003cp>学习目标：\u003c/p>\u003cp> 在跟随我完成本次RIA现场学习后，学习者能够在孩子出现不端行为的时候，通过四个步骤释放愤怒情绪，表达愤怒边界，有效遏制住“愤怒”情绪的破坏力。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>今天我带领大家拆的书名是《孩子，把你的手给我》，作者：【美】海姆.G.吉诺特\u003c/p>\u003cp>\u003cstrong>F（特征）\u003c/strong>: 吉诺特博士的这本著作——在亲子沟通这个领域，是一本革命性的著作，作者在书中倡导的沟通技巧帮助成年人以共情和关爱的方式进入孩子的世界，教给成年人，如何了解孩子的感受，并对其作出反应。一句话来讲，这本书教你如何与孩子实现真正有效沟通的方法。\u003c/p>\u003cp>\u003cstrong>A（优势）\u003c/strong>：\u003c/p>\u003cp>本书在长达一年多的时间里高居美国各大图书排行榜榜首，并陆续被翻译成31种语言畅销很多国家。自2004年被翻译成中文后，持续在国内各大书店摆放在亲子领域的明星位置。\u003c/p>\u003cp>\u003cstrong>B（利益）:\u003c/strong>\u003c/p>\u003cp>B1：如果你还在纠结孩子给自己带来的苦恼，这本书教你如何引导孩子不再那么“熊”；如果你家孩子经常让你情绪激动，来看这本书，它教你如何与孩子沟通；\u003c/p>\u003cp>B2：孩子会急躁，会发怒，会纠缠，会挑战，如果作为父母，我们不知道如何来应对，不知道怎样和孩子沟通忍耐的限度，今天的片段会给你不一样的启发......\u003c/p>\u003cp>\u003cstrong>R原文片段：\u003c/strong> 发怒的三个步骤 在平静时期，让自己做好应付紧张时刻的准备，应该承认下面的事实： 1、我们接受这个事实，在跟孩子打交道的时候，我们有时会发脾气。 2、我们有权生气，而不必感到内疚或者羞愧。 3、除了安全考虑，我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格，我们就可以表达我们的愤怒。 这些假设应该列入处理愤怒的具体步骤中去。处理激动情绪的第一步是给他们明确的定义，这可以提醒相关人改正或者采访预防措施。这样做的第一步是使用人称代词“我”：“我觉得讨厌。”“我觉得被激怒了。” 如果简短的陈述和拉长着脸，并没有产生效果，那么采取第二个步骤。在表达时加强愤怒的强度： “我生气了。” “我很生气。” “我非常非常生气。” “我气急了。” 有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>\u003cp> “当我看到鞋子，袜子，衬衫，运动衫扔得满地都是时，我很生气，生气急了。我真想打开窗户，把这一摊乱七八糟的东西扔到大街上去” “看到你打你的弟弟，我很生气，心里面像有团火在烧，我绝不允许你再伤害他。” “看到你们所有的人一吃完晚饭就冲出去看电视，把那些脏兮兮的盘子，油腻腻的锅留给我时，我非常愤慨！气得我简直七窍冒烟！我真想把所有的盘子砸到电视上去！” “我叫你吃晚饭，而你却不来，我很生气，非常生气，我对自己说：‘我煮了一餐好吃的，希望获得赞赏和感激，而不是失望！&#x27;&quot;。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>当孩子令我们愤怒的时候，我们有权生气，只要我们不攻击孩子的人品或者性格，我们就可以安全的释放我们的愤怒。并且向孩子明确愤怒的边界。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>生活中，当孩子与我们纠缠要得到一件东西的时候，我们是给她讲道理吗？当家里的幼儿宝宝把你心爱的口红涂满沙发的时候，我们是拎起来打一顿吗？\u003c/p>\u003cp>如果我们不管不顾，或者就依着自己当下的情绪，抽耳光、批评、说教，后果会怎样呢？ 短期看得见的就是孩子开始躲你，严重的情况孩子的行为表现出现两张皮，你在的时候一个样子，你不在的时候另一个样子。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>今天这个片段讲的是“智慧的发怒”：安全释放怒气，明确忍耐边界。\u003c/p>\u003cp>1、接纳。\u003c/p>\u003cp>自我接纳：接纳我们和孩子一起相处，有生气的权力，有不伤害孩子人品和性格，安全释放愤怒的能力。\u003c/p>\u003cp>接纳对方是我们的孩子，不是敌人。即使现在他令我生气，对方仍然是我们的孩子，我们是爱他的，我们需要遏制愤怒情绪的破坏力。\u003c/p>\u003cp>2、表达。\u003c/p>\u003cp>目的是给孩子预警。参考句式：我生气了。\u003c/p>\u003cp>3、强化表达。\u003c/p>\u003cp>目的是二次加强预警，就如台风来了，我们橙色预警到红色预警。参考句式：（增加副词或形容词的方式。）我很生气，我气得双腿发抖。\u003c/p>\u003cp>4、明确界限。\u003c/p>\u003cp>解释我们生气的原因，说出我们的想法，以及我们期望的行为。引导孩子从愤怒或对抗向期望的行为方向思考和行动。\u003c/p>\u003cp>\u003cstrong>【案例】正面做法：\u003c/strong>\u003c/p>\u003cp>2006年夏天，我带女儿在北京旅游，在高铁上孩子提出要买一个冰淇淋。我当时考虑孩子在上车前吃过一个，不到两小时又吃，不妥当！所以我就直接拒绝了孩子的需要。结果孩子在月台上各种跟我撒泼，耍赖，弄得我尴尬不说，火气也很大。 当时因为没经验，娘俩互相受伤，类似问题在接下来一周内还持续发生几次。\u003c/p>\u003cp>加工成正面做法：\u003c/p>\u003cp>第一步：接纳。接纳自己有权利生气，不必羞愧，也相信自己有能力安全的释放情绪；接纳孩子，即使孩子让我们愤怒，我们依然爱她。\u003c/p>\u003cp>第二步：告诉孩子。当下的行为妈妈生气。\u003c/p>\u003cp>第三步：当孩子依然没有收敛时，认真的再次告诉孩子，妈妈很生气。\u003c/p>\u003cp>第四步：察觉到孩子稍微平复一些后，跟孩子说出原因：“当我听到宝贝今天第二次要吃冰淇淋，妈妈生气，因为我们约定过一天不超过1条冰淇淋。”妈妈期望，我们一起做个遵守约定的孩子。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>这个方法适合于亲子关系和个人情绪管理良好的家庭。适合无他人在场和孩子一对一的沟通。\u003c/p>\u003cp>如果是亲子关系本身就一地鸡毛，或者说个人容易情绪化。再运用这个方法，可能就会转变成“燃烧愤怒”，最终两败俱伤的结果。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>听到这，大家是不是会觉得这个方法有点麻烦，小题大做？能用棍棒直接解决的问题何必要大费周章？其实，这不仅仅是给孩子表达愤怒的边界。更是我们自己逐步逐步释放愤怒的过程，俗称降火的过程。同时也是向孩子言传身教如何正确的释放愤怒情绪的过程。\u003c/p>\u003cp>如果我们当下火气大得实在是控制不住自己的言行，此刻不如先撤离现场。\u003c/p>\u003cp>有人讲，假如我按照4个步骤都做了，孩子依然纠缠，那怎么办呢？\u003c/p>\u003cp>可以尝试确保孩子人身安全的情况下，暂不和孩子说话，让他感受到你和善而坚定的坚持便可。\u003c/p>\u003cp>有人还会讲，听起来很简单，我要怎么做呢？\u003c/p>\u003cp>知道与做到中间有一条不断践行的道路，刻意练习可以帮助我们运用起来越来越娴熟。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：下面我们来想象一下，某一天你发现，孩子一次性把半年的零花钱花掉了、孩子晚归、或者是孩子把钱送进了网吧、送到了其它娱乐场所。请在脑海中勾勒一下\u003cstrong>今后\u003c/strong>可能遇到的一个场景。那一刻你怒火烧心。那一刻，你好想冲上去给他巴掌。\u003c/p>\u003cp>请大家花1-2分钟想像下，稍后我们找一位小伙伴进行分享。\u003c/p>\u003cp>【学习者张华案例分享】\u003c/p>\u003cp>表妹家初一的孩子，因为迷恋电子设备，经常待大人们睡着后窝在被窝里玩手机。为此家长很苦恼，经常因为这个事件家里大动干戈。作为孩子的姨妈，对此我也生气。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：那接下来，请大家结合今天的拆书，思考下，\u003cstrong>今后\u003c/strong>在这样愤怒的场景里面我们该如何应用今天所拆的方法进行处理呢。请大家进行讨论，也可以在便签纸上写下今后你的行动计划，最好是有步骤的、可操作的、具体的计划。（3分钟后，我们邀请一位伙伴来分享）\u003c/p>\u003cp>【学习者张华案例记录】\u003c/p>\u003cp>学完今天的片段后，我计划和侄女好好谈下。\u003c/p>\u003cp>第一步：接纳孩子在成长过程定会有不同的烦恼，接纳孩子对抗电子设备的诱惑是很难。\u003c/p>\u003cp>第二步：准确的向孩子表达，因为电子设备使用的不受限以及影响休息，这令大人们生气。\u003c/p>\u003cp>第三步：尤其是偷偷的自购手机，在睡觉后使用，令大人们很生气。\u003c/p>\u003cp>第四步：生气的原因一是担心无节制的使用电子设备形成坏习惯，二是担心伤害我们的眼睛；我们期望使用电子设备我们共同约定个使用场景、每日使用次数和使用时间。\u003c/p>\u003cp>谢谢分享，时间过得很快，即使我们讨论得意犹未尽，鉴于时间的限制。回头咱再群里聊。\u003c/p>\u003cp>【小结】:\u003c/p>\u003cp>陪伴孩子快乐成长，是我们每个家长的心愿。智慧的表达愤怒叫“我的忍耐是有限度的。”\u003c/p>\u003cp>四个步骤：一接纳；二表达；三强化表达；四明确界限。\u003c/p>\u003cp>今天的拆书到这里，谢谢大家参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1624777457000,"updated_at":1624858779000,"ria":true},{"id":11316,"topic":"发怒的三个步骤","learn_goal":"","remark":"《孩子，把你的手给我》","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"余铄灵","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>环节\u003c/strong>\u003c/p>\u003cp>\u003cstrong>预计时间\u003c/strong>\u003c/p>\u003cp>\u003cstrong>准备内容\u003c/strong>\u003c/p>\u003cp>自我介绍\u003c/p>\u003cp>1分钟\u003c/p>\u003cp> 大家好，我是余铄灵，非常开心和大家相遇在拆书活动中。今天在场的很多伙伴我们都已经认识了，但我还是简单的做个自我介绍。我毕业于西南政法大学法律专业，在文化行业有10多年的运营管理的从业经验，现在是一名专业的保险代理人。现在的最高荣誉是“好”妈妈。目前我是拆书帮1-1的拆书新人，很荣幸的被我们贵阳第二筹备分舵的舵主阿杜任命为了组织长老，希望可以和大家一起升级打怪，尽快的将我们贵阳分舵筹建起来。我也会尽我的努力来为大家服务。那下面是我可以为大家提供的服务：\u003cbr> \u003cstrong>1、 组织我们的拆书活动。\u003c/strong>在14年第一次购买了赵周老师的《这样读书就够了》，第一次知道拆书这个方法。但是自己琢磨并没有完全掌握要领。20年结识了阿杜，并找到了拆书帮组织，完成了线上30拆，这才算是初入门禁。现在和阿杜、灵灵还有其他的小伙伴们一起，希望能尽快筹建起我们的贵阳分舵。我觉得大家一起学习能带来更好的效果，今后将多为大家组织线下的拆书活动。\u003cbr> \u003cstrong>2、 法律、保险方面的专业知识的咨询。\u003c/strong>这两个板块是我职业标签。如果有伙伴有这两个板块的需求，我都可以为你们提供相关的服务，为你们尽可能的去避免“踩坑”。\u003cbr> \u003cstrong>3、 培训讲师。\u003c/strong>目前我是樊登读书旗下的认证翻转师。会经常给会员们提供沙龙分享和培训。如果您或您的企业需要相关的服务，我也可以给到您一些建议和意见。\u003c/p>\u003cp>拆书帮介绍\u003c/p>\u003cp>2分钟\u003c/p>\u003cp>\u003cstrong>下面给大家简单的介绍一下“拆书帮”和“拆书法”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先我先介绍下“拆书帮”\u003c/strong>\u003cbr> \u003cstrong>“拆书帮”\u003c/strong>是一个公益非营利行的青年自组织社区。是基于帮主赵周在《这样读书就够了》一书中创立的RIA拆书法的学习爱好者社群，致力于促进不断练习运用，讲书中的知识转为己用，同时影响身边更多的人，其使命是“释放学习促进者的能量”，帮助更多爱好者成长为拆书家。他的表现形式为在各地都有“拆书帮分舵”（也叫拆书帮俱乐部）。\u003c/p>\u003cp>那听了拆书帮，可能心里还有一个疑问，那什么是“拆书”呢？下面我就来介绍下拆书和拆书法。\u003c/p>\u003cp>\u003cbr> \u003cstrong>“拆书”\u003c/strong>是一种成人学习的方法论，强调以学习者为中心而不是以知识为中心，适合以提升能力解决问题为目标的成人学习。他分为个人学习的拆书法和组织学习的拆书法。\u003cbr> \u003cstrong>个人学习拆书法：\u003c/strong>就是便签法。即RIA便签法。R是指阅读原文，I是指对原文的诠释，也就是我们可以结合原文片段写出自己对片段的理解，总结出方法技能点。A是指结合我们的过往经验进行反思并可以为未来的工作和生活设定目标和行动步骤。\u003cbr> \u003cstrong>组织学习拆书法：\u003c/strong>是指在一位拆书家的带领下，在线下进行拆解，引导学员把知识转化为技能。如果从学习效果来衡量，拆书可以将读一本就能达到参加同一主题培训的效果，而一位拆书家所创造的价值不亚于一位培训师。\u003c/p>","ratings_count":1,"texts":[{"id":15241,"quote":"\u003cp>我们今天的拆书主题是“发怒的三个步骤”，所选的拆页选自《孩子把手给我》，下面我们有两分钟的阅读片断时间，各位伙伴阅读完了以后，请举手给我一个反馈。\u003c/p>\u003cp>\u003cstrong>【主题】发怒的三个步骤\u003c/strong> \u003cbr> \u003cstrong>【片段来源】孩子把你的手给我\u003c/strong> \u003cbr> \u003cstrong>【R：阅读原文】\u003c/strong> 在平静时期,让自己做好应付紧张时刻的准备,应该承认下面的事实: 1.我们接受这个事实:在跟孩子打交道的时候,我们有时会发脾气。 2.我们有权生气,而不必感到内疚或者羞愧。 3.除了安全考虑,我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格,我们就可以达我们的愤怒。 这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”:“我觉得讨厌”“我觉得被激怒了”。 如果简短的陈述和拉长着的脸并没有产生效果,那么采取第二个步骤。在表达时加强愤怒的强度： “我生气了。” “我很生气。” “我非常非棠生气。 “我气极了。” 有时,仅仅表达出我们的感受(不用解释原因)就能让孩子停止不端行为。但是,有时候,可能需要采取第三个步骤解释我们生气的原因说出我们内心的想法,以及我们希望的行为。 “当我看到鞋子、袜子、衬衫、运动衫扔淂满地都是时 我浪生气,生气极了。我真想打开窗户,把这一摊乱七八糟的东西扔到大街上去。” “看到你打你的弟弟,我很生气,心里面像有团火在烧， 我决不允许你再伤害他。” “看到你们所有的人一吃完晩饭就冲出去看电视,把那些脏兮兮的盘子、油腻膩的锅留给我时,我非常愦慨!气淂我简直七窍冒烟!我真想把所有的盘予砸到电视上去!” “我叫你吃晚饭,而你却不来,我很生气,非常生气,我对自己说:‘我煮了一餐好吃的,希望荻得赞赏和感激,而不是失望!’” 这个方法可以帮助父母释放怒气,而不致引起伤害,而且,它甚至可以是一堂重要的课,教会孩子如何安全地表达愤怒。孩子可能会明白他自己的愤怒也不是什么大的灾难,可以释放出来,而不会伤害任何人。这堂课不仅仅需要父母把怒火发泄出来,还需要父母向孩子指出情感表达的可接受的方式,要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>","explains":"\u003cp>\u003cstrong> I便签\u003c/strong>\u003cbr> \u003cstrong>【What—原文讲了什么】\u003c/strong>\u003cbr> 原文片段告诉我们如何将情绪安全的表达出来，不让事情因为情绪向不好的方面发展。\u003cbr> \u003cstrong>【Why— 为什么作者要总结这些方法】\u003c/strong>\u003cbr> 情绪是每个人都有的，高兴也好，愤怒也好，我们都需要表达出来。愤怒是一种比较激烈的情绪，很容易让我们控制不了自己，所以我们可以通过自己的反思和暗示，来刻意训练自己如何来向孩子表达愤怒。即要解决问题，也不会伤害到自己和孩子。而这些训练就是处理愤怒的具体步骤。\u003cbr> \u003cstrong>【How—怎么做？】\u003c/strong>\u003cbr> 如何安全的来处理愤怒？可以分为以下3步，这三步骤可以是递进关系，也可以是单个独立的关系；可以三个方法都用，也可以只用其中一个，只要能解决就好。\u003cbr>\u003cstrong> 1、 确定。\u003c/strong>首先先确定我们的情绪，并且明确的表达出来。比如：这件事，我不开心。\u003cbr>\u003cstrong> 2、 程度。\u003c/strong>如果对方（孩子或其他人）任然没有感受到我的愤怒，那就可以加强表述愤怒的程度。“这件事让我很不开心。”“我非常生气！”\u003cbr>\u003cstrong> 3、 表达。\u003c/strong>这里的表达其实是为了让对方更好的和我们产生共情。那怎么做才能更好的让对方感受到我们的情感呢？让他理解我们。让他清楚的知道我们当下为什么会有这样的情绪。特别是负面的情绪。当对方知道我们的原因后更容易理解我们，更容易产生共情。\u003cbr> 以上这三步说起来容易做起来难，因为当人愤怒的时候其实是容易做出过激行为的，所以需要提前给自己打预防针，提前做好心理建设。在对孩子上就尤为重要，因为孩子就是你的镜子，我们需要做好示范，如何正确的表达情绪。\u003cbr> \u003cstrong>【Where—可以运用到什么场景】\u003c/strong>\u003cbr> 这个方法除了可以运用在表达愤怒方面，还可以用在任何沟通的过程当中。表达出自己当下的情绪状态，有助于更好，更高效的沟通。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1—过去的具体经历（故事、反思）】\u003c/strong>\u003cbr> \u003cstrong>【故事】\u003c/strong>\u003cbr> 2月23日，儿子用我的账号给游戏进行了高额充值。他并不知道这些充值到游戏里的钱意味着什么，价值几何。而当我知道的时候我非常的愤怒，非常的愤怒。庆幸事情发生的当下，我们没有在一起，我有足够的时间来冷静和思考。当天，我就运用到了文中说提到方法来和孩子进行沟通。\u003cbr> 我从外面匆匆赶回家后，就先给孩子表达了我的情绪。\u003cbr> “这件事情我很生气，你的这个行为让我很愤怒，也让我很难过。”\u003c/p>\u003cp>向他提问，\u003cbr> “你知道你支付出去的钱是多少吗？”\u003cbr> “你知道你的这个行为意味着什么吗？”\u003c/p>\u003cp>告知他我生气的原因\u003c/p>\u003cp>“妈妈之所以这么生气是因为两点：一是…………；二是…………”\u003c/p>\u003cp>用陈述和提问的方式，来表达了自己的情绪和为什么有这种情绪，并弄明白了他的做这件事的原因。\u003c/p>\u003cp>这次的事件让我和儿子都学会了“吃一堑长一智”也是很好的一次情绪表达的实践课。和孩子正好运用到了文中提到的方法进行了很好的沟通，也弄明白了他为什么会这么做的原因，找到了解决问题的办法并且反思了作为父母在这件事情中应该承担的责任。\u003c/p>\u003cp>\u003cstrong>【反思】\u003c/strong>\u003c/p>\u003cp>愤怒只是一种情绪，它并不能帮我们解决问题，怎么处理好愤怒的情绪，让自己回归平静后去处理事情才是最重要的。\u003c/p>\u003cp>\u003cstrong>【A2—未来的行动规划（目标、行动）】\u003c/strong>\u003cbr> \u003cstrong>【目标】\u003c/strong>\u003cbr> 在本月30日前,当孩子触发到我的负面情绪时，我会运用片断中的“消除负面情绪三步法“表达我的感受，并能让孩子与我合作\u003c/p>\u003cp>\u003cstrong>【行动】\u003c/strong>\u003cbr> 当孩子触发我“负面情绪”的神经时：\u003cbr> 第一步，我要确定并明确地表达出我的情绪。“你的这个行为让我觉得不舒服，不开心”。\u003cbr> 第二步，加重语气。\u003cbr> 第三步，我觉得也是最重要的一步，告诉他我为什么生气。为什么不开心。\u003cbr> 这三步中，我觉得可以组合使用，比如1+3或者2+3。视事情的轻重来定。但是我觉得最重要的是一定要有第三步。\u003c/p>\u003cp>谢谢大家的聆听，虽然读书时间很个人的事，但是我觉得独行未必快，众行才会远，齐行必定强。所以我将会做好我组织长老的职责，很多更好的组织大家，持续的升级打怪，希望我们一起突破自己，通过拆书成就更好的自己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1618125949000,"updated_at":1618128620000,"ria":true},{"id":10880,"topic":"学会应对发怒","learn_goal":"","remark":"学习目标：\n   再教育孩子的过程中，经常遇到“放学回家母慈子孝，一写作业鸡飞狗跳”情景，这种情况下就需要我们学会应对我们的怒气。\n内容简要:\n在生活中我们常会感到无法控制自己的愤怒，面对愤怒我们应该如何选择？是任其发展还是控制它又或者是面对它？\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"上官兰幽","city":"哈尔滨市"},"club":{"name":"哈尔滨索菲亚分舵","city":"哈尔滨"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp> 我在拆书帮的昵称是\u003cstrong>上官兰幽，用三个标签介绍一下我自己，我的第一个标签“特”、第二个标签思维导图学习者、最后一个标签写作爱好者\u003c/strong>。这个名字来源非常草率对我来说却十分有意义，我希望现实生活中的我成为虚拟世界“社交达人”的我。“特”是亲朋好友赋予的性格特点，也体现在思维方式上的不同。在学习实践过程中思维导图改变了我的思维方式，同时也帮助我整合我的知识、经验以及见解。我在大学期间经历过一次毁灭性打击，在今年年初走出来之后发现写作是我生命不可割舍的一部分。\u003c/p>\u003cp>\u003cstrong>介绍拆书帮：\u003c/strong>\u003c/p>\u003cp>大家可以看到在拆书帮log背景图后有一扇窗户，这扇窗代表拆书帮，这扇窗让我们站在窗前就能闻到花香、见到不同世界。\u003c/p>\u003cp>说到拆书帮就必须先说一下什么是拆书，\u003cstrong>拆书是一种帮助我们提升能力、解决问题的方法，这一方法强调以学习者为中心，而非以知识为中心，意在帮助学习者将知识内化为己用。拆书按照学习方法分为个人学习：用RIA便签法学习一本书就可以达到参加一次培训的效果；组织学习：引导一群把知识拆为己用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书帮是拆书爱好者的社群，具体表现形式就是各地拆书帮分舵，各分舵都是非营利性组织，其使命是帮助拆书爱好者成长为拆书家。\u003c/strong>\u003c/p>\u003cp>在我年初刚接触到拆书的时候就了解了一个理念，把别人的变成自己的，而拆书帮能帮助我们做到这一点，这是我心中拆书帮的最大价值。\u003c/p>\u003cp>我2021年的目标是成为三级拆书家，在成为三级拆书家后我会向着成为更好的拆书专家与更好的主题专家去努力。\u003c/p>\u003cp>接下来请大家用3分钟阅读手中材料第2到3页。\u003c/p>","ratings_count":2,"texts":[{"id":14775,"quote":"\u003cp>《孩子把你的手给我》p43—p 44\u003c/p>\u003cp>\u003cstrong>发怒的三个步骤\u003c/strong>\u003c/p>\u003cp>在平静时期,让自己做好应付紧张时刻的准备,应该承认下面的事实:\u003c/p>\u003cp>1.我们接受这个事实:在跟孩子打交道的时候,我们有时会发脾气。\u003c/p>\u003cp>2.我们有权生气,而不必感到内疚或者羞愧。\u003c/p>\u003cp>3.除了安全考虑,我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格,我们就可以达我们的愤怒。\u003c/p>\u003cp>这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”:“我觉得讨厌”“我觉得被激怒了”。\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有产生效果,那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>“我生气了。”\u003c/p>\u003cp>“我很生气。”\u003c/p>\u003cp>“我非常非棠生气。\u003c/p>\u003cp>“我气极了。”\u003c/p>\u003cp>有时,仅仅表达出我们的感受(不用解释原因)就能让孩\u003c/p>\u003cp>子停止不端行为。但是,有时候,可能需要采取第三个步骤解释我们生气的原因,说出我们内心的想法,以及我们希望的行为。\u003c/p>\u003cp>“当我看到鞋子、袜子、衬衫、运动衫扔淂满地都是时\u003c/p>\u003cp>我浪生气,生气极了。我真想打开窗户,把这一摊乱七八糟的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟,我很生气,心里面像有团火在烧，\u003c/p>\u003cp>我决不允许你再伤害他。”\u003c/p>\u003cp>“看到你们所有的人一吃完晩饭就冲出去看电视,把那些\u003c/p>\u003cp>脏兮兮的盘子、油腻膩的锅留给我时,我非常愦慨!气淂我简直七窍冒烟!我真想把所有的盘予砸到电视上去!”\u003c/p>\u003cp>“我叫你吃晚饭,而你却不来,我很生气,非常生气,我对自己说:‘我煮了一餐好吃的,希望荻得赞赏和感激,而不\u003c/p>\u003cp>是失望!’”\u003c/p>\u003cp>这个方法可以帮助父母释放怒气,而不致引起伤害,而且,它甚至可以是一堂重要的课,教会孩子如何安全地表达愤怒。孩子可能会明白他自己的愤怒也不是什么大的灾难,可以释放出来,而不会伤害任何人。这堂课不仅仅需要父母把怒火发泄出来,还需要父母向孩子指出情感表达的可接受的方式,要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>","explains":"\u003cp>已经有看完的小伙伴，还有没看完的小伙伴先停一下，跟着我接下来的讲述也可帮助大家理解原文。\u003c/p>\u003cp>大家阅读这一片段来自于我手中这本《孩子把你的手给我》，这本书以更多的案例向读者讲述如何与孩子沟通以及控制自己的情绪。\u003c/p>\u003cp>\u003cstrong>why\u003c/strong>\u003c/p>\u003cp>许多时候我们会感受到怒气无法控制，导致我们被愤怒牵着鼻子走，做出伤害家人、朋友的事情。所以生活中我们需要释放愤怒，并且在这个过程中我们也能够教会孩子应对愤怒。\u003c/p>\u003cp>\u003cstrong>what\u003c/strong>\u003c/p>\u003cp>今天讲的拆页是“学会应对愤怒，具体做法如下：\u003c/p>\u003cp>\u003cstrong>how\u003c/strong>\u003c/p>\u003cp>1、\u003cstrong>接受发怒的事实\u003c/strong>，我不需要为表达怒气而感到内疚，只要我不攻击他人身体与心灵。\u003c/p>\u003cp>2、\u003cstrong>表达愤怒程度。\u003c/strong>通过拉长脸以及语言让对方感受到我有多生气。\u003c/p>\u003cp>3、\u003cstrong>找到我发怒的具体原因并说出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>\u003c/p>\u003cp>这一方法可以用在任何你被他人激怒时的沟通。但不适用个人情绪不好时被激怒，在我们自身情绪不良的情况下，情绪会牵着我们鼻子走，我们没办法控制它，比如前一天没休息好或者这一天就是莫名其妙的心情不好等情况下被激怒就不适合使用这一方法。\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>下面大家跟着我的案例一起看一下不按上面的步骤做会带来怎样的后果。\u003c/p>\u003cp>女儿已经三岁了，上了幼儿园以后独立思考能力变得更强了，经常玩着玩着就会坐地下不起来，10月天气逐渐转凉，一天接女儿放学回家，女儿坐在地上不起来了，我急切的想让女儿起来，女儿就是不起，在一来一回的拉扯中，我和女儿的情绪都崩溃了，我气急败坏的凶女儿，女儿坐地上哇哇哭。\u003c/p>\u003cp>通过这个案例可以看到不按方法做对自己以及孩子或者他人都是伤害。我可以按照今天学习的方法去调整心态，以较平和且拉长脸对女儿说：“地上很凉，这样坐在地上会受凉的。”女儿依然坐在地上无动于衷，接着我加深表情的凝重度以及语气对女儿说：“我现在很生气，地上很凉，你不起来会受凉的。”女儿岿然不动的坐在那里，我再一次加强语气对女儿说：“我现在非常生气，你这样坐在地上会受凉的。”女儿终于慢慢悠悠地站起来了。\u003c/p>\u003cp>我们以安全的方式表达自己的情绪时孩子是能够明白的，许多时候孩子的能力会超出我的的想象。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>经验:\u003c/strong>\u003c/p>\u003cp>我自己本身是比较随和的人，极少出现发怒的情况。在女儿出生到2岁的这两年期间，由于患上产后抑郁症情绪非常不稳定，有两次比较严重的发怒，事件起因已经小到记不清楚了但后果却很严重。\u003c/p>\u003cp>第一次发怒我把结婚证撕了，现在依然清晰的记得当时的情景，撕了结婚证拿着行李箱装上女儿的奶粉衣服就要走，妈妈怎么拦都拦不住，老公自己跑小屋关上门谁都不理，当时女儿还没满月。 \u003c/p>\u003cp>第二次发怒我直接把手机摔了，那时女儿一岁多正处在模仿的初期，很长一段时间女儿受我这一行为的影响特别喜欢摔东西尤其手机。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>在这两次的发怒前我没有在平静期调整心态，直接导致因为一件不值一提的小事就被激怒的后果。后两步更是没有做，导致了一个更糟糕的结果，这一结果足以让我们看到发怒不能给我们带来任何益处，只能给家人带来更多的压力以及负面影响。\u003c/p>\u003cp>最重要的是，我们要意识到第一步的重要性，从我的这个经验中可以看到，不去做第一步，在平静期接受发怒的事实，第二步与第三步就没有办法做到，所以我们要把第一步做好，再去做后面的两步。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标:\u003c/strong>\u003c/p>\u003cp>为了实现减少发怒次数的目标，在一周内做到发怒次数少于5次。\u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>\u003c/p>\u003cp>在情绪稳定时通过不断告诉自己“我有权表达怒气，我不需要为此而内疚；在不对他人身体与心灵造成伤害的前提下，可以表达我的愤怒。”将这一观点记下来，并在发怒时不断提醒自己，以达到思考与行动起同步的目的。\u003c/p>\u003cp>在刚开始的时候我们可能做不到三步都能知行合一，我们可以先做好第一步，在做第一步的同时练习表达愤怒的情绪，可以对着镜子做不同表情，找到自己表达愤怒的表情并不断练习，形成肌肉记忆，方便我们更好的做到第二步。\u003c/p>\u003cp>第二步与第一步相似，我们要做的事情是在每次发怒时提醒自己用，很、非常等词语表达愤怒程度。\u003c/p>\u003cp>当我们把第一步与第二部步做好以后按照前两步的方法练习做第三步，说明愤怒原因。\u003c/p>\u003cp>最后为了让自己做到自律，我设计了一张自律表在4页，大家在行动过程可以按照自律表来做。\u003c/p>\u003cp>大家可以看第5页的思维导图，这张导图就是我们今天学习的主要内容，大家前面不用导回去只带思维导图就可以，按照思维导图回忆今天的学习内容。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1609210590000,"updated_at":1610796529000,"ria":true},{"id":10724,"topic":"青铜树沟通法","learn_goal":"","remark":"本书是美国著名的心理学博士、儿童心理学家海姆·吉诺特所著，传授与青少年孩子实现真正有效沟通及和谐相处的方法。","level":"TF2-2","duration":18,"status":30,"type":0,"chaishujia":{"username":"王文婷Jessica","city":"深圳市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>在跟随我完成本次RIA现场学习后，学习者将能够了解以及运用一套与青少年孩子沟通的青铜树三部曲，在孩子被某件事情困扰而产生情绪的时候，帮助孩子舒缓情绪，增进相互理解并促进亲子关系。\u003c/p>\u003cp>尊敬的观察家、各位亲爱的小伙伴，晚上好！ \u003c/p>\u003cp>我是今天晋级2-2的王文婷。 用3个标签介绍自己，分别是“蒙特梭利主教”蒙特梭利主班老师、“妈妈”和“吃货”。\u003c/p>\u003cp>现在我把大家分成两个组——这边的朋友是一组，那边的朋友是一组。 每组里面头发最长的那位伙伴担任组长，待会儿来组织一下分享。\u003c/p>\u003cp> 今天给大家带来的拆页来自（F）《孩子，把你的手给我II》，本书是美国著名的心理学博士、儿童心理学家海姆·吉诺特所著，传授与青少年孩子实现真正有效沟通及和谐相处的方法。 （A）相比其他同类书籍，这本书一出版就登上《纽约时报》畅销书排行榜，并在榜单上停留了25周之久，并且被翻译成31种语言引入全球各地。 在国内，这本书的豆瓣评分高达8.8分，被奉为“教子经典”。(B1)众所周知，十几岁的青少年孩子具有不同于低龄儿童的特质，给父母们带来许多挑战和困扰。这本书就教给父母们很多实用的知识和技巧，帮助父母与青少年孩子相互尊重、和谐共处。（B2）今天的拆页将聚焦于当孩子被某件事情所困扰而产生情绪的时候，如何同孩子沟通，以帮助孩子纾解情绪、增进相互理解并促进亲子关系。\u003c/p>","ratings_count":2,"texts":[{"id":14597,"quote":"\u003cp>这次要拆的原文片段来自于这本书的第3章，“首要原则是不伤害孩子”。 现在，请大家用2分钟的时间阅读下手中的拆页，阅读完后请举手示意我。\u003c/p>\u003cp>向十几岁的孩子表明沟通和交谈的富有成效的方法，是父母的责任。比如:\u003c/p>\u003cp>专注地倾听\u003c/p>\u003cp>复述对方的要点\u003c/p>\u003cp>不要批评和骂人\u003c/p>\u003cp>陈述自己的观点\u003c/p>\u003cp>当我们更注意地听并以一种同情的语调做出回应时，就能得十几岁孩子的注意。当我们将孩子说的不清楚的事情清晰地表达出来时，就能赢得孩子的心。当我们真诚，当我们使用的言词适合自己情感的时候，就能得孩子的尊重。下面几个故事，说明了父母怎样来使用承认孩子感受的方法。\u003c/p>\u003cp>十五岁的科拉正在抱怨，因为她的妹妹溜冰去了，弟弟打保龄球去。\u003c/p>\u003cp>科拉:他们总是有事可干一去溜冰、打保龄球。我在他们这么大的时候，什么事都不让我干。你们从来不带我去溜冰。\u003c/p>\u003cp>母亲:哦，亲爱的，你知道那个时候你的医生不允许你去溜冰。\u003c/p>\u003cp>父亲:你忘了你那时病了。再说，我们在一起干过很多事情。\u003c/p>\u003cp>科拉:我不记得干过什么事情。你们没有带我去过任何地方。\u003c/p>\u003cp>母亲和父亲(异口同声地反驳):但是，科拉，我们确实带你出去过。你不记得带你去马戏团了?不记得带你去加拿大旅游了？\u003c/p>\u003cp>这时，母亲改变了方法。\u003c/p>\u003cp>她立即理解了科拉的感受，并跟丈夫说:“科拉觉得自己被剥夺了玩的机会!她真的觉得自己被忽略了!”“没错，我就是这种感觉。”科拉大声地肯定道。\u003c/p>\u003cp>母亲:原因并不重要。如果你是这种感受，那事情对你来说就是这样。\u003c/p>\u003cp>科拉(平静地):没错!\u003c/p>\u003cp>这个问题引起的紧张消除了，争论停止了。这位母亲说这件事让我明白了，推理和逻辑无法让一个处于一定情感状况的十几岁孩子的需要得到满足。还让我知道了，可以在处理孩子情绪的过程中改变方法。\u003c/p>","explains":"\u003cp>\u003cbr>【Why】孩子与我们成年人一样，也会因为某些事件产生情绪困扰，回想以前，当发现孩子莫名其妙地冲我们发脾气或者说些明显带情绪的话语的时候，我们不是试图跟孩子讲道理，就是大声斥责孩子，最终孩子可能再也不愿意跟我们沟通交流了。\u003cbr>【What】这段拆页就介绍了一个当孩子因为某些事产生情绪困扰的时候，家长可以运用的沟通三部曲。\u003cbr>【How】具体来说，就是这样的3个步骤——\u003cbr>倾：1、专注倾听，停下手中的事，注视孩子的眼睛，认真倾听TA说的话；\u003cbr>同2、同理感受，站在孩子的角度，表达TA的感受；\u003cbr>述：3、陈述观点，说出自己针对这件事的看法，注意态度要真诚，内容要客观。\u003cbr>谐音（青铜树）\u003cbr>在整个过程中，家长都要小心避免对孩子批评、指责，更不要说打骂。\u003cbr> \u003cbr>【where】这个三部曲不仅适用于当青少年孩子出现情绪困扰时，家长予以应对，也适用于其他年龄段的孩子，甚至成人遭遇类似问题的时候，我们去协助对方纾解情绪并增进相互之间的理解。\u003cbr> \u003cbr>举个例子，有一次我跟女儿去逛商场，在我们即将要离开的时候，我女儿要买一张带钻的贴纸，我看了下价格，一张贴纸要十几块。我就不同意买。我女儿开始发脾气，双手抱胸，嘴里发出“哼哼声”，同时不肯离开商场。我蹲下来，看着她，问：“你怎么了？”她说：“你每次都只买你喜欢的东西，我喜欢的都没有买。” 我认真地听她说话。 这是第一步：专注倾听。\u003cbr>我接着说：“这个贴纸亮闪闪的，很漂亮，你真的很想要”。 这是第二步：同理感受。\u003cbr>我女儿点头说：“恩，是的。” 我打开手机淘宝边给她看边说：“你看下，同款贴纸在淘宝上才卖5块钱，节约下来的钱，我们可以买点好吃的。”这是第三步，陈述观点。\u003cbr> \u003cbr>【异议处理】可能有人会提出来，有时候孩子就是一直发脾气，也不说为什么，我都不知道TA为什么这样，怎么跟TA沟通？这种情况当然也很常见，那就要求我们静下心来，仔细回忆一下孩子发脾气之前，TA在做什么，然后用诚恳的态度去跟孩子交流，引导TA表达，然后再认真去听孩子在说什么，这样进入三部曲。\u003c/p>","interaction":"\u003cp>接下来我们来做一个运用刚才学习到的内容的活动——\u003c/p>\u003cp>第一步，请你想象一下，在未来一周内你可能就会遇到的一个生活或工作中的被某件事情困扰而产生情绪的实际场景，比如孩子想要去同学家，但是因为某种原因你不同意，于是孩子大发脾气，或者你一回家，婆婆就开始抱怨你总是加班。 请想一下，那会是一个什么样的场景呢？ 请写在便签上。 \u003c/p>\u003cp>【学习者案例记录1】\u003c/p>\u003cp>下周我儿子想去婆婆家，但是下周有乐高课，我儿子肯定是没有办法去婆婆家的，那个时候我儿子肯定会大发脾气，甚至在地上打滚。\u003c/p>\u003cp>\u003cbr>第二步，根据刚才你想象到的那个情境，再设想一下：现在那个产生情绪的人就在你面前，你正想开导开导TA。 突然，你想起来今天在拆书晋级的现场听到的“沟通三部曲”的内容。 那么按照这3个步骤—— 1、专注倾听；2、同理感受；3、陈述观点——你可以怎么样帮助TA纾解情绪、增进理解呢？ 请思考一下，然后在便签上写下你的具体做法。\u003cbr>有没有哪位朋友愿意跟大家分享一下？ 有请——\u003cbr>【学习者案例记录2】\u003c/p>\u003cp>还是刚才那个案例，我会这样开导我的儿子，我蹲下来，先听听他在说什么？之后我就会看着他的眼睛跟他说：&quot;我知道你想去婆婆家。&quot;然后我会说：&quot;但是我们有乐高课，我们下周再去婆婆家可以吗？&quot;\u003c/p>\u003cp>今天向大家介绍了一套因某事产生情绪困扰的时候，帮助对方纾解情绪、增进相互理解的沟通三部曲：\u003c/p>\u003cp>1、专注倾听；2、同理感受；3、陈述观点。\u003c/p>\u003cp>希望能帮助大家更好地应对生活和工作中的类似场景，并且增进与对方的关系， 谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1607069037000,"updated_at":1612059949000,"ria":true},{"id":8267,"topic":"生气的三个步骤","learn_goal":"如何生气","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"张璐琳","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>亲爱的同学们，在跟随我完成本次RIA现场学习后，你们可以在遇到生气情境时不再不知所措，只好用一些伤害自己或伤害他人的行为来表达情绪，而是知道明确的步骤，并且在越来越短的时间里直至当下就能控制自己的生气情绪。\u003c/p>\u003cp>大家好，我叫张璐琳\u003c/p>\u003cp>（如果前面的人已经分组，这一步直接沿用。不用选组长。）\u003c/p>\u003cp>我们现场一共？人，我们按照座位，从谁到谁为一组（3人一组）……方便等会儿的小组讨论。\u003c/p>\u003cp>介绍图书：FAB\u003c/p>\u003cp>F:今天我要跟大家分享的片段来源于这本书《孩子，把你的手给我》，作者是海姆·G·吉诺特。他是著名的临床心理学家、儿童心理学家。\u003c/p>\u003cp>A:这本书于1965年出版，之后被翻译为了31种语言。这本书也许你没听说过，那么，有孩子的父母们，你们听说过正面管教吗？这本书可以说就是正面管教的前身。正面管教里的方法几乎都来源于这本书。如果说在父母与孩子的教育方面有什么经典著作的话，那么，首屈一指的就是吉诺特博士的这本著作——它彻底改变了父母与孩子的沟通方式，在这个领域，这是一本革命性的著作。最难能可贵的，这本书行文很生动，一点都不枯燥，是一本可以一口气读完的书。\u003c/p>\u003cp>B：你有没有在面对孩子时束手无策？（有）你没有孩子？那你有没有在面对家人，尤其是另一半的时候，在面对某一个具体问题的时候不知道如何处理？这本书不仅仅适用于孩子，还适用于其它的家庭关系。如果你想提高人际关系的质量，我相信这本书能给你一些启发。\u003c/p>","ratings_count":0,"texts":[{"id":11883,"quote":"\u003cp>当你生气的时候，你一般会怎么做呢？（和观众互动一下）摔门、大吼、哭泣、道歉、后悔、懊恼……首先，我们要明确一个观点，生气是正常的，我们有权利生气，不必感到内疚。我们要学习的是，如果在不伤害自己和他人的情况下表达我们的情绪。那么究竟应该怎么做呢？\u003c/p>\u003cp>今天我们要分享的就是一个非常实用的关于生气的片段。现在给大家两分钟时间，大家来阅读一下这个片段，阅读完之后用眼神回应一下我。\u003c/p>","explains":"\u003cp>那应该怎么“生气”呢？一共三个步骤：\u003c/p>\u003cp>第一，表达情绪（E）：我们常用的句型是“我生气了”，当然，你可以根据实际情况，加强生气的强度，比如“我现在很生气”。\u003c/p>\u003cp>第二，解释原因（R）：我们常用的句型是“我看到……”\u003c/p>\u003cp>第三，提出建议（A）：我们常用的句型是“你可以……”\u003c/p>\u003cp>我们又可以称之为“新纪元生气法”，Era。\u003c/p>\u003cp>如果你不使用这样的方法，在你被“生气恶魔”吞噬的时候，你一定不会有清晰的思路和理智的判断，在那个时候，你就会变成一个“恶魔”，只有伤害才能让我解气，这个被害者有可能是你身边的人，也有可能是你自己。而“新纪元生气法”就是你要抓狂时的“紧箍咒”。\u003c/p>\u003cp>我来跟大家分享一个我自己的案例：上上周星期一，我出门上班，临出门前告诉可儿要吃完营养早餐哦，可儿答应了。然后出门不到3分钟，就收到老公发来的小视频，可儿满地打滚不吃营养早餐，马上回家“收拾”可儿。进门后，我摔了门，摔了包，对可儿大吼，重新做了一杯营养早餐让她必须喝完，她喝吐了。当时情况很糟糕。如果我要使用“新纪元生气法”，我要怎么生气呢？\u003c/p>\u003cp>我会跟她说：“我现在非常生气。”然后告诉她：“我看到你满地打滚，大声哭闹，我辛苦做了营养早餐你也不吃……”最后给他建议：“如果你生气，可以使用‘新纪元生气法’，不需要打滚哭闹，太累了；关于营养早餐，如果你觉得不好吃，我们一起来研究如何让它变得更好吃，好吗？”这个生气法可以教会孩子如何安全地表达情绪。\u003c/p>\u003cp>有一个问题一定要注意，最开始你使用这个方法时，可能还不能很好地管理情绪，先离开，请情绪平静后再使用这个方法。因为你知道正确的方法，所以我相信你情绪平静所需的时间一定会越来越短，直到现场即刻平静。\u003c/p>","interaction":"\u003cp>拆书家提问设计（显像提问）:\u003c/p>\u003cp>你最近有没有让你特别生气的事情？请仔细听一听这些想法和做法，哪一个是你最熟悉的——你想要摔东西、打人、满地打滚、咬牙切齿、想哭、觉得特别挫败……哪种想法是你最熟悉的，是你近期经历过的？写下这个想法。\u003c/p>\u003cp>然后，你最近一次有这种想法是在什么时候？是什么事情呢？请想一想，在小组内分享，时间3分钟，每个人都尽量表达一下。\u003c/p>\u003cp>要特别强调一下的是，分享的时候一定要具体和完整，说清楚事件的时间、地点、人物、起因、经过（方法）和结果。\u003c/p>\u003cp>（1分钟后）\u003c/p>\u003cp>现在有哪位小伙伴想要来和我们分享一下你的案例吗？（必须）\u003c/p>\u003cp>（1分钟）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>前天早上我女儿在早晨上学的时候特别磨蹭，我有一个猪队友，就是我老公。我在那儿催孩子，孩子也在那儿做事。突然，我老公却对孩子说：“闺女儿，快来看……”我当时特别生气：“你有神经病啊……”\u003c/p>\u003cp>拆书家提问设计（逐字稿）:\u003c/p>\u003cp>大家可以想一想，根据我们的“新纪元生气法”，如果上天再给你一次机会，你会如果来处理当时的情况呢？请大家将自己的调整写在便签纸上，并和小组伙伴讨论一下。\u003c/p>\u003cp>（循环指导，指导重点：三个步骤的正确应用\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>我应该这么说：第一步，表达情绪：听到你这样说我真的很生气，我都快炸了。第二步，解释原因。因为我不想她每天迟到，这样让我很尴尬。第三步：以后我们可以专门约一个时间来看这个东西。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1561617846000,"updated_at":1561618633000,"ria":true},{"id":8077,"topic":"教育孩子光有爱和洞察力是不够的，教育全都体现在日常的沟通技巧","learn_goal":"运用“限制过度行为”的四个步骤，对孩子的过度行为进行约束并限","remark":"在与孩子沟通中，你是否有过语言不当，对孩子造成伤害？是否对孩子的行为直接批评否定而引起孩子的不满？是否对孩子提出的过分要求强硬拒绝，而造成孩子的情绪失控？如果你苦于不会与孩子沟通，想利用沟通技巧塑造孩子良好的品格和行为习惯，与孩子建立良好的亲子关系，那么本书会给我们想要的答案。学习目标：学习者能够在发怒或生气的情况下，运用“发怒三步曲”的方法安全的释放自己的怒气，而不伤害对方。","level":"TF2-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"李秋红","city":"烟台"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】在完成本次RIA便签学习后，学习者能够在孩子出现过度行为、提出过分要求欲望，或违反了规定、规矩，我们不允许或不希望这种不好的情况发生的情况下，运用“限制过度行为”的四个步骤，对孩子的过度行为进行约束并限制，而孩子不会产生抵触情绪或进行反击，让孩子懂得约束自己，帮助孩子建立责任感。\r\n【图书介绍】各位伙伴大家上午好，我是今天的拆书人李秋红。\r\n【F】我今天给大家带来的片段来自这本书—《孩子，把你的手给我》，这是一本儿童教育类的书，本书的作者是美国的海姆·G·吉诺特博士，著名儿童心理学家。本书告诉我们，教育孩子光有爱和洞察力是不够的，教育全都体现在日常的沟通技巧中，如何获得与使用这些技巧是这本书的主要内容。\r\n【A】这本书在自2018年1月出版以来在美国的销量达到了500多万册，以31种语言畅销全世界，豆瓣评分达到8.8分。这本书不是枯燥无味的理论说教，它是以生活中的事例诠释着与孩子沟通的技巧和智慧。\r\n【B】在与孩子沟通中，你是否有过语言不当，对孩子造成伤害？是否对孩子的行为直接批评否定而引起孩子的不满？是否对孩子提出的过分要求强硬拒绝，而造成孩子的情绪失控？如果你苦于不会与孩子沟通，想利用沟通技巧塑造孩子良好的品格和行为习惯，与孩子建立良好的亲子关系，那么本书会给我们想要的答案。","ratings_count":1,"texts":[{"id":11669,"quote":"\u003cp>我今天拆解的主题是：“限制过度行为”。下面请大家用2分钟的时间阅读下我发给大家的原文片段，阅读完后请给我一个示意。\u003c/p>\u003cp>\u003cstrong>【原文片段】《孩子，把你的手给我》P117、118\u003c/strong>\u003c/p>\u003cp>\u003cstrong>表达不同限制时要用不同方法\u003c/strong>\u003c/p>\u003cp>作出限制时，有些表达方法会引起反抗，而另一些方法则会得到孩子的合作，比如:\u003c/p>\u003cp>1.父母承认孩子的愿望，并用简单的话说出来:“你希望今晚能去看电影。”\u003c/p>\u003cp>2.父母明确指出对某个具体的为的限制:“但是我们家的规矩是“不是周末的晚上不能看电影。”\u003c/p>\u003cp>3.父母指出望至少能部分实现的途泾:“你可以星期五晚上或者星期六晚上去看电影。”\u003c/p>\u003cp>4.父母帮助孩子说出一些作出限制时可能导致的不满，然后表示同情:\u003c/p>\u003cp>“很显然你不喜欢这个规矩”。\u003c/p>\u003cp>“你希望没有这样的规矩。”\u003c/p>\u003cp>“你希望规矩是这样的:毎天晚上都能看电影。”\u003c/p>\u003cp>“当你长大了，有了自己的家庭，你肯定会改了这个规矩。”\u003c/p>\u003cp>并非总是需要这样来说出限制，这样的表达也并非总是切实可行的。有时需要先说出限制，然后再对孩子的感受做出回应。当孩子要朝妹妹扔石头时，妈妈应该说:“不准朝着她扔!朝树扔!”通过指出树的方向，她可以成功地让孩子改变石头的方向。然后，她可以回到孩子的情绪上来，建议一些没有伤害的表达情绪的方式：\u003c/p>\u003cp>“你可能很生气，以致朝妹妹扔石头。”\u003c/p>\u003cp>“你可能气坏了，在你心里，你可能恨她，但是不应该伤害她。”\u003c/p>\u003cp>“如果你想扔石头，你可以对着树扔。”\u003c/p>\u003cp>“如果你愿意，你可以告诉她，或者向她表示，你多么生气。”\u003c/p>\u003cp>表达限制时，语言不要刺激孩子的自尊。限制的语言越简洁、越客观，孩子越容易接受。“不是周末的晚上不能看电影比“你知道不是周末的晚上，你不能去看电影”引起的不满要少。“该睡觉了”比“你还小，不该熬夜熬这么晚，上床去要更容易接受些。“今天看电视到此为止了”比“你今天已经看了够多电视了，关掉电视”好。“不要互相嚷嚷”比“你最好不要再冲他喊了”更容易让孩子服从。\u003c/p>\u003cp>当限制指出个物体的功能时，孩子更愿意接受。“椅子是用来坐的，不是用来站的”比“不要站在椅子上”效果好。“积木是用来玩的，不是用来扔的”比“不要扔积木”好，也比“对不起，我不能让你扔积木，太危险了”效果好。\u003c/p>\u003cp>&nbsp; &nbsp; 好的，谢谢各位伙伴的反馈。\u003c/p>","explains":"\u003cp>下面我来谈谈对这个片段的理解：\u003c/p>\u003cp>【\u003cstrong>what\u003c/strong>】这个片段讲的是当孩子出现过度的行为或提出过分的要求及欲望时，家长运用“限制过度行为”的方法，限制、禁止其行为或欲望，而不引起孩子的反感和抗拒，让孩子懂得约束自己。\u003c/p>\u003cp>【\u003cstrong>why\u003c/strong>】\u003cstrong>（不这样做的坏处）\u003c/strong>每当孩子出现过分的要求、行为、欲望，或违反了规定、规矩等情况，我们要对他的过度行为进行约束并限制时，我们通常是怎么做的呢？通常我们会采用命令、警告、挖苦、唠叨、骂、甚至大打出手等措施，结果会导致要么伤害孩子，要么孩子不情愿、不服气、不耐烦、叛逆甚至报复，孩子也不会对自己的不合适的行为有所反省。那么当孩子出现过分的行为时，我们应该如何做呢？下面我给大家介绍一下“限制过度行为”的四个步骤：\u003c/p>\u003cp>【\u003cstrong>how\u003c/strong>】\u003c/p>\u003cp>1、承认愿望：用简单的话说出孩子的愿望。比如：“你希望把所有的玩具枪都买回来。”\u003c/p>\u003cp>2、明确限制：说出对具体行为的限制或事情的规矩。比如：“每种玩具不能超过2件。”\u003c/p>\u003cp>3、实现愿望：你可以说出孩子的愿望能够实现的途径和方法。比如：“你可以和你的同学朋友交换着玩或你用零花钱自己买。”\u003c/p>\u003cp>4、理解同情：你要理解孩子对限制的反感情绪，说出孩子的不满，然后表示同情。比如：“你一定不想要这样的规矩。”\u003c/p>\u003cp>【\u003cstrong>预防异议\u003c/strong>】也许有的伙伴会问，这四个步骤在亲子沟通中是很有效的，是不是这种方法只适合于亲子沟通？不是的，实际上只要是人际沟通都可以采取这种方法。\u003cstrong>举个例子：\u003c/strong>昨晚我家先生在家里一直看抖音刷手机玩，孩子也不爱陪，我有点不高兴的说：“你就不能放下你的手机吗？手机比我和孩子都重要是不是？你有多久没陪孩子了？”他听我这么说也不太高兴的说：“我好不容易能休息一会，你又在这挑毛病，我还不如去单位加班。”结果是两人都不太高兴！如果我当时采用了沟通的四步法，那么就不会让先生有这么大的情绪，我不想让他玩手机的心愿也会达成，会降低沟通成本，从这个例子我们可以看出，四步法适合所有的人际沟通。\u003c/p>\u003cp>\u003cstrong>【where\u003c/strong>】这种方法不仅适用于孩子的沟通，同样适用与家人、朋友或同事的沟通中。表达限制时，语言要简练、客观、坚定并且尊重，不侮辱，不专断、不反复无常，不可暴力或过度愤怒。\u003c/p>","interaction":"\u003cp>【A2催化应用分步催化1】\u003c/p>\u003cp>【\u003cstrong>拆书家提问设计逐字稿\u003c/strong>】学是为了更好的用，现在请大家想一下，在未来一周里，你也许会遇到孩子还想再多看一集动画片、想吃垃圾食品、家人只顾着玩手机、同事上班经常迟到等等场景，你会遇到什么样的的场景呢？\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp;请大家用1分钟时间，把你可能会遇到的出现过度行为的场景写在你的便签纸上，然后我会请一位伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录\u003c/strong>】孙梅：我女儿有一个毛病就是爱随手乱扔东西，昨天我下班回家，发现女儿把玩具扔的沙发地上到处都是，我就压不住火了，对她大吼：“你赶快把玩具都收起来，整天乱扔我受够了。”女儿吓得大哭起来。以后我还会遇到女儿又随手乱扔东西的情况，如果再出现这种情况，我会用限制过度行为的四个步骤与孩子沟通。\u003c/p>\u003cp>【A2催化应用分步催化2】\u003c/p>\u003cp>【\u003cstrong>拆书家提问设计逐字稿\u003c/strong>】\u003c/p>\u003cp>谢谢孙梅的分享，现在，请大家针对你刚才所设想的那个场景，让你运用“限制过度行为”的方法，与对方沟通，对对方出现的过度行为进行约束或禁止。请大家用3分钟的时间将你的具体行动步骤写在我发给大家的便签纸上。\u003c/p>\u003cp>然后我会请一位伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录\u003c/strong>】\u003c/p>\u003cp>孙梅：第一步承认愿望：我知道你自己也是不愿意这样乱扔东西的，只是养成这样的习惯了；\u003c/p>\u003cp>第二步明确限制：但是，你自己的物品你一定要自己收拾好；\u003c/p>\u003cp>第三步实现愿望：你可以选择你自己喜欢的固定位置来收纳你的东西，不用非得按照我规定的位置去收纳；\u003c/p>\u003cp>第四步理解同情：我知道你不喜欢我强迫你，但是这是家里的规矩，你可以等你长大后自己来定规矩。\u003c/p>\u003cp>【小结】\u003c/p>\u003cp>&nbsp; &nbsp;好的，感谢伙伴们今天的参与和分享，今天我们一起学习了“限制过度行为”的方法，分别是：承认愿望、明确限制、实现愿望、理解同情，希望通过今天的学习，能够在孩子出现过度行为时，进行约束并限制，让孩子懂得约束自己，帮助孩子建立责任感，我今天的拆书就到这里了，谢谢大家，期待下次的相聚！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1559617763000,"updated_at":1559617763000,"ria":true},{"id":8005,"topic":"本书的主旨是讲父母如何正确有效地与孩子沟通","learn_goal":"父母在不同情境下语言技巧的运用","remark":"本书是一本经典的亲子沟通类实用书籍，它的作者是美国的海姆·G·吉诺特博士，著名的心理学教授、儿童心理学家。书中分10个章节讲述了父母在不同情境下语言技巧的运用，以及在不同问题上的应对方法。所涉及的问题几乎囊括了父母和孩子之间日常可能发生的全部状况。这本书在自2018年1月出版以来在美国的销量达到了500多万册，以31种语言畅销全世界，豆瓣评分达到8.8分。本书的主旨是讲父母如何正确有效地与孩子沟通。同一主旨的书应该是不在少数，但这本书提出了这样的命题：只拥有爱和洞察力是不够的，父母需要技巧和对孩子的理解，才能解决在沟通中发生的各种冲突和不幸。你在教育孩子过程","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"李秋红","city":"烟台"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】在完成本次RIA便签学习现场后，学习者能够在发怒或生气的情况下，运用“发怒三步曲”的方法安全的释放自己的怒气，而不伤害对方。\r\n【图书介绍】各位伙伴大家晚上好，今天晚上是咱们八仙分舵第7次线下拆书，我是今天的拆书人李秋红，我今天要拆的书就是这本《孩子，把你的手给我》。\r\n【F】本书是一本经典的亲子沟通类实用书籍，它的作者是美国的海姆•G•吉诺特博士，著名的心理学教授、儿童心理学家。书中分10个章节讲述了父母在不同情境下语言技巧的运用，以及在不同问题上的应对方法。所涉及的问题几乎囊括了父母和孩子之间日常可能发生的全部状况。\r\n【A】这本书自2018年1月出版以来在美国的销量达到了500多万册，被翻译成31种语言畅销全世界，豆瓣评分达到8.8分。本书的主旨是讲父母如何正确有效地与孩子沟通。同一主旨的书应该是不在少数，但这本书提出了这样的命题：只拥有爱和洞察力是不够的，父母需要技巧和对孩子的理解，才能解决在沟通中发生的各种冲突和不幸。\r\n【B】你在教育孩子过程中是否有过无计可施、无能为力的感觉？是否有自认为已经了解很多育儿常识，却依然不会与孩子沟通的情况？当孩子出现不合作、叛逆、生气发脾气等各种状况时，你是如何沟通的呢？这本书会给我们想要的答案，它教会我们运用语言的力量，让我们真正的与孩子实现有效的沟通。","ratings_count":1,"texts":[{"id":11585,"quote":"\u003cp>我今天拆解的主题是：“安全的表达愤怒”。通过今天的学习，我们能够在生气或发怒的情况下，运用“发怒三步曲”的方法安全的释放自己的怒气，而不造成伤害。下面请大家用2分钟的时间阅读下我发给大家的原文片段，阅读完后请给我一个示意。\u003c/p>\u003cp>\u003cstrong>【原文片段】《孩子，把你的手给我》P43\u003c/strong>\u003cstrong>、44\u003c/strong>\u003c/p>\u003cp>发怒的三个步骤\u003c/p>\u003cp>在平静时期，让自己做好应付紧张时刻的准备，应该承认下面的事实。\u003c/p>\u003cp>1．我们接受这个事实：在跟孩子打交道的时候，我们有时会发脾气。\u003c/p>\u003cp>2．我们有权生气，而不必感到内疚或者羞愧。\u003c/p>\u003cp>3．除了安全考虑，我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者性格，我们就可以表达我们的愤怒。\u003c/p>\u003cp>这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”“我觉得讨厌”“我觉得被激怒了”。\u003c/p>\u003cp>如果简短的陈述和拉长着的脸并没有产生效果，那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>“我生气了。\u003c/p>\u003cp>“我退生气。”\u003c/p>\u003cp>“我非常非常生气。”\u003c/p>\u003cp>“我气极了。”\u003c/p>\u003cp>有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>\u003cp>“当我看到鞋子、子、衬衫、运动衫扔得满地都是时，我很生气，生气极了。我真想打开窗户，把这一推乱七八槽的东西扔到大街上去。”\u003c/p>\u003cp>“看到你打你的弟弟，我很生气，里面像有团火在烧，我决不允许你再伤害他。”\u003c/p>\u003cp>“看到你们所有的人一吃完晚就冲出去看电视、把那些脏今今的盘子、油膩胍的锅留给我时，我非常愤概！气得我简直七窍冒烟！我真想把所有的盘予砸到电视上去！”\u003c/p>\u003cp>“我叫你吃晚饭，而你却不来，我生气，非常生气，我对自己说：我煮了一餐好吃的，希望获得赞賞和感激，而不是失望。”\u003c/p>\u003cp>&nbsp; &nbsp;这个方法可以帮助父母释放怒气，而不致引起伤害，而且，它甚至可以是一堂重要的课，教会孩子如何安全地表达愤怒。孩子可能会明白他自已的愤怒也不是什么大的灾难，可以释放出来，而不会伤害任何人。这堂课不仅仅需要父母把怒火发泄出来，还需要父母向孩子指出情感表达的可接受的方式，要向他们说明表达愤怒应该采取的安全、可理解的方法。\u003c/p>","explains":"\u003cp>好，伙伴们都看完了，下面我想谈谈对这个片段的理解。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>这个片段讲的是：当孩子出现不良行为，让我们无法容忍时，我们可以用“发怒三步曲”的方法，安全的表达愤怒，释放怒气，而不伤害孩子。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003cstrong>（不这么做的坏处）\u003c/strong>当孩子出现不良的言行举止，让我们感到无法忍受时，或孩子犯了错误让我们很生气时，我们是怎么做的呢？我们通常是要么挖苦讽刺、威胁警告，要么直接破口大骂、大打出手来发泄自己的情绪，这样做孩子会反抗、也可能会暂时屈服，但却不会从根本上解决问题，而且还伤害了孩子的身心健康，只能让孩子将注意力转移到对家长的怨恨中，而没有认识到自己的错误或不良行为。\u003c/p>\u003cp>\u003cstrong>【举例说明】比如：\u003c/strong>\u003c/p>\u003cp>2016年夏天的一个上午（时间），我骑车带儿子（人物）回家的路上（地点），他把脚放在车轱辘边上摩擦着玩，脚拖拉在地上，鞋子也磨坏了（起因），我发现后停下来告诉他不要这么做，很危险，他当时嘴上答应却依然我行我素，在第三次劝告无效后，我非常生气的把他揪下车，踢了他一脚，告诉他：“你自己跑回家。”我佯装着骑车要走，他吓坏了，哭着喊我不要扔下他，告诉我再也不敢了！这件事后孩子总是害怕我抛下他不管他，缺乏安全感。（结果）\u003c/p>\u003cp>\u003cstrong>【反思】\u003c/strong>当时没有按照“三步曲”的方法理性的表达自己的愤怒，而是直接采用暴力手段，给孩子造成了伤害，让孩子感觉到无助无望，没有安全感，也没有真正的意识到自己的不良行为。\u003c/p>\u003cp>那么当我们生气后的正确的做法是什么呢？下面我就来介绍下“发怒三步曲”的具体步骤：\u003cstrong>&nbsp; \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>1.承认事实：首先我们要接纳自己，要接受我们会发脾气的事实，在不伤害孩子人格及人身安全的前提下，我们有权发怒生气，而不必感到自责内疚。\u003c/p>\u003cp>2.表达感受和强烈的愤怒情绪：用“我”开头表达自己的情绪和感受。比如：“我感觉很烦！”“我觉得没被尊重！”如果表达感受后，依然没有效果，可以表达我们强烈的愤怒。比如：“我真是受不了了，我现在非常非常生气！”“真是气死我了！”\u003c/p>\u003cp>3.解释原因、说出想法及想做的事：你可以解释你为什么生气，说出自己的想法和我们非常想做的事。比如：“你吃饭时挑三拣四，不停的抱怨（原因），我感到自己的辛苦付出没有得到尊重（想法），我非常非常生气，我真想把这些饭都倒掉，谁也不用吃了（想做的事）！”\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>就拿刚才我的故事为例，我运用“发怒三步曲”应该这样做：\u003c/p>\u003cp>1.先承认事实：在不伤害孩子的前提下我有权生气，不用内疚自责。\u003c/p>\u003cp>2.再表达感受和愤怒：：“景友豪，我现在是既生气又担心，我马上就要爆发了！我很生气！”\u003c/p>\u003cp>3.最后解释原因、说出想法及想要做的事：“万一出现意外，你的脚会受很严重的伤，很长时间都不能走路，而你却把我的劝告当作耳边风，我的耐心被你耗尽了，如果你还我行我素，那么我只能让你下车，你自己跑回家！”\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>这种方法不仅适用于孩子，面对家人、朋友、同事、领导表达自己的生气和愤怒同样适用，对待长辈表达愤怒情绪时可以表达感受并解释原因，情绪过激则不合适。\u003c/p>","interaction":"\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>阅读了刚才这个拆页，我们知道了如何表达愤怒的方法，那么请各位伙伴想象一下，你带着孩子出门吃饭，在饭店里孩子大喊大叫上蹿下跳，你屡教不改，最后忍无可忍，你是怎么表示你的愤怒的？或者你与家人因为干家务活的多少而闹得不愉快，非常委屈气愤，你又是怎样表达的？你有没有与孩子，家人、同事或朋友发生过不愉快的冲突事件，让你感到很生气、很愤怒？回想一下当时的情景和你的感受，将事情的前因后果以及你是怎样做的在小组内分享。请用3分钟时间在组内讨论，等下我会请一位伙伴分享他的故事。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>孙梅：前天晚上我从乡下回来，一进家门就看见家里跟猪窝一样乱，就非常恼火，直接就爆发了，我就对老公说：“你们这两天是猪吗？你们住的是猪圈吗？”我老公很不耐烦的回答说：“我能把孩子给你照看好就不错了！”最后我俩闹得很不愉快！家里也没收拾。\u003c/p>\u003cp>&nbsp;感谢孙梅的分享，非常生动！\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>刚才大家的故事是未使用“发怒三步曲”的处理方式，那我们一起回顾一下今天学习的“发怒三步曲”，一是承认事实，二是表达感受和强烈的愤怒情绪，三是解释原因、说出想法及想做的事。假设时光可以倒流，再回到当时的情境，让你根据拆页中学到的“发怒三步曲”的方法，去表达你的愤怒情绪，你又会如何表达？请大家用3分钟的时间，将你的行动步骤写在我发给大家的便签纸上。然后我会请一位伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>孙梅：首先，我会接纳自己的情绪，对自己说生气是正常的，但要尽力的控制情绪；然后我会表达我的感受和愤怒的情绪——我非常生气，你这样做让我感觉非常非常难受；最后我会说出原因想法和自己想做的事——你知道嘛，你看电视不吃饭的行为让我感觉我的辛苦付出被辜负了，我也有很难受的时候，我也很想哭，我特别不想让你吃饭，我又怕你不吃饭又很饿，你还要这样继续做吗？”\u003c/p>\u003cp>【小结】感谢孙梅的分享！请大家给他热烈的掌声！\u003c/p>\u003cp>&nbsp; 好的，今天我们一起学习了“发怒三步曲”，分别是：承认事实，表达感受和强烈的愤怒情绪，解释原因、说出想法及想做的事。希望通过今天的学习，能够让我们在生气时，理性的释放我们的怒气，而不伤害对方。我今天的拆书就到这里啦，谢谢大家，期待下次的相聚！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1558964393000,"updated_at":1558964393000,"ria":true},{"id":6902,"topic":"表达愤怒三步法","learn_goal":"当被孩子的不良行为惹怒时，用安全表达愤怒的三步法表达愤怒","remark":"","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"郭露","city":"雅安"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; 大家好！我叫郭露，三个标签是运动、宝妈、成长。\r\n分组：\r\n &nbsp; &nbsp; &nbsp;以桌为单位 ，刚好每组都是四人。做个现场调查：“有小孩的小伙伴，请举手！”“刚好每组都至少有一位。”\r\n学习目标：\r\n &nbsp; &nbsp; &nbsp;在跟随我完成本次RIA现场学习后，学习者能够解决遇到孩子不良行为而感到愤怒时，采用表达感受，强化感受，说出想法三步来表达愤怒，从而避免冲突升级，造成孩子内心创伤,让孩子健康成长。\u003c/p>\u003cp>图书介绍：&nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; F：特征&nbsp;拆段选自&nbsp;《孩子，把你的手给我》作者海姆.G.吉诺特,是心理学的博士，本书主要介绍了于孩子实现真正有效沟通的方法。\u003c/p>\u003cp>&nbsp; &nbsp; A：优势&nbsp; 本书在《自助书籍的权威指南》一书中，获得最高评价——“强烈推荐”，而且列在自助书籍的决选名单中。\u003c/p>\u003cp>&nbsp; &nbsp; B：利益&nbsp; 我想没有一位父母会说：“今天只要有机会，我就要向我的孩子大喊大叫、唠叨，要让他丢脸、出丑。”相反每天早晨，许多父母都下定决心：“今天是平静的一天，没有叫嚷，没有争辩，没有战争。”但是，尽管有好的意图，讨厌的战争还是会再次爆发。吉诺特博士在书中倡导的沟通技巧，帮助成年人以同情和关爱的方式进入孩子的世界，教给成年人如何了解孩子的感受并对其做出反应。正好可以帮助我们化解这样的困扰。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;请小伙伴们拿出拆页，2分钟时间阅读，阅读完的小伙伴举手示意我一下。谢谢！\u003cbr>\u003c/p>","ratings_count":2,"texts":[{"id":10266,"quote":"\u003cp>发怒的三个步骤：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在平静时期，让自己做好应付紧张时刻的准备，应该承认下面的事实：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 1．我们接受这个事实：在跟孩子打交道的时候，我们有时会发脾气。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 2．我们有权生气，而不必感到内疚或者差愧。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 3．除了安全考虑，我们有权利表达自己的感觉。只要我们不攻击孩子的人品或者牲格，我们就可以表达我们的怒。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 这些假设应该列入处理愤怒的具体步骤中去。处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我“我觉得讨厌。”“我觉得被激怒了。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 如果简短的陈述和拉长着的脸并没有产生效果，那么采取第二个步骤。在表达时加强愤怒的强度：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;“我生气了。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;“我退生气。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;“我非常非常生气。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;“我气极了。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 有时，仅仅表达出我们的感受（不用解释原因）就能让孩子停止不端行为。但是，有时候，可能需要采取第三个步骤解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>","explains":"\u003cp>What&nbsp; &nbsp;愤怒、生气、伤心、难过都是我们的感受，感受没有对错之分，它是我们生而为人的情绪体验。只有积极情绪和消极情绪的区别。在面对孩子的不良行为时，我们难免会生气、愤怒。只要不攻击孩子的人格，我们是可以表达愤怒的，不过我们提倡积极表达或者安全表达。\u003c/p>\u003cp>why&nbsp; &nbsp;&nbsp;因为我们不表达或者消极表达（过分表达）都会对孩子的成长不利。\u003c/p>\u003cp>How&nbsp; &nbsp;&nbsp;安全表达愤怒的三步法：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;1.&nbsp;&nbsp;&nbsp;&nbsp; 表达感受：准确告知相关人，我现在的感受。比如：“我被激怒了！”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;2.&nbsp;&nbsp;&nbsp;&nbsp; 感受强化：表达时强化情绪的程度：“我现在非常愤怒！”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;3.&nbsp;&nbsp;&nbsp;&nbsp; 说出想法：想法可以是我们愤怒的原因，当下内心的想法或者我们希望的行为。“我非常愤怒，一看到你打弟弟，我心里有团火在烧，我绝不允许你伤害他。”\u003c/p>\u003cp>【不这么做的坏处】&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;通常大家都只做了1、2步并且强化和过激的表达了而忘了第三步，可能对孩子造成了伤害，所以第三步很重要。而有一些父母为了避免对孩子造成心灵创伤，而选择不表达愤怒，不做1、2步，往往会憋出内伤，在忍无可忍的时候把愤怒积累到了极点爆发一场，扭曲的表达1、2步肆意宣泄我们愤怒，结果除了给孩子带来心灵创伤，还一点点的吞噬掉孩子的在家里的价值感和归属感，在一点点的把孩子往家门外推，我相信这不是我们所希望的。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我在眉山上班几天回家一次，11月第三次回家的时候一开我的房间门，惊呆了。各种玩具满房间都是，床上也是。一股怒火瞬间就上来。大声招呼孩子过来，大家觉得他会过来吗？不会。那只好我过去把他揪到案发现场哈。路上我都是想的怎么吼他不听就打他的念头。如果我真这么做了有可能会造成孩子愤恨、报复、反叛、退缩，不敢去细想哈。当我看到他的表情是不好意思，有点扭捏时，其实他已经知道错了。大家认可吗？ 我当时是这么说：“1.表达感受：柴柴，我感到很生气，2.强化感受:真的非常生气，3.说出想法：我们的房间像小狗住的地方，我们现在该怎么办呢？”“我们一起收拾吧！”结果孩子跟我一起愉快的收拾了房间。当孩子同意和我一起收拾的时候，就是他改错和进步的时候，所以我推荐安全表达愤怒的3步法。\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;请大家一起来回想一下，最近收否因为孩子不吃饭、不睡觉、不刷牙、不洗澡、作业拖拉、房间凌乱等等情况而使你生气愤怒？小组讨论5分钟。\u003c/p>\u003cp>小伙伴分享\u003c/p>\u003cp>&nbsp; &nbsp; 孩子两岁，曾经很听话很可爱的孩子，现在一言不合就地打滚。第一次遇到情况的时候就懵了，大家都很生气。爸爸还对孩子说：“你这招没有用哈，在我们家是不可能的，你自己起来。”\u003c/p>\u003cp>&nbsp; &nbsp; 非常感谢小伙伴的分享，孩子两岁确实对父母来说是一个挑战。\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>&nbsp; &nbsp; 想想看，再遇到这样的情况，你可以应用表达愤怒的三步法，怎样安全的表达愤怒呢？小组讨论并写在便签上。\u003c/p>\u003cp>小伙伴分享案例\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;小朋友挑食，吃饭非常少。“妈妈生气了，妈妈非常生气，你这样挑食长期营养摄入不均衡对，多身体不好，就不能长高长漂亮了。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;谢谢小伙伴的分享！这就是我分享给大家安全表达愤怒的三步法，希望大家回家以后能运用起来，能帮助大家改善的亲子关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1545893196000,"updated_at":1545893814000,"ria":true},{"id":6608,"topic":"“限制的技巧”","learn_goal":"如何为孩子的行为设立界限","remark":"","level":"TF2-3","duration":30,"status":29,"type":0,"chaishujia":{"username":"王焱","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>尊敬的观察家、各位亲爱的小伙伴，晚上好！&nbsp;\u003c/p>\u003cp>我是今天晋级2-3的王焱。 用3个标签介绍自己，分别是“职业培训师”、“驴友”和“妈妈”。&nbsp;\u003c/p>\u003cp>现在我把大家分成3个小组，这边是一组，中间是一组，那边是一组。&nbsp;\u003c/p>\u003cp>今天我要拆的这本书叫做《孩子，把你的手给我——与孩子实现真正有效沟通的方法》。 &nbsp;\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>作者海姆.吉诺特博士是美国著名的儿童心理学家和儿科医生。 这本书于1965年首版，出版后曾高居美国各大图书排行榜榜首长达一年之久，并被翻译成31种语言畅销全球。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>这本书的主要内容是针对家长与孩子的沟通中存在的诸多问题，教授如何实现真正有效的亲子沟通。 同当时的其他亲子书籍比较，这本书提出的很多观点都是颠覆性的，因而也被认为是亲子教育领域首屈一指的“革命性的著作”\u003c/p>\u003cp>\u003cstrong>【B1】\u003c/strong>家长对于孩子的不能接纳的行为，有时会采取责备、命令、威胁、哄劝、说教等方式去回应。 这些沟通方式既不能达到理想的效果，又可能对孩子造成心理上的伤害。 这本书就教给父母们很多实用的技巧，用于改善与孩子的沟通，同时引导孩子成为自信、自立、自爱而又富有担当的人。\u003c/p>\u003cp>\u003cstrong>【B2】\u003c/strong>今天的拆页将聚焦于如何为孩子的行为设立界限，既让孩子清楚地知道什么可为，什么不可为，又尽可能避免抵触和冲突。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用完整告知、清楚界定、坚定表达、传递尊重、区别对待等5个步骤对孩子设立行为上的界限。 在表达限制的时候，不仅清楚和坚定，同时也尽可能避免抵触和冲突。\u003cbr>\u003c/p>\u003cp>这次要拆的原文片段来自于这本书的第5章，“纪律：寻找替代惩罚的有效手段”。\r\n现在请大家阅读手中的拆页。读完以后请举手示意一下，谢谢！\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":9941,"quote":"\u003cp>限制的技巧\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在制定限制时——就像其他所有教育手段一样——成果取决于方法。 限制必须清楚地告诉孩子：（a）什么是不可接受的行为；（b）什么替代行为是可以接受的。 你不可以扔盘子，你可以扔枕头。 或者用不太符合语法却更有效的句子：“盘子不是用来扔的，枕头是可以拿来扔的”；“你的弟弟不是用来推的，你的踏板车是用来推的”。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;制定限制时，最好要全面，而不要部分限制。 例如：往妹妹身上泼水和不要往妹妹身上泼水，中间的区别很清楚。 如果限制是这样的：“你可以往她身上泼一点点水，只要不把她弄得太湿就行了。” 这样的限制简直就是在鼓励用水浇她，惹来麻烦。 这样模糊的话没有给孩子一个赖以做决定的清晰的根据。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;作出限制时，语气必须坚定，这样会传达给孩子一个信息：“这个禁令是真的，我是认真的。” 如果父母不太确定该怎么做，这时最好是什么也不要做，先思考、弄清自己的态度。 在作出限制时，如果父母的话模棱两可，就会陷入无休止的争论中。 犹豫不决的、笨拙的限制是对孩子的一个挑战，会引起关于意志的一场战争。 在这场战争中，谁也不会赢。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;作出限制时该用什么态度，必须谨慎思考，要把孩子的不满降到最低程度，要保留孩子的自尊。 规定限制、说“不”的最合适的方法是要表达出权威，而不是侮辱。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;限制应该用于处理具体的事件，而不适用于处理变化发展的历史。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>孩子的规则意识并不是与生俱来的，这就意味着作为家长，我们需要为孩子的行为设立界限，也就是说，要让孩子清楚地知道，什么行为是被接受的，什么行为是不被接受的。 针对那些不被接受的行为，我们就需要作出限制。&nbsp;\u003c/p>\u003cp>\u003cstrong>【Why/不这样做的坏处】\u003c/strong>但在做出限制的时候，如果家长没有清楚地告知，那么孩子对于什么可以做、什么不可以做，就不会有清晰的概念；如果家长态度不够坚决，那么孩子对于规则就可能不会严格地遵守；如果家长只是运用权威，对孩子说“不行”，甚至强行阻止，往往会让孩子反感甚至激起反抗。 比如有报道说一个孩子喜欢玩手机打游戏，家长多次教育无效。 有一天家长发现孩子又在玩，于是夺过手机扔出窗外，没想到孩子跟着就跳下去了。 那么如何防止这种类似的悲剧发生，正确地给孩子的行为设立界限呢？\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>根据这段拆页的内容，我们可以采用以下5个步骤来设立规则、表达限制——\u003c/p>\u003cp>1.完整告知。 告知内容应包括两个方面：第一，什么行为是不被接受的；第二，可以采取什么样的替代行为。 比如，孩子用水枪对着人瞄准，你就可以对他说：“水枪是不能用来射人的，你可以射那棵树。”\u003c/p>\u003cp>2.清楚界定。 “可以”与“不可以”之间有明确的区分。 比如，你不允许孩子玩你的手机，你可以告诉孩子：“你不可以玩妈妈的手机。” 但如果你说的是“妈妈现在跟人说工作上的事情，你不可以玩妈妈的手机。” 那么孩子或许就会这样理解：当妈妈没有用手机处理事情的时候，我就可以玩她的手机。\u003c/p>\u003cp>3.坚定表达。 坚定的语气传递的是父母坚定的态度。 比如：“不准打人”就比“宝宝，你怎么能打人呢？”更能起到阻止孩子的效果。\u003c/p>\u003cp>4.传递尊重。 虽然做出限制时我们是利用了家长的权威，但这并不意味着我们就可以践踏孩子的自尊。 比如，孩子希望你再给他买一件玩具，如果你说：“还要玩具？ 你看你已经有多少玩具了？ 你怎么看见什么都想要！” 这种攻击人格的语言可能会带给孩子你意想不到的伤害。\u003c/p>\u003cp>5.区别对待。 限制应该是针对当下的某一具体事件。 随着时间和情境的变化，限制可能改变甚至撤销。 比如：孩子3岁的时候你是决不允许他独自离开家跑到外面玩的，但到孩子8岁的时候，他自己在小区里面骑骑自行车，你就完全可以接受了。\u003c/p>\u003cp>下面我再通过一个自己的案例帮助大家进一步地掌握设立界限、表达限制的5个步骤——\u003c/p>\u003cp>我的孩子还在幼儿阶段，所以我是限制她看电视的，只允许周末的时候看一小会儿。 我是这样同她沟通的——\u003c/p>\u003cp>1.完整告知：“宝宝，你不能天天看动画片，但是妈妈给你买了《小猪佩奇》的画册，你可以看那个。”\u003c/p>\u003cp>2.清楚界定：“只有在周末的时候，你可以看3集《小猪佩奇》。”\u003c/p>\u003cp>3.坚定表达。 无论孩子耍赖还是耍嗲，我都会这样回应：“现在不是周末，只有周末你才可以看。”\u003c/p>\u003cp>4.传递尊重：“妈妈知道你很喜欢看《小猪佩奇》，妈妈也觉得那个动画片挺好看的，但是你这个年纪的小朋友还不适合多看电视。”\u003c/p>\u003cp>5.区别对待：“你现在还不到5岁，不能多看电视；等你满了7岁，你看电视的时间就可以再长一点；等你长到像阳阳哥哥（她14岁的表哥）那么大的时候，你就可以自己决定看多长时间了。”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>可能有的朋友会有这样的疑问——只要对孩子进行限制，我都需要走完这5个步骤吗？ 答案是不一定。 在有些紧急情况发生的时候，比如危及孩子自身或他人的人身安全，就需要马上进行限制，而不需要按照这样的5个步骤来操作。\u003c/p>\u003cp>比如，你看到二宝抢夺大宝的玩具，大宝很生气，要把二宝推倒，这时你就可以马上说：“不能推妹妹！” 首先制止大宝的行为，然后在风险解除之后，再同孩子进行沟通。\u003c/p>\u003cp>按照这样的5个步骤来表达限制——完整告知、清楚界定、坚定表达、传递尊重和区别对待，我们给孩子设立的界限就不仅清楚和坚定，同时也能够尽可能避免抵触和冲突。\u003c/p>\u003cp>同时，这种表达限制的方法，不仅适用于家长给孩子设立界限，同样也适用于在职场里面给新人制定规则。\u003c/p>","interaction":"\u003cp>接下来我就提供一个场景，请大家运用这5个步骤来做表达限制的演练。 这个场景是这样的——\u003c/p>\u003cp>你有一个5岁的女儿。 你认为充足的睡眠对幼儿来说非常重要，所以你希望她每晚按时睡觉。 可是每次当你提醒她收拾玩具准备洗漱的时候，她都舍不得放下玩具，而是尽量拖延，推迟上床的时间。 那么运用给孩子设立界限的5个步骤，现在你可以怎么同她沟通呢？ 既让她清楚地知道必须在晚上8点开始收拾玩具，然后洗漱上床，同时又尽可能地遵守这个规则。&nbsp;\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>请基于这个场景和沟通目的，一个人扮演家长，一个人扮演孩子，按照5个步骤把你们对话的过程模拟出来，稍后进行发表。\u003c/p>\u003cp>（分组研讨）\u003c/p>\u003cp>现在请组长指定两位代表发表本组的研讨结果。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录1】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>妈妈：儿子，现在已经8点钟，收拾玩具吧，我们要按照约定准备上床睡觉了，你可以明天再玩。\u003c/p>\u003cp>儿子：我还想再玩会儿。\u003c/p>\u003cp>妈妈：我们说好的，7点到8点钟是玩玩具的时间，现在时间已经到了，该收拾玩具准备上床睡觉了。\u003c/p>\u003cp>儿子：我正玩得起劲呢，我还想再玩一会儿水枪。\u003c/p>\u003cp>妈妈：不行，我们需要准备上床睡觉，时间到了。 我非常能够理解你现在想要继续玩水枪，妈妈也觉得这个水枪挺好玩的，但是时间已经到了，我们需要收拾玩具准备上床睡觉了。\u003c/p>\u003cp>儿子：好的好的……但是，我看其他的，比如那个小姐姐，他们都是睡得很晚呐。\u003c/p>\u003cp>妈妈：你看你现在还是长身体的时候，那个小姐姐不一样，她已经长大了。 你必须要保证10个小时的睡眠，而她只需要保证8个小时的睡眠。 咱们现在赶紧收拾玩具，妈妈给你洗漱，然后我们就上床睡觉，好不好？\u003c/p>\u003cp>儿子：好嘛。\u003c/p>\u003cp>\u003cstrong>【反馈】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>谢谢两位的演练！ 他们运用这5个步骤是比较清晰的。 只是在最后这个“区别对待”的环节，可以补充一句：“等你长到小姐姐那么大的时候，你就可以再多玩一会儿，上床的时间再推迟一些了。” 我们也可以看到，通过运用这5个步骤表达限制，传递的限制信息更明确，同时相比妈妈直接命令甚至强行要求孩子收拾玩具，引起孩子抵触和反抗的可能性会小很多。\u003c/p>\u003cp>下面有请另一组——\u003c/p>\u003cp>\u003cstrong>【学习者案例记录2】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>爸爸：宝贝儿，现在我们该收拾玩具准备上床睡觉了，你可以明天接着玩。\u003c/p>\u003cp>女儿：（沉默）\u003c/p>\u003cp>爸爸：宝贝儿，8点钟以前是可以玩玩具的，但过了8点就不能继续玩了。&nbsp;\u003c/p>\u003cp>女儿：可是我还想跟小猪佩奇再玩一会儿。\u003c/p>\u003cp>爸爸：小猪佩奇也需要睡觉。 她跟你一起睡觉，好吗？ 你可以明天再跟她玩。 我也知道你很喜欢小猪佩奇，想跟她多待一会儿，但她也要睡觉了——跟你一样，需要注意身体。 当然，周末的时候，不上幼儿园，我们就可以多玩半个小时，好吗？\u003c/p>\u003cp>女儿：好。\u003c/p>\u003cp>\u003cstrong>【反馈】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>我们对照一下这5个步骤，这一组的应用是不是清晰？ 第一步和第二步特别清晰，后面这三步结合到一起了。 通过运用这5个步骤，孩子清楚地知道了8点以前可以玩玩具，8点以后需要收拾玩具准备睡觉这样的限制信息，以及周末可以多玩半小时这样的区别对待方案，也感受到了爸爸对她的理解和尊重，于是就很配合地接受了。 很不错，在这么短的时间里面，大家就已经把知识点吸收了。\u003c/p>\u003cp>今天给大家介绍了向孩子表达限制的5个步骤——完整告知、清楚界定、坚定表达、传递尊重和区别对待。 希望在各位需要给孩子做出限制的时候，或者对其他人需要进行行为上的约束的时候有所帮助，不仅达到限制和约束的目的，同时尽可能维护关系。\u003c/p>\u003cp>好，我的分享就到此结束，谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543512652000,"updated_at":1546903013000,"ria":true},{"id":6606,"topic":"“表达限制的方法”","learn_goal":"如何在需要约束孩子或其他人的问题行为时有技巧地表达。","remark":"","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"王焱","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>尊敬的观察家、各位亲爱的小伙伴，晚上好！ \r\n我是今天晋级2-1的王焱。 用3个标签介绍自己，分别是“职业培训师”、“驴友”和“妈妈”。&nbsp;\u003c/p>\u003cp>在正式开始之前，我先把大家分为两组——这边的朋友是一组，那边的朋友是另一组。\u003c/p>\u003cp>今天我要拆的这本书叫做《孩子，把你的手给我》。&nbsp;\u003c/p>\u003cp>【F】作者海姆.吉诺特博士是美国著名的儿童心理学家和儿科医生。 这本书于1965年首版，以如何实现真正有效的亲子沟通为主题。&nbsp;\u003c/p>\u003cp>【A】这本书出版后曾高居美国各大图书排行榜榜首长达一年之久，并被翻译成31种语言畅销全球，被认为是亲子教育领域首屈一指的“革命性的著作”。&nbsp;\u003c/p>\u003cp>【B1】家长对于孩子的不能接纳的行为，有时会采取责备、命令、威胁、哄劝、说教等方式去回应。 这些沟通方式既不能达到理想的效果，又可能对孩子造成心理上的伤害。 这本书就教给父母们很多实用的技巧，用于改善与孩子的沟通，同时引导孩子成为自信、自立、自爱而又富有担当的人。&nbsp;\u003c/p>\u003cp>【B2】今天的拆页将聚焦于对孩子进行限制时如何有技巧地表达，既争取孩子的合作，又避免冲突、维护关系。&nbsp;\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者将能够在需要约束孩子或他人的行为时摒弃简单粗暴的方式，采用表达愿望、指出限制、给予选择和同理感受等4个步骤来表达，从而避免冲突、争取达成合作。&nbsp;\u003c/p>\u003cp>这次要拆的原文片段来自于这本书的第5章，“纪律：寻找替代惩罚的有效手段”。\r\n现在请大家阅读手中的拆页。读完以后请举手示意一下，谢谢！\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9939,"quote":"\u003cp>表达限制的方法\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;作出限制时，有些表达方法会引起反抗，而另一些方法则会得到孩子的合作，比如：\u003c/p>\u003cp>1.父母承认孩子的愿望，并用简单的话说出来：\u003c/p>\u003cp>“你希望今晚能去看电影。”\u003c/p>\u003cp>2.父母明确指出对某个具体的行为的限制：\u003c/p>\u003cp>“但是我们家的规矩是‘不是周末的晚上不能看电影’。”\u003c/p>\u003cp>3.父母指出愿望至少能部分实现的途径：\u003c/p>\u003cp>“你可以星期五晚上或者星期六晚上去看电影。”\u003c/p>\u003cp>4.父母帮助孩子说出一些作出限制时可能导致的不满，然后表示同情：\u003c/p>\u003cp>“很显然你不喜欢这个规矩。”\u003c/p>\u003cp>“你希望没有这样的规矩。”\u003c/p>\u003cp>“你希望规矩是这样的：‘每天晚上都能看电影’。”\u003c/p>\u003cp>“当你长大了，有了自己的家庭，你肯定会改了这个规矩。”\u003c/p>","explains":"\u003cp>【How】这段拆页的内容介绍了向孩子表达限制的4个步骤，分别是——\u003c/p>\u003cp>第一，表达愿望；\u003c/p>\u003cp>第二，指出限制；\u003c/p>\u003cp>第三，给予选择；\u003c/p>\u003cp>第四，同理感受。\u003c/p>\u003cp>【What】在孩子成年以前，作为监护人，我们会对孩子的行为做出这样那样的限制，有时是为了建立界限，有时是为了保障安全，有时是为了帮助孩子养成良好的习惯。\u003c/p>\u003cp>【Why/不这么做的坏处】但在做出限制的时候，如果家长只是运用权威，对孩子说“不行”，甚至强行阻止，往往会让孩子反感甚至激起反抗。 比如有报道说一个孩子喜欢玩手机打游戏，家长多次教育无效。 有一天家长发现孩子又在玩，于是夺过手机扔出窗外，没想到孩子跟着就跳下去了（反面案例）。 作为家长，我们都绝对不希望发生这样的事情，那么根据表达限制的4个步骤，我们可以怎么做呢？\u003c/p>\u003cp>首先，承认孩子的愿望——“妈妈知道你喜欢打游戏，打游戏确实很好玩。”&nbsp;\u003c/p>\u003cp>然后指出限制——“但是你要先完成作业，然后才能玩游戏。”&nbsp;\u003c/p>\u003cp>接下来给予选择——“你可以在每天做完作业以后玩半个小时游戏。”\u003c/p>\u003cp>最后同理感受——“你一定在想，要是随时想玩就能玩，那就好了。”（正面案例）\u003c/p>\u003cp>【适用边界】需要提醒大家的是，在有些紧急情况发生的时候，比如危及孩子自身或他人的人身安全，就需要马上进行限制，而不需要按照这样的4个步骤来操作。\u003c/p>\u003cp>比如，你看到二宝抢夺大宝的玩具，大宝很生气，要把二宝推倒，这时你就可以马上说：“不能推妹妹！” 首先制止大宝的行为，然后再同理他的感受：“妹妹抢你的玩具，你真的很生气。”\u003c/p>","interaction":"\u003cp>请在座的家长朋友回忆一下，孩子曾经出现过某种行为，而你不能接纳，想要限制的经历，比如：孩子一直看电视，不去做作业。\u003c/p>\u003cp>还没有成为家长的朋友也可以回忆一下，对身边其他人想做出限制的场景，比如：你的下属经常上班迟到。 或者其他发生在身边的、你想对某人做出限制的事情。\u003c/p>\u003cp>当时你是怎样对对方表达限制的呢？ 请回忆具体的时间、场合、事由和过程。 怎么说的？ 怎么做的？ 对方又是什么反应？&nbsp;\u003c/p>\u003cp>大家可以先在小组内先分享一下，自己有没有过这样的经历。 每个人不超过1分钟的时间。\u003c/p>\u003cp>有没有哪位朋友愿意分享一下他的这样一个经历呢？ 您可以吗？\u003c/p>\u003cp>\u003cstrong>【学习者案例记录1】\u003c/strong>\u003c/p>\u003cp>“刚好发生在昨天晚上，我们家小朋友在看电视，我当时在厕所里面洗脚，我就让他在看电视的这个时候和我一起把脚洗了，我想的是顺便嘛，免得后面又叫他去洗。 我就让他过来，他当时就不是很情愿。 我都叫了他有1分钟了，他还在看，然后我就强行把他拖到厕所里面去把脚洗了。”\u003c/p>\u003cp>大家都已经了解了吉诺特博士建议的表达限制的4个步骤，那么想一想，针对之前你对孩子或其他人做出限制的事情，假如重新回到当时的情境里，按照这4个步骤来，你可以怎么做？ 请想一想，然后在小组内轮流分享。每人1-2分钟时间。\u003c/p>\u003cp>现在我想邀请一位朋友来跟大家分享一下，有请——\u003c/p>\u003cp>\u003cstrong>【学习者案例记录2】\u003c/strong>\u003c/p>\u003cp>“我的这个场景是针对小孩吃饭，跟我的公公婆婆之间。 他们为了让小孩吃饭，会开着电视，还喂饭，但我觉得这个习惯是不好的。 我的处理方式就是首先安静下来，肯定他们为小孩好的初衷，并且表示感谢，肯定他们的付出。 第二个环节‘指出限制’我会再次明确我的底限——吃饭应该是专注的，而不是通过转移注意力来达到目的。 第三是给予选择，如果你们没办法来引导、也不忍心的话，就由我来规范小朋友吃饭，也请他们尊重我。 有不同意见可以沟通，但是不能触碰底限。 最后一个环节‘同理感受’，我会再次强调，我知道他们可能会担心，但是请给我时间，一定会看到效果的。”\u003c/p>\u003cp>非常清晰的4个步骤，是想对自己的父母，在孩子吃饭的这个问题上进行约束。 谢谢分享！\u003c/p>\u003cp>今天向大家介绍了海姆.吉诺特博士关于表达限制的建议，分为4个步骤——\u003c/p>\u003cp>1.表达愿望；\u003c/p>\u003cp>2.指出限制；\u003c/p>\u003cp>3.给予选择；\u003c/p>\u003cp>4.同理感受。\u003c/p>\u003cp>希望在各位对孩子或其他人进行行为约束的时候有所帮助，能够让对方更愿意配合，从而避免冲突、争取合作。\u003c/p>\u003cp>我的分享到此结束，谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543507387000,"updated_at":1543759938000,"ria":true},{"id":3991,"topic":"打造小小的理财师","learn_goal":"在跟随我完成本次RIA现场学习后，学习者能够通过三个步骤引导","remark":"金钱就像权力，对于孩子来讲没有丝毫经验，很容易处理失当。为人父母我们只要正确引导，确定使用范围，定期与孩子商讨，相信各位宝爸宝妈定能培养出小财童。","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"贺楚瑜","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"大家好！我是今天的拆书家贺楚瑜。今天我们要聊的话题是“孩子，我们陪你快乐成长系列之 培养小财童”。\r\n首先我们进行【分组】活动前了解到，各位均已是孩子的父母，稍后的讨论我们就按照就近原则，每两人一组，共5组的方式进行讨论。\r\n目标：在跟随我完成本次RIA现场学习后，学习者能够通过三个步骤引导孩子合理使用零花钱。","ratings_count":0,"texts":[{"id":6943,"quote":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够通过三个步骤引导孩子合理使用零花钱。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天我带领大家拆的书名是《孩子，把你的手给我》，作者：【美】海姆.G.吉诺特\u003c/p>\u003cp>F: 吉诺特博士的这本著作——它彻底改变了父母与孩子的沟通方式，在这个领域，这是一本革命性的著作。父母可以帮助孩子可为一个品质高洁的人，一个有着怜悯心，敢于承担和义务的人，一个有勇气、充满活力、正直的人\u003c/p>\u003cp>A:畅销美国500多万册的教子经典，以31种语言畅销全世界，彻底改变父母与孩子沟通方式的巨著。\u003c/p>\u003cp>本书在长达一年多的时间里高居美国各大图书排行榜榜首，并陆续被翻译成31种语言畅销很多国家。\u003c/p>\u003cp>B:如果你还在纠结“熊孩子”给自己带来的苦恼，这本书教你如何引导熊孩子不再那么熊；如果你家熊娃经常让你情绪高昂，来看这本书，它教你一些方法如何处理我们自己的情绪；如果作为父母，你在犹豫如何给孩子合理零用钱，来看这本书，这本书会给你不一样的启发......\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>原书第91页\u003c/strong>。\u003c/p>\u003cp>零用钱不应该是作为对好的行为的奖赏或者做家务的报酬来付给孩子。它是一种教育手段，有明确的目的：给孩子提供使用金钱的经历，从中锻炼孩子选择和承担责任的能力。因此，对零用钱实施监督就完全达不到零用钱的目的了。我们所需要做的是，【HOW】制定一个大体的方针，规定零花钱的支出范围：请朋友吃饭，送朋友礼物、午饭、学校用品等等。随着孩子年龄的增长，零用钱的数量也要增加，以应付额外的开支和花费，例如：俱乐部会员会费、娱乐消费、衣物饰品等等。有些孩子控制不好预算，一拿到零用钱很快就花了很多。对这种零花钱的滥用行为，父母应该和孩子商讨，用一种像处理公事的态度，这样才能得到双方都同意的解决办法。还是说这个花钱太快的问题，可能需要把零用钱分成几批给孩子，一周两次或更多次。零用钱本身不应该成为悬在孩子头上的大棒，对孩子施加压力，让他取得好成绩，或者变得听话。父母也不应该在气头上随意停发零用钱，或者一时高兴，随意增加零花钱。对于这样的安排，即使是孩子也不会感到舒服。就像下面这件趣事显示的一样：\u003c/p>\u003cp>妈妈：你一直表现很乖，给你些钱去看电影。\u003c/p>\u003cp>儿子：你不必再给我钱了，我不要任何东西，也会很乖的。\u003c/p>","explains":"\u003cp>在当下 (停顿)，我们很多职场父母由于没有太多的时间陪孩子，便常常会把对孩子的担心和歉疚，转化到多给孩子零花钱上来，因此，孩子的腰包就鼓了起来，花起钱来也毫不心疼。家长给孩子零花钱的初衷，一是希望孩子在父母不在身边的时候，从某种意义上说口袋里有一些钱，就等于多一些安全保障；二是希望孩子能把钱花在该花的地方。但是，很多孩子领会不到父母的意思，他们会把自己的零花钱花在零食、电脑游戏等一些无关紧要的事上，这不仅使孩子养成了滥用金钱的习惯，有时还成了孩子犯错的根源。\u003c/p>\u003cp>做为父母，这事到底要怎么办呢？怎样引导？\u003c/p>\u003cp>当然也有父母会说，哪有那么闹心，给孩子一个账本就好了。也有父母认为，小孩子不需要零花钱，需要什么跟家里说，家长买即可。真的是这样吗？\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>或许确实有部分可以做到。但是真的给她一个账本就行吗？如果孩子拿到账本并不知道账本该记录些什么，或如何记录，这又有什么意义呢？也有父母认为，孩子不需要零花钱，这又会有什么不良影响？当今的社会，孩子没有金钱管理的经历，她会怎么样？将来离开父母前往异地学习，没有丝毫金钱管理经历的她，又会怎么样？\u003c/p>\u003cp>教育家们认为：父母应该让孩子接触金钱世界，给孩子适当的零花钱，并指导孩子如何使用它，这对孩子的成长是非常有利的，它能培养孩子的理财能力。其中的关键是父母在孩子零花钱的使用上，如何对孩子进行正确引导。原文片段里面提到三种方法:\u003c/p>\u003cp>一是，明确花钱的范围，譬如约定每月零花钱用于父母不在身边的时候急用开支，朋友之间生日礼物互赠等；\u003c/p>\u003cp>二是，给孩子准备一个账本，让他学习记录每一笔开支，定期和孩子翻阅账本，对不合理的开支一起商讨，寻找代替方案，对每月合理开支且有结余的情况予以奖励。\u003c/p>\u003cp>三是，分批次的给孩子零花钱，让孩子逐步管理。\u003c/p>\u003cp>听起来是不是蛮简单的呢？\u003cbr>\u003c/p>\u003cp>那孩子的零花钱什么时候给？怎么给？\u003c/p>\u003cp>金钱就像权力，对于没有经验的人来说，很容易处理失当。最好从很少的量开始给起，然后再随着时间慢慢调整，这要比一次给孩子很多钱，增加他的负担要好得多。当孩子开始上学，学会了数钱和找零钱时，就应该给孩子零用钱了。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：下面我们来想象一下，某一天你发现，孩子一次性把半年的零花钱花掉了、孩子晚归、或者是孩子把钱送进了网吧、送到了其它娱乐场所，没有孩子的亲，也可以设想下你的另一半或朋友的孩子，请在脑海中勾勒一下今后可能遇到的一个场景。\u003cbr>\u003c/p>\u003cp>【学习着班正话案例记录】\u003c/p>\u003cp>朋友11岁的儿子，在过去每周一，喜欢邀请同学们下馆子，偶尔费用上千元。朋友很苦恼，一方面担忧孩子这种炫富心理，另一方担忧孩子的虚荣心，更多还担忧孩子的金钱观。尤其是一想到再过两天又是周一，作为朋友都能够感受到他的焦虑感随着临近周一逐渐变强，父子关系也随着紧张了起来。\u003c/p>\u003cp>好叻，谢谢分享，情景大家基本都勾勒出来。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：那接下来，请大家结合今天的拆书，思考下，今后在这样的场景里面我们该如何应用今天所拆的方法引导呢。下面请大家在便签纸上写下今后你的行动计划，最好是有步骤的、可操作的、具体的计划。（3分钟后，我们邀请一位伙伴来分享）\u003c/p>\u003cp>【学习者张德中案例记录】\u003c/p>\u003cp>同小组伙伴建议，小班同志可以将今天拆书学习到的方法从以下几个方面分享给他的朋友。\u003c/p>\u003cp>首先，在今晚或明天就合理使用零花钱和孩子正式沟通一次。沟通的内容包括以下几个方面：\u003c/p>\u003cp>\u003cstrong>第一\u003c/strong>：与孩子共同商讨，明确花钱的范围、指定可支配金额区间，多少钱以内可以自己决定，超出多少钱需要和家长沟通；\u003c/p>\u003cp>\u003cstrong>第二\u003c/strong>：正式的给孩子买一个账本，记录下来，什么时间、什么事情、花了多少钱、还剩下多少钱；为了巩固孩子的习惯，刚刚开始的时候每周陪孩子一起检查账本，一起讨论，随着孩子的习惯逐渐稳定，检查账本的周期也随即改为月度。\u003c/p>\u003cp>\u003cstrong>第三\u003c/strong>：鉴于孩子此前的开销金额较大，和孩子约定从此起，零花钱将按每周两次或多次的方式给。逐步调整孩子的花销习惯。\u003c/p>\u003cp>谢谢分享，时间过得很快，即使我们讨论得意犹未尽，鉴于时间的限制。回头咱再群里聊。\u003c/p>\u003cp>【小结】:金钱就像权力，对于孩子来讲没有丝毫经验，很容易处理失当。为人父母我们只要正确引导，确定使用范围，定期与孩子商讨，我相信在座各位定能培养出小财童。\u003c/p>\u003cp>今天的拆书到这里，谢谢大家参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1510458827000,"updated_at":1510467494000,"ria":true},{"id":3070,"topic":"孩子，我们陪你快乐成长","learn_goal":"学会称赞的步骤/如何处理我们自己的愤怒？","remark":"通过学会称赞孩子、学习如何处理我们自己的愤怒，发挥语言的力量陪伴孩子快乐成长、帮助孩子成为一个品质高洁的人，一个有着怜悯心，敢于承担和义务的人，一个有勇气、充满活力、正直的人\r\n","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"贺楚瑜","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是今天的拆书家贺楚瑜，在活动前我了解到在座各位都已经为人父母。今天我们要聊的话题是“孩子，我们陪你快乐成长”。\r\n今天我带领大家拆的书名是《孩子，把你的手给我》，作者：【美】海姆.G.吉诺特","ratings_count":0,"texts":[{"id":5874,"quote":"\u003cp>\u003cstrong>F:\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 吉诺特博士的这本著作——它彻底改变了父母与孩子的沟通方式，在这个领域，这是一本革命性的著作。父母可以帮助孩子可为一个品质高洁的人，一个有着怜悯心，敢于承担和义务的人，一个有勇气、充满活力、正直的人\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>畅销美国500多万册的教子经典，以31种语言畅销全世界，彻底改变父母与孩子沟通方式的巨著。\u003c/p>\u003cp>本书在长达一年多的时间里高居美国各大图书排行榜榜首，并陆续被翻译成31种语言畅销很多国家。\u003c/p>\u003cp>\u003cstrong>B:\u003c/strong>如果你还在纠结“熊孩子”给自己带来的苦恼，这本书教你如何引导熊孩子不再那么熊；如果你家熊娃经常让你情绪高昂，来看这本书，它教你一些方法如何处理我们自己的情绪；如果作为父母，我们不擅长如何鼓励孩子，来看这本书，这本书会给你不一样的启发......\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在遇到孩子需要鼓励和肯定时，不再简单一句很棒称赞她，而是对孩子的努力表现出承认、尊重和理解。\u003c/p>\u003cp>原文片段我将通过微信的方式发送到群里，请看完的伙伴举手向我示意。\u003c/p>\u003cp>原书P30\u003c/p>\u003cp>&nbsp; 如果每个月末，宣称爱我们的人给我们一个评定，我们会怎么想？“如果你得了A，就亲你一下；如果得了B，就拥抱你一下；而如果你的了A+，我就会很爱你。”我们会感到心烦意乱、情绪低落，而不会觉得被爱。\u003c/p>\u003cp>&nbsp; &nbsp;比较好的方法是：表达中要充满欣喜和赞赏，言辞中要传达对孩子的努力的承认、尊重和理解。\u003c/p>","explains":"\u003cp>嗯，大家都看完了。\u003c/p>\u003cp>称赞包括两个部分：我们对孩子说的话，以及孩子听了我们的话后在心里跟自己说的话。\u003c/p>\u003cp>我们的话应该明确表明我们很喜欢、很欣赏他们的努力、帮助、工作、体谅、创造或者成就，让孩子能对自己的品格有一个现实的看法，像一块有魔法的帆布，这块布虽然不能给孩子提供帮助，但是，能让他们给自己画一幅正面的画像。\u003c/p>\u003cp>\u003cstrong>（强调不那么做的坏处&amp;意译&amp;预防异议）\u003c/strong>\u003c/p>\u003cp>一年级的乐乐，每天早晚我接送她上学，有一天放学：\u003c/p>\u003cp>乐乐：“妈妈，我今天的数学试卷得了94.5分”\u003c/p>\u003cp>妈妈：“嗯，宝贝你真棒。”\u003c/p>\u003cp>孩子安静的坐在旁边玩她的，没有再就此话题深聊。接下来几天又有一次数学考试，数学试卷发了乐乐不再和妈妈说，而是老师给妈妈来电\u003c/p>\u003cp>老师：“乐乐妈妈，孩子的两位数加分、减法，方法她此前会，在今天的考试中孩子全错，还说不会，在学校已经教过一遍回家你再指导下”\u003c/p>\u003cp>在上面这个例子里，我对乐乐的回应，简单、笼统的给了孩子一个回复“你真棒”。\u003cem>\u003cstrong>【预防异议】\u003c/strong>\u003c/em>\u003cstrong>在这里有人可能就会问我，表扬孩子真棒，不也是称赞和欣赏，何必要思考得如此周全，多麻烦\u003c/strong>。是的，感觉上确实会很显得麻烦，事实上，这些麻烦是非常有必要的。通过接下来考试中老师和我的沟通情况，不难发现孩子从妈妈那并没有获得所谓的赞赏或鼓励，以及因努力获取到成功带来的愉悦感受，相反孩子感受到的是，这个考试不那么重要。\u003c/p>\u003cp>\u003cstrong>\u003cem>（细化行动建议、案例、预防性讲解）\u003c/em>\u003c/strong>\u003c/p>\u003cp>反过来，通过今天这个片段的行动建议，我们可以这样做，第一步：通过语言先表达我的感受，让孩子感受到尊重；第二步：通过言辞对孩子的努力进行承认，让孩子感受到理解。\u003c/p>\u003cp>下面我们通过案例来看看，孑然不同的效果：\u003c/p>\u003cp>乐乐：“妈妈，我今天的数学试卷得了94.5分”\u003c/p>\u003cp>妈妈：“嗯，宝贝，听到这个消息妈妈好开心哦。\u003c/p>\u003cp>我看到你通过自己的努力，进步了，这一次的分数比上次高了3分喔，跟妈妈说说具体哪些地方有进步”\u003c/p>\u003cp>接下来，孩子就会喋喋不休的接话，.... ...&nbsp;\u003c/p>\u003cp>到这里，你还会觉得对她努力的行为承认并进行欣赏和称赞的描述很啰嗦？\u003c/p>\u003cp>我们是不是会有所收获了呢，显然，你发现当你这样通过描述看到的事实并予以回应。可以想象得到，孩子听到这样的称赞后，开心快乐的继续和母亲进一步沟通，并且在以后的学习中认真的对待考试这个过程，同时也会知道进步所代表的是什么。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:激活经验：\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（接下来的话，我们分两个组，左边一组、右边一组）请大家回想最近我们的孩子在日常生活、或学习中，有没有过孩子取得了某方面的进步，或者学会了点什么，兴奋的两眼看着你，期待着你鼓励或肯定的场景？当时的情景是怎样的？你们是怎么沟通的？请想一想，稍后在小组内分享。\u003c/p>\u003cp>\u003cem>（思考中... ... ）\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cbr>\u003c/em>\u003c/p>\u003cp>下面有请敏君为我们分享：\u003c/p>\u003cp>学习者敏君案例记录：\u003c/p>\u003cp>场景：一天早上，我起床，起床之后看到我的3岁和5岁的两个小侄子，在楼上在他们妈妈的带领下刷牙洗脸，两个小家伙打开水龙头接水，然后很仔细的用牙刷，用一种很正统的方法来刷牙。\u003c/p>\u003cp>我当时就说：“德德、超超你们两个这么早起床，真棒，会自己刷牙了。”\u003c/p>\u003cp>当时的场景看起来很醒目，很棒，当时就用了这样个词语评价。\u003c/p>\u003cp>谢谢敏君的分享，她当时的场景就是早上起床看到侄子自己刷牙，就给了个宝贝真棒的肯定。\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应】\u003c/strong>那咱们再看看，如果运用“称赞的技巧”，你会怎样做？\u003c/p>\u003cp>敏君分享：德德、超超看你们两个刷牙就知道按照顺序，刷门牙的时候是上下动的，里面的牙的时候是左右拉的，看，你们多会刷牙。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>嗯，是的，通过这个片段以后我们敏君分享的这个案例在称赞的技巧上已经发生了一个巨大的变化，孩子已经知道了上下刷、左右刷是不一样的，不但可以保护我们的牙齿，同时还可以可以坚持我们认真做事情的习惯。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5875,"quote":"\u003cp>两个片段过渡语：\u003c/p>\u003cp>孩子的话题，是我们每一个父母锲而不舍、喋喋不休的话题。孩子成长快乐，是我们每个父母的愿望。赞赏让我们的孩子感觉到自己被尊重，被理解。但是孩子的成长不仅有需要赞赏的时光，还有激怒我们的时光。\u003c/p>\u003cp>下面，我们来探讨“如何处理我们自己的愤怒”心情平静的与孩子相处。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在与孩子一起出现激动情绪时，通过明确定义、加强愤怒的强度、解释我们生气的原因三种方法平复我们的情绪以及引导孩子出现我们希望的行为。\u003c/p>\u003cp>原文片段我将通过微信的方式发送到分享群，看完的伙伴请给我示意。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>原书P43\u003c/p>\u003cp>&nbsp; &nbsp;处理激动的情绪的第一步是给它们明确的定义。这可以提醒相关的人改正或者采取预防措施。这样做的第一步是使用人称代词“我”：“我觉得讨厌。”“我觉得被激怒了。”\u003c/p>\u003cp>&nbsp; &nbsp;如果简短的陈述和拉长着的脸并没有产生效果，那么采取第二步，在表达时加强愤怒的强度：\u003c/p>\u003cp>&nbsp; &nbsp;“我生气了。”\u003c/p>\u003cp>&nbsp; &nbsp;“我很生气了。”\u003c/p>\u003cp>&nbsp; &nbsp;“我非常非常生气了。”\u003c/p>\u003cp>&nbsp; &nbsp;“我气急了。”\u003c/p>\u003cp>&nbsp; &nbsp;有时，仅仅表达出我们的感受就能让孩子停止不当的行为。但是，有时候，可能需要采取第三个步骤：解释我们生气的原因，说出我们内心的想法，以及我们希望的行为。\u003c/p>","explains":"\u003cp>愤怒就像一场飓风，是生活中的一部分，我们不得不承认，而且还要准备好。对父母来说，愤怒是一种代价很高的情感，为了物有所值，没有益处的话，还是不要随便发怒的好。发怒呢不应该招来更多的话，就像药物不应该比疾病更糟糕一样。怒气应该以某种方式表达出来，这种方式应该能够使父母得到一定的解脱和轻松，给孩子一些启示，对任何一方都不应该有副作用。\u003c/p>\u003cp>\u003cstrong>【细化行动步骤/意译】\u003c/strong>\u003c/p>\u003cp>遇到娃“熊”的时候，“淘气的时候”，我们怒火冲天，怎么办呢？怎么办呢？\u003c/p>\u003cp>第一步，我们先觉察下自己当下的感受，是焦虑呢？难过呢？还是生气了?&nbsp;\u003c/p>\u003cp>通过“我”语句表达出来，我觉得生气了。\u003c/p>\u003cp>第二步，表达时加强愤怒的强度\u003c/p>\u003cp>告诉对方“我很生气，生气得手和脚都发抖了，胸口好痛”\u003c/p>\u003cp>第三步，向对方解释我生气的原因，我内心的想法是怎样的？我希望你的行为怎么样？\u003c/p>\u003cp>以我家乐乐跟随我们一起参加活动，她在旁边书写作业为例，我们来看下这个片段\u003c/p>\u003cp>孩子像往常一样和我们一起活动，我们拆书，她在旁边写作业。\u003c/p>\u003cp>突然间，乐乐跑过来说：“妈妈，我作业写完了。”她狠高兴，“妈妈我作业写完了”\u003c/p>\u003cp>然后，我轻轻的走到她的座位旁，对照着作业登记本本检查发现孩子的作业80%都没完成。\u003c/p>\u003cp>这个时候我拉长着脸，孩子没当回事。这个时候我进行第一步说到：“乐乐，我感觉很生气”\u003c/p>\u003cp>乐乐依然坐在老板椅子上摇摇晃晃\u003c/p>\u003cp>然后我就开始第二步：“乐乐，我感觉非常生气，气得妈妈胸口好痛，就像一团火烧到了脑袋上一样，我要拿东西砸人了”\u003c/p>\u003cp>此刻，孩子坐直在旁边，看着我，但是依然不知所措\u003c/p>\u003cp>说实话，那一刻的我是已经非常非常生气了，但是想着这个片段的第三步，然后我就运用第三步说：“宝贝，明天我们就考试了，今天是我们这个学期最后一次作业，我们一起看看今天的作业主要都有什么，哦，有错题复习、错题整理，一起作业。妈妈希望你认真的完成今天的作业，（停顿）你看行不行呀，等会妈妈这边工作结束了，你的作业也完成了，等会我们一起回家，你觉得怎么样？”\u003c/p>\u003cp>很显然，这个方法很凑效，孩子马上就平静下来安安静静的准备开始一项一项认认真真的写作业，通过以上案例，我们看到我在一步一步的运用处理激动情绪的三步法，我自己的情绪逐渐抚平的过程，孩子的行为也逐渐的朝着我需要的方向前进。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3促动参与：\u003c/strong>\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（下面我通过一个场景来实践下我们今天这个片段，案例是这样的）出差回来的你刚刚步入家门，爷爷向你告状：\u003c/p>\u003cp>爷爷：“哎呀，这孩子调皮死了，管不了了，她把你房间弄得乱起八糟的，把你的化妆品全部都弄撒了，首饰盒里面的贵重首饰也拿出来玩，你看看有没有什么弄丢的，有没有什么东西不在的”。\u003c/p>\u003cp>然后你就跑到房间一看，床上乱七八糟的，然后你的化妆品不管是你兰蔻还是资生堂都已经被小祖宗捣腾得到处都是，然后首饰盒里面你心爱的几件首饰也不翼而飞了。\u003c/p>\u003cp>作为父母的你，接下来怎么样处理？你要怎么样收拾残局，怎样跟孩子沟通。\u003c/p>\u003cp>下面我们左边一组、右边一组，两组的伙伴分别讨论下，并编写剧本，稍后的话我们选出两位代表，分别扮演你和孩子来和大家分享。\u003c/p>\u003cp>（讨论）\u003c/p>\u003cp>....\u003c/p>\u003cp>参与者A:这场面好刺激，一般都会抓狂\u003c/p>\u003cp>参与者B：肯定抓狂\u003c/p>\u003cp>......\u003c/p>\u003cp>我：抱着她表扬一通\u003cstrong>\u003cem>【回应与反馈】\u003c/em>\u003c/strong>\u003cbr>\u003c/p>\u003cp>参与者C：这不是有问题吗？\u003c/p>\u003cp>参与者A：这就有问题了\u003c/p>\u003cp>我：抱着她表扬一通，“宝贝，你创造了这么多的变化呀，给妈妈太多惊喜了”\u003c/p>\u003cp>参与者：“你们家乐乐没做过这个事吧”\u003c/p>\u003cp>我：做过，一两岁的时候，我记得把我的高跟鞋呀不管多贵的，那会她刚学走路，成天穿着在家里一遍一遍的走.\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;后面还干过比较刺激的事，我的单只版羽毛球拍被小祖宗搞弯了\u003cbr>\u003c/p>\u003cp>.........\u003c/p>\u003cp>【扮演分享】下面有请敏君和雯雯给我们大家扮演下她们的剧本：\u003c/p>\u003cp>妈妈（语气高昂）：呀( ⊙ o ⊙ )！家里怎么这么乱。\u003c/p>\u003cp>宝宝：不啃声\u003c/p>\u003cp>妈妈（语气稍平静）：怎么回事，气死我了\u003c/p>\u003cp>宝宝：不啃声\u003c/p>\u003cp>妈妈：是你做的吗，是你干的吗\u003c/p>\u003cp>宝宝：可能是吧\u003c/p>\u003cp>妈妈：可能？\u003c/p>\u003cp>宝宝：可能\u003c/p>\u003cp>妈妈：我想不出除了你还有谁\u003c/p>\u003cp>宝宝：如果没有别人就是我了\u003c/p>\u003cp>妈妈：那也就是说就是你做的咯，你知道吗，妈妈看到这个好生气呀，非常非常的生气。\u003c/p>\u003cp>你知道这个场面看起来简直是糟糕透顶了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;你看，我刚买的化妆品，刚叫人帮我从香港带回来的，经常要用到的，现在全没了，还花了我好多钱，还有再看看这首饰盒里面，这些东西，妈妈平常都经常带的，\u003cbr>\u003c/p>\u003cp>宝宝：嗯\u003c/p>\u003cp>妈妈：也不见了，你知道那个有多贵吗？\u003c/p>\u003cp>宝宝：不知道\u003c/p>\u003cp>妈妈：其中有一枚戒指还是你爸爸送给我的，结婚戒指\u003c/p>\u003cp>宝宝：叫爸爸再送你一个呗\u003c/p>\u003cp>妈妈：你说的轻巧，那意义很重要的，你想想，你心爱的东西丢了你生不生气？\u003c/p>\u003cp>宝宝：好像...我有什么心爱的东西呀？\u003c/p>\u003cp>妈妈：你的娃娃，你的娃娃我现在把它扔了，你生气吗？\u003c/p>\u003cp>宝宝：不要，不能扔\u003c/p>\u003cp>妈妈：你会不会不开心？\u003c/p>\u003cp>宝宝：嗯\u003c/p>\u003cp>妈妈：那你能理解妈妈现在的情绪吗？\u003c/p>\u003cp>宝宝：嗯\u003c/p>\u003cp>妈妈：你看到妈妈现在都发抖呀，我都气得站都站不稳了，哎！\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;你知道自己做错了吗？\u003cbr>\u003c/p>\u003cp>宝宝：我只是觉得好玩而已\u003c/p>\u003cp>妈妈：好玩？\u003c/p>\u003cp>宝宝：是呀\u003c/p>\u003cp>妈妈：你为什么会觉得好玩？\u003c/p>\u003cp>宝宝：你看你有那么多瓶瓶罐罐，我一瓶都没有，我只是拿来擦擦手而已\u003c/p>\u003cp>妈妈：为什么要擦手？擦手有什么好处？\u003c/p>\u003cp>宝宝：干呀，擦了之后就滑滑的\u003c/p>\u003cp>妈妈：来，妈妈看看你的手\u003c/p>\u003cp>宝宝：嗯，\u003c/p>\u003cp>妈妈：确实是，现在天气冷了，那妈妈下次给你买一瓶BB霜放你床头，好吗？\u003c/p>\u003cp>宝宝：我终于有我自己的了\u003c/p>\u003cp>妈妈：那以后再也不要动妈妈的化妆品了，好吗？\u003c/p>\u003cp>宝宝：好的\u003c/p>\u003cp>妈妈：可是，还有一件事情，这些首饰究竟去哪里了，你能帮妈妈想一想吗？\u003c/p>\u003cp>宝宝：...思考....\u003c/p>\u003cp>妈妈：具体藏到哪个角落去了呢？\u003c/p>\u003cp>宝宝：哦，我记得了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;前天，小丽来我们家，她说刚喝了喜酒，那个新娘子脖子上挂着好多项链，她也想挂一个，我就拿了你的几根项链给她带，那个项链应该.应该..\u003cbr>\u003c/p>\u003cp>妈妈：然后呢？\u003c/p>\u003cp>宝宝：后来我就忘了这回事了\u003c/p>\u003cp>妈妈（惊愕）：她带回家啦？\u003c/p>\u003cp>宝宝：不知道，我打电话问问她\u003c/p>\u003cp>妈妈：好\u003c/p>\u003cp>（宝宝跑到一侧开始给小丽打电话..\u003c/p>\u003cp>“小丽，前几天我那些项链放到哪里了”.“哦，在放颜料的盒子里”.“哦，我去看看”...）\u003c/p>\u003cp>宝宝：妈妈，妈妈你看，我找到了，我找到了\u003c/p>\u003cp>妈妈：嗯，不错不错，这几条终于看到了。\u003c/p>\u003cp>对了，妈妈那个戒指呢\u003c/p>\u003cp>宝宝：戒指？就是圆圆的那个，是吧？\u003c/p>\u003cp>妈妈：是呀。\u003c/p>\u003cp>宝宝：圆圆的，我想下是谁拿了，哦，是雨轩。雨轩说她家的雪人鼻子好长，可以挂个小圈圈，所以我就送给她了。\u003c/p>\u003cp>妈妈（惊）：你送给她了？\u003c/p>\u003cp>宝宝：你说过好朋友要互相帮助，互相分享嘛\u003c/p>\u003cp>妈妈：那妈妈现在很想要回来怎么办？\u003c/p>\u003cp>宝宝：那就要回来咯，雨轩就住我们对面，我去找她看看能不能要回来\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;... ...&nbsp;\u003cbr>\u003c/p>\u003cp>宝宝：妈妈，妈妈你看，原来雨轩还挂在雪人的鼻子上，我把那个雪人拿回来了，你看漂不漂亮？雪人的鼻子是挂个全球是不是很好看呀？\u003c/p>\u003cp>妈妈：是很好看。要是带在我的手上更好看\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;你看看，给妈妈带下是不是更好看\u003cbr>\u003c/p>\u003cp>宝宝：嗯，是的。不过我觉得妈妈带不带戒指都好看。\u003c/p>\u003cp>妈妈：这句话妈妈爱听\u003c/p>\u003cp>宝宝：嗯，终于看到妈妈不那么生气了。\u003c/p>\u003cp>妈妈：嗯？不对喔，还有一对耳环\u003c/p>\u003cp>宝宝：雨轩还有一根猴子，猴子的耳朵好大，给它带上耳环特别可爱，我去拿回来\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;妈妈，妈妈，你看，你的耳环。\u003cbr>\u003c/p>\u003cp>妈妈：现在都拿回来了，嗯，妈妈就放心了。\u003c/p>\u003cp>宝宝：嗯\u003c/p>\u003cp>妈妈：嗯，妈妈现在就想起，你这一次随意就把妈妈这些东西送给别人，那以后你会不会把你爸爸的东西也送给别人呢？\u003c/p>\u003cp>宝宝：可是我的好朋友需要呀，那怎么办呢？\u003c/p>\u003cp>妈妈：那你说我把你的东西随便的送给其它人，你觉得合适吗？\u003c/p>\u003cp>宝宝：不合适。\u003c/p>\u003cp>妈妈：那要怎么做才合适呢？\u003c/p>\u003cp>宝宝：那件东西必须是我自己的我才有权利送给其它人，即使送也要看情况。\u003c/p>\u003cp>妈妈：那你的意思是，是先问你的意思，对不对，征求你的意见\u003c/p>\u003cp>宝宝：是我的东西\u003c/p>\u003cp>妈妈：嗯，蛮聪明的，以后爸爸妈妈的东西要先征求爸爸妈妈的意见，即使要送也要自己送，除了爸爸妈妈的东西其它人的也一样对吧。\u003c/p>\u003cp>宝宝：嗯。\u003c/p>\u003cp>妈妈：你自己也不喜欢别人乱动你的东西\u003c/p>\u003cp>宝宝：嗯,嗯。\u003c/p>\u003cp>妈妈：宝贝，你这样做就是棒。\u003c/p>\u003cp>（鼓掌）\u003c/p>\u003cp>好叻，谢谢两位的精彩分享。剧本很有意思，妈妈和宝贝都非常投入。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：接下来，设想一下，今后咱家宝贝在沙发上画画、穿着鞋子在床上玩耍、拿你心爱的首饰与小朋友间玩耍，遇到类似怒发冲冠的事情，你想起了今天的片段，我们运用“如何处理我们的愤怒”这三个步骤来解决的话，你会怎么做？请在便签纸上写下你的具体行动计划。\u003c/p>\u003cp>学习者敏君案例分享记录：\u003c/p>\u003cp>下次我如果碰到孩子的一些行为让我不能接纳生气的话，我就第一步：我会很明确的让孩子知道，我是生气了，而且，不仅仅是让她知道我生气，我会说出我内心的想法，比如我会说有一次我的孩子把墙壁画的脏脏的，我是这么跟他说的：“宝贝，当我看到这么白的墙壁画成这样，我很生气，生气急了，真想教训你一下。不过，你认为你现在怎么做我不会那么生气呢”很快孩子就意会到他要怎么做，把墙壁擦得干干净净。后面我们就达成了。\u003c/p>\u003cp>谢谢敏君的分享。\u003c/p>\u003cp>今天我们的拆书活动呢，因为有剧本促使我们今天的拆书更活跃、更生动，大家看起来也拆得比较快乐。今天的活动我们也就接近尾声，以后我们可以用到的就是，请大家记住“称赞的表达中要充满欣喜和赞赏，言辞中要传达对孩子的努力的承认、尊重和理解。”我们积极的察觉自己的感受，并主动表达出来，再施之以引导孩子的不当行为会逐渐减少。今天的活动就到此结束，谢谢大家。\u003cstrong>【强有力的结尾】\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1498801474000,"updated_at":1503137096000,"ria":true},{"id":888,"topic":"如何正确与孩子沟通","learn_goal":"学会针对孩子的感受做出反应而不是针对其行为","remark":"","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"安静","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"如何有效与有负面情绪的人顺利沟通？\r\n通过拆书学习我们可以做到在沟通中，1、觉察到对方的情绪；2、表示理解或认同对方及其情绪；3、在上面基础上给出建议达到沟通目的。","ratings_count":0,"texts":[{"id":2739,"quote":"\u003cp>\u003cstrong>沟通针对孩子的感受作出反应\u003c/strong>，而不是针对其行为。\u003c/p>\u003cp>和孩子沟通要建立在尊重的基础之上，另外，还要有技巧：需要同时照顾孩子和父母的自尊；\u003cstrong>要先说出表示理解的话，然后再提出建议或意见。\u003c/strong>\u003c/p>\u003cp>埃里克，九岁，怒气冲天地回到家里，他的班级本来打算去野餐，但是下雨了。他的父亲决定用一种新的方法。以前他总是说一些让事情变得更糟的话：“天气不好，哭是没有用的。以后会有玩的时候。又不是我让它下雨的，你为什么要冲我发火？，但是，这一次，埃里克的父亲没有这么说，他心里想：我的儿子对错过了野餐反应很强烈，他很失望，他用怒气向我表现他的这种失望，我可以帮助他的，只要对他的感受表示理解和尊重于是他对埃里克说“你看上去很失望。\u003c/p>\u003cp>埃里克：我当然很失望了。父亲：你已经准备好了一切，该死的却下雨了。埃里克：是的，正是这样。这时，出现了短暂的沉默， 然后埃里克说：“不过，可以以后出去玩：他的怒气看起来消失了，在下午余下的时间里，他都很合作。通常，只要埃里克生气地回家，一家人都会心烦，迟早他会激怒家中的每个成员，直到深夜他终于睡着了，家里才能重回宁静。\u003c/p>\u003cp>这个方法有什么特别之处呢？它在哪些地方产生了作用，当孩子处于强烈的情绪时，他们听不任何人的话。他们不会接受任何意见或安慰，也无法接法接受任何建设性的批评。他们希望我们能够理解他们心里在想什么，希望我们明白在那个特别的时刻他们的心情。而且，他们希望不用完全说出自己的遭遇，我们也能够理解他们。他们的情绪只会透露二点点，我们必须猜出剩下的部分。\u003c/p>\u003cp>如果一个孩子跟我们说：“老师冲我嚷嚷”我们不必再问更多细节，也无需说：“你干了什么事让老师这样对你？如果老师冲你嚷嚷，那你一定做了什么。你做了什么？”我们甚至不必说：“哦，我很抱歉。”我们需要向她表明我们理解她的尴尬、痛楚和气愤。\u003c/p>\u003cp>安妮塔9岁，—天回家吃午饭生气的说：“我不要回学校了。”妈妈：“你看上去很烦，能告诉我怎么了吗？安妮塔：老师把我的卷子撕了，我那么努力地答题，她居然只看了一眼就撕了。妈妈：没有得到你的允允许吗？怪不得你这么生气呢！安妮塔的妈妈没没有发表任何评论疑问。她知道，\u003cstrong>如果她想帮助女儿消除怒气，就必须带着理解和同情跟她说话。\u003c/strong>\u003c/p>","explains":"\u003cp>原文讲述了当孩子或他人处于强烈的负面情绪时，我们不要急于提供的建议、批评、意见或安慰都不会产生效果。很多人在孩子出现状况时，不能觉察到他的情绪，而是一味指责、抱怨或则直接给建议。有时候我们即便感受到她的情绪，也可能不一定立马见效。但是，我们应该坚持做，让孩子感受到我们特别理解他和他现在的状态，这对孩子心理的安抚作用是非常大的，让孩子非常有归属感。\u003c/p>\u003cp>可以在尊重的基础上，父母做到以下两点可以让孩子安静下来，与我们进行沟通。\u003c/p>\u003cp>1、首先先根据观察和感觉说出他人感受的话（你看起来有点：愤怒、着急、闷闷不乐、生气）\u003c/p>\u003cp>2、&nbsp; 直到对方感觉到你理解他的情绪后，再提建议\u003c/p>\u003cp>\u003cstrong>异议：\u003c/strong>听到这里，大家可能会问，你这也太简单了吧？大家觉得今天的内容简单吗？然而往往我们在生活中很多时候很容易看到别人处于某种状态，就会给出建议。就像文中的例子一样：老师把我试卷撕了，好多时候家长会说肯定是你调皮了，或不听话了……引发孩子更加郁闷的叹息。\u003c/p>\u003cp>例子：\u003c/p>\u003cp>书中有个例子，其中一个是父亲采用了理解孩子感受再给建议的方式，避免了以前出现过的生气的小孩子，把家里每个人都搞的很心烦，直到他睡着了，家里才安静。这个例子是采用了正确的两步骤得到了很好的结果。&nbsp;\u003c/p>","interaction":"\u003cp>\u003cbr>在工作或生活中大家有没有直接没有处理对方的情绪，直接给建议的经历呢？&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>香春：\u003c/strong>放假回到家里，妈妈跟自己说起她跟爸爸之间的矛盾，每次自己一听就不耐烦了，告诉妈妈：别理他，我把就是那样的人！觉得自己特别简单粗暴，没有照顾到妈妈的心情及妈妈的倾诉。\u003c/p>\u003cp>\u003cstrong>崔颖颖：\u003c/strong>在工作中有个客户，她们部门在公司的位置不是很重要，也不被重视，经常有做了好多事突然被领导否定或吵的情况，她非常郁闷。和她通电话时耐心的倾听了她的情绪，让她感到被理解是很好的倾诉对象。后来才给建议，这个客户对自己非常忠诚，一有什么培训需求，总是第一时间联系颖颖。\u003c/p>\u003cp>如果有这样一个场景，你回到家，妈妈跟你忧伤的说你爸爸的很多不对，你如何做让妈妈情绪变好，且能听你的建议？\u003c/p>\u003cp>香春：先耐心的听妈妈说，然后告诉她：“妈妈我能感受到当时很生爸爸的气，确实他那样做挺让人伤心的。等他回来我跟爸爸再谈谈，希望他能够认识到对您的伤心，希望他以后不这样做了。\u003c/p>\u003cp>惠璞：跟父母沟通听他们说就行了，就算装也要装着让他们觉得我们在听，这样他们能感受到我们在听他们说，能理解他们的感受，他们也就没有情绪了。感觉到他们感受到理解他们了，就再表达自己的观点：“确实是有时候情绪上来会做过分的事，过去的就过去了，但一家人还是自己给自己亲！”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473645172000,"updated_at":1473645172000,"ria":true}]};